window.ASISTENT_ZA_MATURE_CROATIAN_WRITING={"version":2,"rubrics":{"summary-2023":{"id":"summary-2023","label":"Službena rubrika za sažetak","source":{"title":"NCVVO Ispitni katalog za državnu maturu 2022./2023. - Hrvatski jezik","url":"https://www.ncvvo.hr/wp-content/uploads/2022/09/HRV-2023a.pdf"},"criteria":[{"id":"content","label":"Sadržaj","maxScore":3,"levels":[{"score":3,"description":"Navodi autora i naslov, temu, namjenu, autorov stav, osnovne misli i važne pojedinosti; nema suvišnih detalja i uglavnom se služi vlastitim riječima."},{"score":2,"description":"Sadržaj je djelomično potpun ili općenit, uz poneke suvišne pojedinosti ili dijelove prenesene iz polaznoga teksta."},{"score":1,"description":"Tekst uglavnom prepričava, izdvaja samo jednu osnovnu misao ili navodi slabije povezane pojedinosti."},{"score":0,"description":"Ne određuje temu, namjenu i autorov stav, ne izdvaja osnovne misli ili je većinom prepisan."}]},{"id":"organizationStyle","label":"Organizacija teksta i stil","maxScore":3,"levels":[{"score":3,"description":"Ima jasan uvod, razradu i zaključak, logičan slijed, povezane misli te objektivan, jasan i primjeren stil."},{"score":2,"description":"Trodijelna struktura postoji, ali slijed i veze među mislima nisu potpuno jasni."},{"score":1,"description":"Nedostaje uvod ili zaključak, a slijed i povezanost misli slabi su."},{"score":0,"description":"Nema trodijelnu strukturu ni povezane osnovne misli i stil nije primjeren sažetku."}]},{"id":"languageAccuracy","label":"Jezična točnost","maxScore":3,"levels":[{"score":3,"description":"Pravopisno, gramatički i leksički točno."},{"score":2,"description":"Uglavnom pravopisno, gramatički i leksički točno."},{"score":1,"description":"Djelomično pravopisno, gramatički i leksički točno."},{"score":0,"description":"Pravopisno, gramatički i leksički netočno."}]}],"specialRules":["Očekivani opseg je 200-250 riječi; za vrednovanje je dopušteno 180-275 riječi.","Sažetak se ne vrednuje ako ne ostvari barem 1 bod u sastavnici Sadržaj.","Sažetak se ne vrednuje ako tekst nije čitljiv ili je pisan samo velikim tiskanim slovima."]},"school-essay-2023":{"id":"school-essay-2023","label":"Službena rubrika za interpretacijski školski esej","source":{"title":"NCVVO Ispitni katalog za državnu maturu 2022./2023. - Hrvatski jezik","url":"https://www.ncvvo.hr/wp-content/uploads/2022/09/HRV-2023a.pdf"},"criteria":[{"id":"centralThesis","label":"Središnja tvrdnja","maxScore":3,"levels":[{"score":3,"description":"Tvrdnja je jasna i točna, pokazuje temeljito razumijevanje djela i uključuje relevantna književna obilježja."},{"score":2,"description":"Tvrdnja je točna, ali općenita; razumijevanje i izdvojena književna obilježja djelomični su."},{"score":1,"description":"Tvrdnja je vrlo općenita, razumijevanje površno, moguće su činjenične pogreške i izostaju važna književna obilježja."},{"score":0,"description":"Nema razvijenu središnju tvrdnju."}]},{"id":"argumentation","label":"Argumentacija","maxScore":3,"levels":[{"score":3,"description":"Dva ili tri jasna argumenta temeljito objašnjavaju tvrdnju, potkrijepljeni su djelom i cjelovitom analizom ulomka."},{"score":2,"description":"Dva ili tri općenita argumenta djelomično objašnjavaju i potkrepljuju tvrdnju te daju djelomičnu analizu ulomka."},{"score":1,"description":"Jedan razvijen ili više slabih argumenata površno podupiru tvrdnju, uz vrlo površnu analizu."},{"score":0,"description":"Argumentacija izostaje."}]},{"id":"coherence","label":"Povezanost teksta","maxScore":3,"levels":[{"score":3,"description":"Uvod, razrada i zaključak povezani su; odlomci su jasni i logični, a kohezivna sredstva gotovo potpuno uporabljena."},{"score":2,"description":"Tekst ima tri dijela, ali oni nisu posve povezani; odlomci i kohezivna sredstva djelomično su uspješni."},{"score":1,"description":"Tekst ima tri dijela, ali uvod ili zaključak vrlo su općeniti, odlomci nejasni, a povezanost površna."},{"score":0,"description":"Tekst nema trodijelnu strukturu; razrada nije organizirana i rečenice su nepovezane."}]},{"id":"vocabulary","label":"Upotreba rječnika","maxScore":3,"levels":[{"score":3,"description":"Rječnik je širok i primjeren; književni pojmovi rabe se dosljedno i točno, a opće riječi precizno."},{"score":2,"description":"Rječnik je zadovoljavajući i uglavnom primjeren; književni pojmovi rabe se djelomično, a opće riječi uglavnom točno."},{"score":1,"description":"Rječnik je ograničen i često neprimjeren; književni pojmovi rijetki su, a opće riječi samo djelomično točne."},{"score":0,"description":"Rječnik je nezadovoljavajući i neprimjeren; književni pojmovi izostaju, a opće riječi rabe se netočno."}]},{"id":"languageAccuracy","label":"Pravopisna i gramatička točnost","maxScore":3,"levels":[{"score":3,"description":"Pravopisno i gramatički točno."},{"score":2,"description":"Uglavnom pravopisno i gramatički točno."},{"score":1,"description":"Djelomično pravopisno i gramatički točno."},{"score":0,"description":"Pravopisno i gramatički netočno."}]}],"specialRules":["Očekuje se najmanje 440 riječi; za vrednovanje je dopušteno najmanje 396 riječi.","Esej se ne vrednuje ako ne ostvari barem 1 bod u sastavnici Središnja tvrdnja.","Esej se ne vrednuje ako tekst nije čitljiv ili je pisan samo velikim tiskanim slovima."]},"school-essay-legacy":{"id":"school-essay-legacy","label":"Službena rubrika za školski esej starog formata","source":{"title":"NCVVO Ispitni katalog za državnu maturu 2018./2019. - Hrvatski jezik","url":"https://www.ncvvo.hr/wp-content/uploads/2018/10/HRVATSKI-2019.pdf"},"criteria":[{"id":"contentArgumentation","label":"A: Poznavanje i razumijevanje književnoga teksta","maxScore":20,"items":[{"id":"A1","label":"Prepoznaje obilježja polaznoga teksta ili tekstova","maxScore":2},{"id":"A2","label":"Navodi ključne sadržajne podatke i strukturu djela","maxScore":4},{"id":"A3","label":"Razumije i problematizira polazni tekst i djelo u cjelini","maxScore":6},{"id":"A4","label":"Tvrdnje potkrepljuje primjerima i citatima","maxScore":4},{"id":"A5","label":"Sintetizira argumente, stavove i čitateljsko iskustvo","maxScore":4}]},{"id":"composition","label":"B: Povezanost teksta","maxScore":6,"items":[{"id":"B1","label":"Sadržajno oblikuje uvod, razradu i zaključak","maxScore":1},{"id":"B2","label":"Povezuje tvrdnje smisleno i logično","maxScore":4},{"id":"B3","label":"Upotrebljava prikladan stil","maxScore":1}]},{"id":"languageStyle","label":"C: Upotreba standardnoga hrvatskog jezika","maxScore":14,"items":[{"id":"C1","label":"Sintaktička točnost","maxScore":4},{"id":"C2","label":"Pravopisna točnost","maxScore":6},{"id":"C3","label":"Morfološka točnost","maxScore":2},{"id":"C4","label":"Leksička točnost","maxScore":2}]}],"specialRules":["Dopušteno je odstupanje do 10 % ispod zadanoga najmanjeg broja riječi.","Esej se ne vrednuje ako zadatak nije ispunjen, tekst nije u obliku eseja, sadrži nepristojno izražavanje ili crteže, nije čitljiv ili je pisan samo velikim tiskanim slovima."]},"school-essay-2022":{"id":"school-essay-2022","label":"Službena rubrika za školski esej 2021./2022.","source":{"title":"NCVVO Ispitni katalog za državnu maturu 2021./2022. - Hrvatski jezik","url":"https://www.ncvvo.hr/wp-content/uploads/2021/09/HRV2022a.pdf"},"criteria":[{"id":"contentArgumentation","label":"A: Poznavanje i razumijevanje književnoga teksta","maxScore":20,"items":[{"id":"A1","label":"Prepoznaje obilježja polaznoga teksta ili tekstova","maxScore":2},{"id":"A2","label":"Navodi ključne sadržajne podatke i strukturu djela u cjelini","maxScore":4},{"id":"A3","label":"Analizira polazni tekst i povezuje ga s djelom u cjelini","maxScore":6},{"id":"A4","label":"Tvrdnje potkrepljuje primjerima i citatima","maxScore":4},{"id":"A5","label":"Obrazlaže stavove, izvodi zaključak i pokazuje ukupno čitateljsko iskustvo","maxScore":4}]},{"id":"composition","label":"B: Povezanost teksta","maxScore":6,"items":[{"id":"B1","label":"Sadržajno oblikuje uvod, razradu i zaključak","maxScore":1},{"id":"B2","label":"Povezuje tvrdnje smisleno i logično","maxScore":4},{"id":"B3","label":"Upotrebljava prikladan stil","maxScore":1}]},{"id":"languageStyle","label":"C: Upotreba standardnoga hrvatskog jezika","maxScore":14,"items":[{"id":"C1","label":"Sintaktička točnost","maxScore":4},{"id":"C2","label":"Pravopisna točnost","maxScore":6},{"id":"C3","label":"Morfološka točnost","maxScore":2},{"id":"C4","label":"Leksička točnost","maxScore":2}]}],"specialRules":["Dopušteno je odstupanje do 10 % ispod zadanoga najmanjeg broja riječi.","Esej se ne vrednuje ako zadatak nije ispunjen, tekst nije u obliku eseja, sadrži nepristojno izražavanje ili crteže, nije čitljiv, pisan je samo velikim tiskanim slovima ili je potpisan."]}},"exams":[{"id":"hrvatski-2025-ljetni-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2025,"schoolYear":"2024./2025.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2025/06/HRV25prvi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S073.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nKruno Lokotar, Dvopismeni ili nepismeni\nU suvremenome svijetu sve se manje čita, a razloge tomu treba tražiti u intenzivnoj digitalizaciji\nkoja donosi nevjerojatne promjene u živote ljudi, ali i izazove u čitateljskim navikama. Dokazano\nje da čitanje znatno utječe na razvoj mozga, a tehnologija je promijenila način na koji čitamo, što\nposljedično mijenja i mozak.\nIstraživanjem američke neuroznanstvenice Maryanne Wolf, koje je predstavila u svojoj knjizi\nČitatelju, vrati se kući, utvrđeno je da se danas čita više nego ikad prije. Međutim, dominira digitalno,\npovršno čitanje, koje karakterizira brzo prelaženje preko teksta. Takvo je čitanje letimično, odvija se\nu cik-cak figuri dok oči skakuću po tekstu na ekranu, baš kao što skakuće i čitateljska pozornost.\nPrelazak očima preko teksta, uz česte prekide zbog obavijesti (notifikacija) ili poveznica, smanjuje\nsposobnost dublje koncentracije i refleksije. Čitatelji stalno traže novu informaciju koja im odvlači\npozornost. Takva im aktivnost donosi brzu i kratkotrajnu zadovoljštinu, ovisnu o novim podražajima,\na istovremeno negativno utječe na sposobnost analitičkoga razmišljanja i kritičkoga mišljenja. Osim\ntoga, brz pristup informacijama i oslanjanje na internetske pretraživače mogu smanjiti kapacitet za\ndugoročno pamćenje. Ljudski se mozak sve više oslanja na tehnologiju. Smanjuje se potreba za\npamćenjem jer se informacije mogu uvijek lako pronaći. Rezultati skraćene pozornosti očituju se\nu rastućemu broju kratkih književnih formi, ali još i više u objavama na društvenim mrežama. Čim\nse digitalni čitatelj izmakne iz digitalnoga svijeta, spopada ga nepodnošljiva dosada. Dosada je\nnekad bila izvor kreacije i imaginacije, ali suvremena je dosada ozbiljan problem koji se zadovoljava\ndigitalnom stimulacijom, a ne knjigom. Uz navedeno, kao vrlo važnu negativnu posljedicu digitalnoga\nčitanja istraživanje ističe i smanjenje empatije kod mladih. Bez empatije smanjuje se mogućnost\nemocionalnoga povezivanja, što može utjecati na socijalne odnose i međuljudske vještine.\nMeđutim, istraživanje pokazuje kako se svi navedeni problemi mogu umanjiti poticanjem\ndubinskoga, klasičnoga čitanja u fizičkome mediju, tj. čitanjem prave knjige. Takav način čitanja\nne zadovoljava mozak trenutačno, već ga aktivira i usmjerava prema sposobnosti obavljanja\ndugoročnih zadaća. Za razliku od digitalnoga čitanja dubinsko čitanje zahtijeva usredotočenost\nna jednu temu tijekom duljega razdoblja. Time se razvija koncentracija, što je korisno za učenje\ni rješavanje problema. Stvaraju se snažnije veze među različitim informacijama u mozgu, što\npridonosi boljemu dugoročnom pamćenju. Veze olakšavaju razumijevanje složenih koncepata i\nomogućavaju zadržavanje znanja. Osim toga, kad čitatelj tijekom čitanja zamišlja složene scenarije,\nlikove i situacije, stimulira se mašta i kreativna sposobnost mozga. Ovaj aspekt dubinskoga čitanja\nposebno je važan za mlade jer potiče kreativno promišljanje koje može doprinijeti inovativnim\nidejama i rješenjima u stvarnome svijetu. Klasično čitanje ima veliku ulogu u razvoju strpljenja,\nplaniranja i empatije. Čitanje fikcije pomaže čitateljima da se užive u živote likova, razumiju njihove\nSažetak Hrvatski jezik\nosjećaje, motivacije i perspektive, a to utječe na razumijevanje i prihvaćanje različitosti, što je\nposebno važno u globalnome svijetu. Dubinsko čitanje pozitivno djeluje i na vještine pisanja i govora\njer se njime obogaćuje vokabular, omogućava jasnije i preciznije izražavanje misli i ideja koje su\npreduvjet za razvijanje socijalnih vještina i komunikacije.\nIstraživanja pokazuju kako se nalazimo u poodmakloj fazi najveće od svih dosadašnjih revolucija\n– u jeku smo neurološke revolucije prema kojoj su otkrića i upotreba parnoga stroja i električne\nstruje banalni jer ova revolucija izravno utječe i modificira način na koji funkcionira naš mozak.\nIako je tehnologija omogućila široku dostupnost tekstova, multimedijalnost, brzinu i interaktivnost,\nistovremeno je donijela i brojne izazove koji otežavaju tradicionalno čitanje te sve dobrobiti koje\nono donosi za razvoj ljudskoga mozga. Na pitanje kako pomiriti tradicionalno čitanje s digitalnim\nsvijetom ranije spomenuta neuroznanstvenica Maryanne Wolf odgovor vidi u obrazovnome sustavu\nkoji razvija dvopismeni mozak, sposoban da se snađe u objema čitalačkim galaksijama. To je važno\njer bi dijete bez digitalnih kompetencija lako moglo biti izopćeno iz vršnjačkoga društva, a sasvim će\nse sigurno teže nositi s izazovima suvremenoga svijeta, jednako kao što će bez vještine klasičnoga\nčitanja ostati zakinuto za ranije navedene dobrobiti. Razvijanje dvopismenosti omogućava\niskorištavanje prednosti obaju svjetova. Digitalno je čitanje izazovnije zbog stalnih smetnji\n(pop-upovi, poveznice, videomaterijali), ali obrazovanjem se može pomoći učenicima da usvoje\ntehnike za filtriranje ovih smetnji i da ostanu koncentrirani na ključne informacije. Međutim, na\npitanje kako to učiniti, kako pomiriti Gutenberga i Zuckerberga, galaksiju knjige i digitalnu galaksiju,\nobrazovni sustav tek treba naći pravi odgovor.\nProces je digitalizacije ireverzibilan, što znači da nema povratka na staro. Ima svoje manjkavosti,\nali i dobre strane. No, oko toga ne treba kukati, nego se s problemom treba suočiti. Ne osposobimo\nli sebe i nadolazeće generacije da budemo žitelji dviju galaksija, papirnate i digitalne, uskoro će\nnedostajati i pisaca i čitatelja i suosjećajnih građana sposobnih za kritičko mišljenje.\nPrilagođeno prema: www.kritika-hdp.hr\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-sazetak/page-8.png","page":8,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-sazetak/page-9.png","page":9,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2025-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2025,"schoolYear":"2024./2025.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2025/06/HRV25prvi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nAugust Šenoa, Prijan Lovro\nPolazno pitanje\nNa koji je način Lovrino podrijetlo utjecalo na njegov životni put?\nPolazni tekst\nNeki nemir osvoji Lovru.\n– Međutim – nastavi grof – čovjek snuje, a Bog boguje. Grof Buol mi je prijatelj, ali ima u njega\ndrugih prijatelja, moćnijih prijatelja. Na preporuku carskoga poslanika u Carigradu baruna H.,\nprimljen je drugi pitomac u akademiju, a i sami znate da je samo jedno mjesto prazno bilo.\n– Dakle ništa? – istisnu jedva Lovro blijed na smrt.\n– Žalibože ništa, jadni prijatelju moj! Ali ne gubite nade. Učite prava, budite činovnik! Skrbit ću\nza vas.\n– Hvala, gospodine grofe, ne mogu.\n– A zašto?\n– Oprostite da vam i opet iskreno govorim.\n– Govorite slobodno.\n– Utekoh iz sjemeništa da se dokopam slobode. Nisam bio jak u nijemoj zabiti probaviti\nnekoliko godina. A da budem svezan sav svoj vijek? (…)\n– Što kanite dakle, prijatelju?\n– Što? Znam li ja? Vijest, koju evo razumjeh, ošinula me kao grom iz vedra neba. Nemam sile\nni misliti, ali samo to znam, da neću biti činovnikom.\n– Ohrabrite se, prijatelju. Vi znate puno jezika; poznajete razne književnosti. Budite učitelj. Šta\nvelite na to?\n– Pravo rekoste, gospodine grofe! Sila vraća mi se. Da, bit ću učitelj za sve što sam bio za\nvašega sina. Svratit ću svoju tvornu silu u tu struju, i kad mi nije dano da budem sȃm čitavim\nčovjekom, othranjivat ću bar čitave ljude.\n– Dobro! Napišite odmah molbu na ministarstvo! Sȃm ću ju popratiti da vam se podijeli štipendij\ndržavni.\nŠto grof reče, to Lovro i učini. Valjalo je čekati, čekati. Lovro bavio se pisanjem književnih\nslavenskih rasprava. Minula tri mjeseca, ne bude odgovora. Grof se tomu čudio. Zdravlje bijaše\nmu slabo. Prekret pripravljao se po svoj državi. Grof odluči ostaviti se službe a poći na godinu\ndana putovati po Italiji, po Švicarskoj. Lovri valjade poći kući, nije mu se dalo samu besposličiti\nna tuđoj hrani. Starci slušali kako će Lovro biti profesorom, starci zadovoljni bili, samo bi se starici\nkadšto iz oka izvinula suzica. Sve će biti dobro, tješio se Lovrin otac. Ta nije li sȃm predsjednik\nrekao da je Lovro valjan, pošten, učen čovjek, a takav mora da bude velikim gospodinom.\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj rečenici ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i\ntako najaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznoga teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2025-ljetni-rok-skolski-esej/page-2.png","page":2,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2025-jesenski-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2025,"schoolYear":"2024./2025.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2025/08/HRV25drugi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S074.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nMija Dropuljić, Put putujem\nPotreba za putovanjem ukorijenjena je duboko u ljudskoj prirodi. Još od najranijih vremena\nčovjek je živio neprestano se krećući u potrazi za hranom. Razvojem i usavršavanjem poljoprivrede\nnomadski način života prestao je biti neophodan, ali potreba za otkrivanjem novih mjesta nije\nnestala. Ta iskra radoznalosti u nama čeka da je potpalimo novim iskustvima i nezaboravnim\ndoživljajima.\nSuvremeni čovjek voli isplanirati svoje životne aktivnosti, stoga često i željenomu putovanju\nprethode mjeseci promišljanja o destinaciji i planiranje putovanja. Mnogi znanstvenici tvrde da\nodgođeno zadovoljstvo, naročito ako je povezano s putovanjem, donosi veći užitak nego samo\nputovanje. Istraživanje provedeno na sveučilištu u Cornwallu pokazalo je da su ispitanici koji su\niščekivali trenutak da odu na odmor mnogo sretniji sa svojim životom, da imaju manje negativnih ili\nneugodnih emocija, zadovoljniji su svojom obitelji, financijama i zdravljem u usporedbi s ispitanicima\nkoji su odjednom odlučili putovati. Činjenica da očekujemo dobre stvari i da znamo da su one pred\nnama, a putovanja su izrazito poželjna iskustva, može biti izvor radosti dugo vremena. Planiranje\nputovanja može biti naročito uzbudljivo zato što često znamo taman toliko o mjestu na koje idemo\ni o tome što ćemo ondje raditi da možemo početi zamišljati ugodne detalje budućega izleta, poput\nležanja na plaži, planinarenja, mirisa borova, nezaboravnih gastronomskih užitaka. Istovremeno\ndosta detalja i ne znamo, što ostavlja prostor za uzbudljivu neizvjesnost i razmišljanje o tome\nšto bi nas sve tamo moglo čekati. Drugim riječima, počinjemo putovati čim počnemo razmišljati\no putovanju, tvrde autori studije. To je dovoljan razlog da, ako trenutačno i nemate mogućnost\nda nekamo odete, barem počnete planirati neko buduće putovanje: užitak će biti čak i veći, kao i\ndobrobiti za vaše mentalno zdravlje nego da ste odmah sjeli u auto i odvezli se na more.\nOsim pripreme putovanja i sam čin putovanja utječe na vaše mentalno zdravlje. Stres kod kuće,\nna poslu i u školi čini vas napetima, nemirnima, razdražljivima, krade vam elan i energiju, ograničava\nvaše sposobnosti, a putovanje vam daje priliku da se na neko vrijeme odmaknete od uzročnika\nstresa. Ono omogućuje da u drukčijim okolnostima preispitate svoj način života, navike, postupke\ni razmišljanja te da u konačnici eliminirate uzročnike nezadovoljstva i depresije, sagledavajući ih iz\nnekoga drugog kuta. Studija Sveučilišta Modul u Beču potvrđuje da redovita putovanja i izleti mogu\npomoći u smanjenju stresa i donijeti unutarnji mir. Putovanje također može ojačati odnose u obitelji,\npogotovo odnos s partnerom, može stvoriti novu razinu intimnosti i povjerenja. Nadalje, upoznavanje\nnovih mjesta, ljudi i kultura može promovirati takozvano multikulturalno učenje. To vam omogućuje\nrješavanje problema na nove načine, povećanje svijesti o okolišu i razbijanje predrasuda. Nadalje,\nputovanje proširuje vaš pogled i perspektivu te se možete bolje nositi s izazovima. Nemojte\nzaboraviti da je većina ljudi na putovanjima daleko aktivnija nego kod kuće. Upravo turistička šetnja\nSažetak Hrvatski jezik\ns ciljem upoznavanja određenoga mjesta, obilazak muzeja i znamenitosti, pješačenje planinarskim\nstazama, skijanje, plivanje u moru samo su neki od sadržaja koji zahtijevaju tjelesnu aktivnost i\ntako doprinose cjelokupnomu zdravlju (poboljšavaju cirkulaciju i čuvaju zdravlje srca i krvožilnoga\nsustava, preventivno djeluju protiv nastanka dijabetesa...).\nTreba upozoriti i na mračnu stranu putovanja o kojoj se baš i ne govori. Objavljene fotografije\npojedinaca na društvenim mrežama prikazuju prijeđene kilometre, mjesta boravka i posjećene\nturističke atrakcije, ali realnost je da svako putovanje nosi određenu dozu anksioznosti, remeti\nprirodni ritam organizma i razdvaja osobu od obitelji i prijatelja, piše The Huffington Post. Mnoge\nosobe počinju svoj identitet zasnivati na tome kamo su putovale i koliko često. Stalno su izložene\nnovim stimulansima, novomu okruženju, pa se teže vežu uz mjesta i teže zadržavaju postojeće\nprijatelje, pogotovo ako ti prijatelji ne putuju i nemaju zanimljive priče koje oni stalno iščekuju.\nOno što nije objavljeno za njih nije bilo, stoga su vrlo frustrirani ako se stalno ne putuje i stalno\nnešto novo ne bilježi. S medicinske točke gledišta česta i dugotrajna putovanja donose neprekidan\nsindrom jet laga jer dolazi do poremećaja prirodnoga ritma spavanja zbog prelaska kroz različite\nvremenske zone. Također, ako putnici nisu dovoljno pripremljeni na novo, mogu doživjeti pravi\nkulturni šok, što ih frustrira. Zemlje i ljudi razlikuju se – ono što je vama normalno, možda nije\nnormalno na drugoj strani svijeta. Važno je biti znatiželjan i otvoren za nova iskustva i doživljaje i\nuživati u nepoznatome, ali nisu svi na to spremni.\nŽivimo u divnome svijetu koji je put ljepote i avantura kojima nema kraja ako ih tražimo otvorenih\nočiju jer, kao što je Antun Gustav Matoš rekao: „Ne putuje onaj koji mnogo putuje, već koji\ndoživljava.” Stoga putujte, ali se dobro pripremite za putovanje, ne dajte da vas poteškoće na putu\noneraspolože i frustriraju. Vratite se obogaćeni, kao pripovjedači koji će s dragim osobama podijeliti\nsvoja iskustva.\nPrilagođeno prema: www.novilist.hr, www.zivim.jutarnji.hr\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-sazetak/page-8.png","page":8,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-sazetak/page-9.png","page":9,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2025-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2025,"schoolYear":"2024./2025.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2025/08/HRV25drugi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK 2. rok.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nFranz Kafka, Preobražaj\nPolazno pitanje\nNa koji način posao i obiteljska očekivanja oblikuju Gregorov život?\nPolazni tekst\n„Gregore”, reče sad otac iz susjedne sobe slijeva, „došao je gospodin prokurist i raspituje se\nzašto nisi otišao ranim vlakom. Mi ne znamo što bismo mu rekli. Uostalom, on želi i razgovarati\ns tobom osobno. Dakle, molim, otvori vrata. Bit će tako dobrostiv da te ispriča zbog nereda u\nsobi.” „Dobro jutro, gospodine Samsa”, vikne prokurist ljubazno u međuvremenu. „Nije mu dobro”,\nreče majka prokuristu, još dok je otac govorio na vratima, „nije mu dobro, vjerujte mi, gospodine\nprokuristu. Kako bi inače Gregor propustio vlak! Mladiću je samo posao na umu. Gotovo se ljutim\nšto nikada na večer ne izlazi; sada je bio osam dana u gradu, ali svake je večeri bio kod kuće.\nSjedi tu s nama za stolom i šutke čita novine ili proučava redove vožnji. Za njega je već razonoda\nkada se zabavlja rezbarenjem. Tako je, na primjer, u dvije-tri večeri izrezbario mali okvir; začudit\nćete se kako je lijep; visi unutra u sobi; smjesta ćete ga vidjeti čim Gregor otvori. Ja sam zapravo\nsretna što ste ovdje, gospodine prokuristu; mi sami ne bismo naveli Gregora da otvori vrata,\ntako je tvrdoglav; i zacijelo mu nije dobro, iako je to jutros zanijekao.” „Odmah dolazim”, reče\nGregor polako i oprezno i ne pomakne se da ne propusti ni riječ od razgovora. „Drukčije, milostiva\ngospođo, to uopće ne bih mogao objasniti”, reče prokurist, „nadajmo se da nije ništa ozbiljno.\nPremda moram s druge strane također reći, da bismo mi poslovni ljudi – nažalost ili nasreću,\nkako hoćete – često morali neznatne smetnje naprosto prevladati zbog poslovnih obzira.”\n„Dakle, smije li gospodin prokurist već do tebe?” upita nestrpljivi otac i ponovno zakuca na vrata.\n„Ne može”, reče Gregor. U susjednoj sobi slijeva zavlada mučna tišina, u susjednoj sobi zdesna\nsestra počne jecati.\n(…)\n„Gospodine Samsa!” uzvikne prokurist povišenim glasom. „Što se događa? Zabarikadirali ste\nse u svojoj sobi, odgovorite barem s da i ne, opterećujete svoje roditelje teškim, nepotrebnim\nbrigama i zanemarujete – a to primjećujem usput – svoje radne obveze na zapravo nečuven\nnačin. Govorim ovdje u ime vaših roditelja i vašeg šefa i molim vas sasvim ozbiljno da to\ntrenutačno, čestito razjasnite. Čudim se, čudim se. Mislio sam da vas znam kao mirnog, razumnog\nčovjeka, a sada kao da ste odjednom počeli paradirati s čudnovatim hirovima. Šef mi je, doduše,\nrano jutros natuknuo čime bi se mogao objasniti vaš propust – tiče se inkasa1 koji vam je nedavno\npovjeren – ali, evo, uistinu na časnu riječ, to objašnjenje neće biti pravo. Ali vidim sada vašu\nnepojmljivu tvrdokornost i potpuno sam izgubio volju da se i najmanje založim za vas. A položaj\nvam nipošto nije najčvršći. Imao sam spočetka namjeru reći vam sve to u četiri oka, ali budući da\novdje nepotrebno trošite moje vrijeme, ne znam zašto da to ne saznaju i vaši roditelji. Vaš rad,\ndakle, u posljednje vrijeme nimalo ne zadovoljava; doduše, ovo nije pogodno doba za osobite\nposlove, to priznajemo; ali, gospodine Samsa, ne smije uopće postojati doba kad se poslovi\nne bi sklapali.”\n„Ali, gospodine prokuristu!” uzvikne Gregor izvan sebe i zaboravi u uzbuđenju sve ostalo.\n„Smjesta, isti čas ću otvoriti. Neznatna nelagoda, napadaj vrtoglavice spriječili su me da ustanem.\ninkaso – naplaćivanje novčanih potraživanja\nJoš uvijek sam u krevetu. Ali sada sam ponovno svjež. Upravo izlazim iz kreveta. Samo još časak\nstrpljenja! Ne ide još tako dobro kako sam mislio. Ali već mi je bolje. Kako to samo spopadne\nčovjeka! Još mi je sinoć bilo sasvim dobro, moji roditelji znaju, ili točnije, ja sam već sinoć nešto\nnaslutio. Moglo se to vidjeti na meni. Zašto se samo nisam javio u trgovini! Ali čovjek uvijek misli\nda će prevladati bolest, a da ne ostane kod kuće. Gospodine prokuristu! Štedite moje roditelje! Tȁ\nnema razloga za sve te prigovore koje mi sada upućujete; a dosad mi nitko nije rekao ni riječi o\ntome. Vi vjerojatno niste pročitali posljednje narudžbe koje sam poslao. Uostalom, otputovat ću još\nvlakom u osam sati, okrijepilo me tih nekoliko sati mira. Ne zadržavajte se, gospodine prokuristu;\nzačas sam u trgovini i budite tako dobrostivi da to prenesete i preporučite me gospodinu šefu!”\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj rečenici ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i\ntako najaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznoga teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2025-jesenski-rok-skolski-esej/page-2.png","page":2,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2024-ljetni-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2024,"schoolYear":"2023./2024.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2024/06/HRV24prvi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S067.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nGoran Mizdrak, O pčelama\nDrevni su narodi duboko shvaćali ulogu pčele u prirodi. Spominjanje pčela seže još u davna\nvremena neolitika kada su naši preci na zidovima pećina, između ostalih životinja, crtali i pčele.\nAmerički su Indijanci još prije 6000 godina upotrebljavali med kao lijek i jelo. Tu su još i faraoni te\nrimski vladari na čijim su grobnicama redovito bile naslikane pčele. Tu sitnu posvećenu životinju\niznimne inteligencije štovali su mnogi narodi i vjerojatno odatle potječe izreka da pčele umiru, a\nne ugibaju. Pretpostavlja se da pčele žive na planetu Zemlji oko 110 milijuna godina, a danas ih\nraspoznajemo oko 20 000 vrsta.\nTijekom posljednjih nekoliko godina već smo mnogo puta imali priliku čuti koliko su pčele\ndragocjeni dio našega ekosustava. One su važne za naše zdravlje, ali i gospodarstvo općenito.\nNo, je li važnost njihove uloge uistinu do nas doprla? Zahvaljujući pčelama možemo uživati ​​u raznim\nnamirnicama, od jabuka i krušaka do kave i vanilije. K tome, ako nosite pamuk, to je moguće samo\nzato što je biljka pamuka, iz koje potječu niti od kojih je kreiran vaš odjevni komad, oprašena.\nImpresivno, zar ne? Može se zaključiti da je uloga pčela u prirodi iznimno velika. One u ekosustavu\nimaju vjerojatno jednu od najvažnijih uloga jer pridonose našemu ekosustavu tako što oprašuju\nbiljke. Svi dobro znamo da bez oprašivanja biljaka ne bi bilo ni njihovih plodova, pa tako ni hrane\nza nas i životinjski svijet. Na Zemlji se samo oko 10 % biljaka cvjetnica oprašuje vjetrom, dok 90 %\noprašuju insekti. Glavninu tih insekata čine upravo pčele. Pčela može nositi više peluda i posjetiti\nviše cvjetova od svih drugih oprašivača, poput leptira ili osa. Osim što oprašuju biljke koje su važan\ndio zdrave i uravnotežene prehrane jer našemu organizmu pružaju vlakna i esencijalne vitamine i\nminerale, pčele oprašuju i one biljke koje se koriste za prehranu drugih životinja važnih u ljudskoj\nprehrani. Budući da oprašuju široki spektar biljnih vrsta, pčele su važne i biljkama i čovjeku jer bez\noprašivanja ne mogu nastati plodovi koje jedemo. Dakle, one pomažu u očuvanju ekosustava i\nbioraznolikosti, stoga ljudska populacija bez njih ne može preživjeti.\nOsim što su važne pčele, važni su i pčelinji proizvodi. Oni su se oduvijek upotrebljavali i u\nmedicini i kao prehrambeni proizvodi. Med se od davnina koristi na oba načina. On se može\nupotrebljavati kao bolja alternativa za šećer, a sirovi med može biti i dobar izvor antioksidansa,\nminerala i enzima. Zbog svojega antibakterijskog djelovanja može se koristiti i kod liječenja rana.\nNadalje, pčelinji je propolis poput ljepila koje sve drži na okupu. On štiti košnicu od kiše, hladnih\nvjetrova i snijega, ali pomaže i ojačati strukturu i stabilnost košnice, spriječiti da bolesti i paraziti\nzaraze košnice i štiti ih od uljeza. Propolis se najčešće sastoji od pčelinjega voska, sline, soka i\nraznih biljnih proizvoda s područja u kojemu se pčele nalaze. Propolis također ima antibakterijsko\ndjelovanje, može pridonijeti snižavanju krvnoga tlaka, poticanju zdravlja kosti, ublažavanju nuspojava\nsezonskih alergija te pruža brojne druge prednosti organizmu kad se uključi u svakodnevnu\nSažetak Hrvatski jezik\nprehranu. Matična mliječ bogata je hranjivim sastojcima s dugom povijesti u tradicionalnoj medicini\njer je također poznata po svojim ljekovitim svojstvima. Visok postotak antioksidansa u matičnoj\nmliječi odličan je za zdravlje cjelokupnoga organizma. Usto, matična mliječ može pridonijeti jačanju\nnašega imunološkog sustava, potaknuti zdravlje probave, boriti se protiv upala i još mnogo toga.\nTakođer, pridonosi i poboljšanju stanja kože kao što su akne, ekcemi i razne upale. Otac medicine\nHipokrat smatrao je da su med, zrak i voda lijek za sve ljudske tegobe. Iz vremena u kojemu je živio\njavljaju se prvi pisani tragovi o primjeni pčelinjih proizvoda i pčelinjega otrova u medicinske svrhe.\nDanas taj način liječenja nazivamo apiterapija. Apiterapija upotrebljava pelud i pčelinje proizvode\nkao što su vosak, med i pčelinji otrov kako bi se došlo do izlječenja od određene bolesti. Pokazala\nse uspješnom kod liječenja kašlja, herpesa, visokoga kolesterola i prehlade, a vjeruje se da je\nuspješna i kod osteoartritisa, alergija i multiple skleroze. Ustanovljeno je da se med i ostali pčelinji\nproizvodi, posebice propolis, uspješno bore protiv virusa i bakterija. Jedna srodna grana apiterapije\nnaziva se apipunktura i upotrebljava se u Kini, a i u svijetu, već tisućama godina. Pri tome se koristi\npčelinji otrov, ubodom igle ili ubodom pčele. Postoje podatci o važnim povijesnim ličnostima koje su\nbile tretirane i izliječene ovom metodom.\nDa pčele život znače, znao je i Albert Einstein koji je izjavio: „Ako pčele nestanu s lica Zemlje,\nčovjeku kao vrsti neće preostati više od četiri godine života.” Važno je istaknuti da je najveća\nprijetnja pčelama čovjek jer proizvodnjom pesticida, onečišćenjem prirodnih staništa i voda te\nsječom šuma ljudi uništavaju pčele i one polako nestaju. Kako biste sačuvali njihove živote, ali i\nljudske – pazite na prirodu, ne zagađujte vodu, koja je također njihova hrana, i smanjite upotrebu\npesticida, posebno u blizini njihovih staništa. Zapamtite da bez pčela nema oprašivanja, nema\nploda, nema hrane, a nema ni ljudi.\nPrilagođeno prema: www.senzacionalno.hr; www.zena.net.hr\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-sazetak/page-8.png","page":8,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-sazetak/page-9.png","page":9,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2024-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2024,"schoolYear":"2023./2024.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2024/06/HRV24prvi.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nFjodor Mihajlovič Dostojevski, Zločin i kazna\nPolazno pitanje\nZašto su likovi Sonje i Dunje u romanu Zločin i kazna primjer požrtvovnosti?\nPrvi polazni tekst\nA onamo dječica gladuju... A Katerina Ivanovna krši ruke i sve hoda po sobi i crvene joj pjege izbile\npo obrazima, kao što svagda biva u toj bolesti, i viče: „Živiš kod nas, gotovanko jedna, jedeš i piješ\ni griješ se”, a vraga pije i jede kad ni dječica po tri dana ne vide korice kruha! Ja sam tada ležao...\nama, što da krijem! Ležao sam pijan, molit ću lijepo, i čujem kako Sonja govori (onako pokorna\ni glasić joj tako krotak... plavokosa je, a lice joj uvijek blijedo, mršavo), kaže joj: „Pa zar zbilja,\nKaterino Ivanovna, da se u tako što upustim?” A ona Darja Francovna, opaka žena i policiji dobro\npoznata, raspitivala se već tri puta kod gazdarice. „Pa što”, odgovara joj Katerina Ivanovna, onako\npodrugljivo, „što imaš čuvati? Baš mi je i to neko blago!” Ali ne zamjerite joj, ne zamjerite, milostivi\ngospodine, ne zamjerite! Nije bila pri zdravoj pameti kad je to rekla, bila je uzrujana, bolesna i\ndjeca su plakala jer nisu imala što jesti, i više je to rekla da je uvrijedi, nego u pravom smislu...\nJer, Katerina Ivanovna vam je takve ćudi, i čim se djeca rasplaču, pa makar i od gladi, odmah ih\npočne tući. I vidim ja, negdje oko šest sati, Sonječka ustala, ogrnula rubac, obukla ogrtač i otišla\nod kuće, a negdje oko devet se vratila. Došla pa ravno do Katerine Ivanovne i na stol pred nju\nmetne bez riječi trideset rubalja. Ni riječi nije progovorila, ni da je pogleda, samo je uzela naš\nveliki zeleni rubac od polusukna (imamo takav jedan zajednički rubac, od polusukna), pokrila se\nnjime preko glave i legla u krevet, okrenula lice zidu, samo joj se ramena i cijelo tijelo neprestance\ntresu... A ja i dalje sve onako ležim... I onda vidim, mladiću, kako Katerina Ivanovna, isto tako bez\nriječi, priđe Sonječkinu krevetu, i cijelu je večer do njezinih nogu proklečala, ljubila joj noge, nije\nhtjela ustati, i poslije su obadvije tako zajedno zaspale, zagrljene... obadvije... jest, molit ću lijepo...\na ja... ja sam pijan ležao, molit ću lijepo.\nDrugi polazni tekst\nRazumihin je po mnogim znacima ubrzo zaključio da obje žene žive u vrlo teškim prilikama.\nDa je Avdotja Romanovna bila obučena kao kraljica, valjda je se ne bi uopće bojao, ali ovako,\nmožda baš zato što je bila siromaški obučena i što je vidio u kakvim bijednim prilikama živi, u srce\nmu se uvukao strah pa je počeo strepiti za svaku svoju riječ, za svaku gestu, što je, naravno, bilo\nna nepriliku čovjeka koji se ionako nije previše uzdao u sebe.\n(...)\n– Znaš što, Dunja – počne ozbiljno i suhoparno – molim te, naravno, da mi oprostiš za ono\njučer, ali smatram se dužnim da te opet podsjetim da ne odustajem od svog glavnog zahtjeva.\nIli ja ili Lužin. Ja mogu biti i hulja, ali ti ne smiješ. Jedna je hulja dovoljna. Ako se ipak udaš za\nLužina, neću te više smatrati sestrom.\n– Rođa, Rođa! Pa opet se ponavlja isto ono od jučer – jadovito cikne Puljherija Aleksandrovna.\n– I što neprestano sam sebe nazivaš huljom, to nikako ne mogu podnijeti. I jučer je bilo isto tako...\n– Brate – odlučno mu i isto onako suhoparno odvrati Dunja – u svemu tome ti si negdje ipak\npogriješio. Noćas sam o tome razmišljala i otkrila pogrešku. Vic je u tome što ti valjda misliš da se\nja tobože nekome i za nekoga žrtvujem.\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i tako\nnajaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznog teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2024-ljetni-rok-skolski-esej/page-2.png","page":2,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2024-jesenski-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2024,"schoolYear":"2023./2024.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2024/08/HRV24drugi-1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S069.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nMajda Rijavec, Dubravka Miljković, Školska disciplina\nIstraživanja širom svijeta pokazuju da, usprkos svim naporima koji se čine da bi ih bilo manje,\ndisciplinskih je problema u školi sve više. Stručnjaci koji se bave problemima (ne)discipline u\nrazredu pokušavaju definirati modele koji bi u praksi mogli poslužiti i za prevenciju i za rješavanje\ndisciplinskih problema. Danas su u svijetu poznata dva modela školske discipline: pozitivna\ndisciplina Jane Nelsen i njezinih suradnika te asertivna disciplina Leeja Cantera i Marianne Canter.\nPozitivna disciplina usmjerena je na učenike, a njezin je cilj razvoj njihovih osobina i vrlina\nsamodiscipline, tj. smanjivanje potrebe za izvanjskom kontrolom ponašanja. Naglašava se razvoj\nsamokontrole te razvoj svijesti o svojim i tuđim emocijama i motivima, ističe se važnost socijalne\nodgovornosti i sposobnosti timskoga rada, poštenje, moralnost, integritet, iskrenost i pomaganje\ndrugima. Preduvjet je svemu tome zadovoljavanje najvažnijih učeničkih potreba kao što je\nostvarivanje autonomije (potreba da učenici svojevoljno i samostalno biraju aktivnosti i donose\nodluke), kompetentnosti (potreba da se učenici osjećaju uspješnima i da imaju kontrolu nad\nokolinom) i povezanosti (potreba za dobrim, bliskim i sigurnim odnosima s drugim ljudima). Svi\nučenici, baš kao i odrasli ljudi, vole kad mogu sami odlučivati o onome što im je važno – hoće li prvo\npisati zadaću ili se igrati, na koju će temu pisati sastavak ili kamo će ići na izlet. Osjećaj slobode i\nu malim stvarima dovodi do osjećaja zadovoljstva, a time i do manje disciplinskih problema. Slično\nje i s ostalim dvjema potrebama. Svaki učenik ima potrebu pokazati i sebi i drugima kako je bar\nu nečemu uspješan, tj. kompetentan. Većini učenika to i uspijeva. Neki su općenito dobri učenici,\ndrugi su izrazito uspješni u nekim predmetima, a treći u sportu ili nekoj drugoj izvannastavnoj\naktivnosti. Njihove kompetencije treba razvijati da im škola ne bi bila mučno iskustvo suočavanja s\nneuspjehom, nego mjesto postizanja uspjeha i osobnoga zadovoljstva. Također, svaki učenik ima\npotrebu imati prijatelje i biti prihvaćen od ostalih učenika u razredu. Učenici koji su u tome smislu\nzadovoljni izazivat će manje disciplinskih problema. Važno je istaknuti da se ovaj model izričito\nprotivi upotrebi nagrada, pohvala i kazni. Temelji se na dobrim odnosima učitelja i učenika i njihovu\nstalnom dogovaranju radi sprečavanja problema u ponašanju; ako netko „ne sluša”, slijede mu\nprirodne, logične posljedice – na primjer, posljedica nerada loša je ocjena.\nAsertivna je disciplina, s druge strane, usmjerena na učitelja jer se temelji na pravilima i\nkorektivnim postupcima koje primjenjuje učitelj. Ti su korektivni postupci nagrade, pohvale i\nkazne te ne služe samo u rješavanju problema, već i u njihovu sprečavanju, odnosno u razvoju\nsamodiscipline. Postavljanje pravila nužno je za stvaranje discipline u razredu. Učenicima treba biti\njasno što je dopušteno, a što nije. Pravila moraju biti jasna, a kad se jednom postave, od učenika\nse očekuje da ih poštuju. Stoga učitelj treba poticati učenike kad se drže pravila, ali isto tako moraju\nbiti jasne posljedice, odnosno kazne ako učenici pravila krše. Poticaji su sve ono što učenici vole i\nSažetak Hrvatski jezik\nu čemu uživaju, na primjer zabavne aktivnosti na kraju dana, proslave rođendana u razredu, igranje\nigara, odlazak u zoološki vrt, kino ili kazalište, sat u prirodi, slatkiši, dopuštanje aktivnosti po izboru,\nproglašenje najboljega učenika, razne vrste pohvala i slično. Za razliku od poticaja, kazna je sve ono\nšto smanjuje učestalost nekoga ponašanja, a općenito se ne sviđa onomu na kome se primjenjuje.\nU školi se najčešće primjenjuju opomene, ukori, slanje ravnatelju na razgovor te kažnjavanje\nnekom neugodnom aktivnošću, na primjer brisanjem ploče ili pospremanjem nereda. Kazne mogu\nbiti i uskraćivanje ili zabrana nekih ugodnih aktivnosti. Ipak, kažnjavanje ima brojnih ograničenja\n– uči učenike što ne smiju ili ne trebaju raditi, a ne ono što bi trebali. Također, kazna obično ima\nkratkotrajne učinke, uči djecu agresivnosti prema drugima, stvara negativno školsko i razredno\nozračje, a ponekad može služiti i kao nagrada – učenici je izazivaju da bi dobili pažnju učitelja,\ndrugih učenika ili smanjili dosadu. Usprkos svim ovim ograničenjima kažnjavanje je ipak nužno i\nučinkovito, a očekivanje da će se svi oblici kazne zamijeniti „pozitivnijim” tehnikama idealističko je i\nutopijsko.\nČini se da je kratkoročno učinkovitija asertivna disciplina, no za dugoročne učinke bolje je\npozabaviti se pozitivnom disciplinom. Ipak u obama modelima ima postupaka koji su nedvojbeno\nvažni za uspostavljanje dobroga razrednog ozračja, a oni uključuju usmjeravanje na prevenciju,\njasna pravila i postupke, poticaje, dobre odnose s učenicima, dobru suradnju s roditeljima,\nsamodisciplinu i mnoge druge.\nPrilagođeno prema: Majda Rijavec, Dubravka Miljković, Pozitivna disciplina u razredu\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-sazetak/page-8.png","page":8,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-sazetak/page-9.png","page":9,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2024-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2024,"schoolYear":"2023./2024.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2024/08/HRV24drugi-1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK jesen.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nAlbert Camus, Stranac\nPolazno pitanje\nNa koji način Meursaultov karakter određuje njegovu sudbinu?\nPolazni tekst\nSutradan me u zatvoru posjetio branitelj. Bio je nizak i debeljuškast, prilično mlad, pomno\nzalizane kose. Iako je bilo vruće (ja sam bio u košulji), nosio je tamno odijelo, ovratnik sa\nzavrnutim krajevima i neobičnu kravatu sa širokim crnim i bijelim prugama. Odloži na moj krevet\ntorbu koju je nosio pod pazuhom, predstavi se i reče da je proučio moj predmet. Moj je slučaj vrlo\nškakljiv, ali on ne sumnja u uspjeh, pod uvjetom da mu se povjerim. Zahvalih mu, a on mi reče:\n– Da prijeđemo odmah na samu stvar!\nSjede na krevet i priopći mi da su se raspitali o mom privatnom životu. Znaju da mi je majka\nnedavno umrla u ubožnici. Zatim su poveli istragu u Marengu. Istražitelji su doznali da sam se\n„pokazao bešćutnim” na dan mamina sprovoda. – Znate – reče mi branitelj – malo mi je neugodno\nda vas to pitam, ali je to vrlo važno, i bit će jak argument optužbe ako ne budem mogao na to ništa\nodgovoriti. – Htio je da mu pomognem. Upita me jesam li taj dan mnogo patio. Neobično sam se\nzačudio tom pitanju, činilo mi se da bi i meni bilo vrlo neugodno kad bih ga morao kome postaviti.\nOdgovorih mu, ipak, da sam se uglavnom odvikao da sâm sebe ispitujem, i da mi je teško o tome\nbilo što kazati. Svakako sam mnogo volio majku, ali to ništa ne znači. Sva su zdrava bića\nmanje-više koji put poželjela da umru oni koje vole. Tu me branitelj, vrlo uzbuđen, presiječe u\nriječi. Zatraži od mene da mu obećam da to neću reći na suđenju ni pred glavnim istražiteljem.\nObjasnih mu, međutim, da sam po naravi takav da mi često tjelesne potrebe potiskuju osjećaje.\nOnoga dana kad smo pokopali mamu, bio sam vrlo umoran i pospan, pa nisam vodio računa o\nonome što se događalo. Jedino mogu pouzdano reći da bih radije da mama nije umrla. Ali, činilo\nmi se da branitelj nije time zadovoljan. Reče mi:\n– To nije dovoljno.\nPorazmisli i upita me smije li reći da sam toga dana potpuno gospodario svojim osjećajima.\nRekoh mu: – Nemojte, to ne bi bila istina. – Pogledao me nekako čudno, kao da mu se pomalo\ngadim. Reče mi gotovo pakosno da će ravnatelja i osoblje ubožnice svakako preslušati kao\nsvjedoke, i da bi mi „to moglo grdno naškoditi”. Upozorih ga da to nema nikakve veze s mojim\nslučajem, ali mi on samo odgovori da se vidi da nisam imao nikad posla s pravosuđem.\nOtišao je nekako srdit. Htio sam ga zadržati i rastumačiti mu da želim steći njegovu naklonost,\nne zato da bi me bolje branio nego, ako mogu tako reći, iz prirodnih razloga. Najgore je što sam\nvidio da se osjeća nelagodno sa mnom. Nije me razumio i malo se naljutio na mene. Zaželio sam\nda ga uvjerim da sam kao i drugi ljudi, baš kao i drugi ljudi. Ali od svega toga ne bi zapravo bilo\nvelike koristi, i iz lijenosti sam odustao od svoga nauma.\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i tako\nnajaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznog teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2024-jesenski-rok-skolski-esej/page-2.png","page":2,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2023-ljetni-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2023,"schoolYear":"2022./2023.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2023/06/HRV23ljeto1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S061.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nSnježana Mostarkić, O domaćoj zadaći\nNakon niza sati provedenih sjedeći u učionici posljednje što želimo čuti jest da je pred nama\ndodatni rad vezan uz školu koji valja odraditi tijekom dragocjenoga vikenda. Iako je poznato da je\nriječ o odrednici tradicionalnoga školovanja, domaća zadaća kao tema izaziva brojna neslaganja i\nrasprave. Jedni smatraju da je neizostavan dio školovanja, dok drugi vjeruju da bi vrijeme potrebno\nza pisanje domaće zadaće moglo biti bolje uloženo.\nBrojni su razlozi zašto učenici trebaju pisati domaću zadaću. Jedan je od njih taj što ona\npotiče uvježbavanje. Iako može djelovati vremenski nefunkcionalno i dosadno u usporedbi s\ndrugim aktivnostima, ponavljanje je potrebno kako bi se objasnili neki pojmovi i poboljšale pojedine\nvještine. Također, domaća zadaća može biti nešto što će roditelje uključiti u život njihove djece\nuz uvjet da žive u zdravom okružju. Roditelj koji djetetu pomaže ispuniti obveze domaće zadaće\nujedno sudjeluje u djetetovu obrazovanju. Pritom se otvara mogućnost povezivanja i zbližavanja\nroditelja i djece. Domaća zadaća od mnogo je većega značenja negoli je to vidljivo u činu rješavanja\ndodijeljenih zadataka. Može razviti vještine upravljanja vremenom tako što upućuje učenike na\nplaniranje te na potrebu da se svi zadatci riješe u zadanome roku. Učeći upravljati vremenom,\nučenici ujedno jačaju vještine vezane uz rješavanje problema i samostalno razmišljanje. Dobro\nje i što zadaća stvara vezu između škole i roditelja. Omogućuje bolje međusobno upoznavanje, a\nroditelji mogu vidjeti u kojem dijelu rada i učenja njihovo dijete nailazi na prepreke. Također, roditelji\nmogu saznati u čemu je dijete izvanredno. Danas mnoga djeca pred zaslonima provode znatno\nviše vremena negoli bi to bilo dopustivo. Da ne idu u školu, to bi vrijeme bilo veće. Zadaće potiču\nučenike na razvijanje dobrih navika u učenju te pritom reduciraju vrijeme provedeno pred zaslonima.\nZadaća se može promatrati i kao još jedna izvannastavna aktivnost. Mnoge obitelji ulažu mnogo\nvremena i novca u različite klubove i tečajeve kako bi ispunile djetetovo slobodno vrijeme, pa se, kao\nizvannastavna aktivnost, domaća zadaća može uvrstiti u učenikov dnevni raspored.\nMeđutim, unatoč mnogim pozitivnim učincima pisanje zadaće ima i negativne učinke. Iako je\nvrijeme provedeno u učionici bitno, jednako je bitno i ono provedeno na dječjem igralištu. Ako se\ndjeci dodjeljuje pretjerana količina zadaće, neće imati dovoljno vremena za igru, što može utjecati\nna njihov društveni razvoj i učenje. Istraživanja pokazuju da oni koji imaju više vremena za igru, u\nškoli dobivaju bolje ocjene te dulje mogu održati pozornost. Djeca na nastavi provode duge sate\nsjedeći u učionici, a zadavanje domaće zadaće samo znači produljenje takvih sati. Sjedilački\nnačin života može biti opasan te može prouzročiti zdravstvene poteškoće kakva je primjerice\npretilost. Domaća zadaća djeci oduzima vrijeme potrebno za tjelesnu aktivnost. Iako mnogi ljudi\nu obiteljskome domu vide dobro okružje za djecu da nastave s učenjem, nemaju sve obitelji dom\nkoji je ujedno i zdravo okružje. Postoje roditelji koji ne pružaju ni najosnovniji oblik pomoći svojemu\nSažetak Hrvatski jezik\ndjetetu, a i oni koji bi to željeli, zbog osobnih barijera katkad ne mogu. Domaća zadaća može\nprodubiti razlike među djecom i njihovim roditeljima te je to jedan od razloga zašto je zadavanje\nzadaće loš izbor. Također, škola za učenike znači mjesto s punim radnim vremenom s obzirom\nna to da u učionici provedu i šest sati dnevno. Učenici često imaju i izvannastavne i izvanškolske\naktivnosti kao što su sportovi, glazba ili likovno stvaralaštvo, a koje su jednako potrebne kao i\ntradicionalna nastava. Dodavati dodatne sate na sve postojeće zahtjeve može za djecu biti prevelik\nizazov, a ujedno znači i sprečavanje učenika da slobodno vrijeme ulože u iskušavanje novih\nrazličitih kreativnih aktivnosti. To su ujedno i najveći nedostatci zadavanja domaćih zadaća. Opći\nje dogovor da učenici – sukladno razredu koji pohađaju – ne bi trebali dobiti više od deset minuta\nzadaće na dan. To znači da u prvom razredu imaju maksimalno deset minuta posla, u drugom\ndvadeset i tako dalje. Međutim, većina učenika dobije znatno veću količinu domaće zadaće od\npreporučene. Zadavanje prevelike količine zadataka povećava razinu stresa i vodi u sagorijevanje.\nS druge strane, kako bi izbjegli pisanje domaće zadaće kod kuće, mnogi učenici radije varaju te\nprepisuju jedni od drugih ili preuzimaju ono što su pročitali na internetu. I jedno i drugo, pak, dovodi\ndo negativnih učinaka kad su u pitanju obrazovna postignuća.\nArgumenti suprotstavljenih strana o pitanju trebaju li učenici imati domaću zadaću uvjerljivi su\ni utemeljeni te se čini da nema jednostavnog odgovora na to pitanje. Roditelji i profesori i dalje će\nrazmjenjivati razmišljanja i stavove, a učenici ostajati usred tih rasprava bez osobitoga prostora da\ni sami nešto kažu ili promijene. Bitno je shvatiti prednosti i nedostatke zadavanja domaćih zadaća\nkako bi se obje perspektive uzele u obzir i pronašlo najbolje rješenje. U konačnici svima je cilj\ndobrobit i uspjeh naših učenika.\nPrilagođeno prema: www.skolskiportal.hr, Jesu li domaće zadaće potrebne ili štetne?\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-sazetak/page-4.png","page":4,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-sazetak/page-5.png","page":5,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2023-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2023,"schoolYear":"2022./2023.","term":"ljetni rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2023/06/HRV23ljeto1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI-ZADATAK.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nMiroslav Krleža, Gospoda Glembajevi\nPolazno pitanje\nZašto se Leone Glembay u roditeljskom domu osjeća strancem?\nPolazni tekst\nLEONE: Da, ja sam doputovao da budem na tom jubileju. I ja sam konačno vidio tebe,\nmi smo se vidjeli! Ja sam jutros prisustvovao sjednici banke, a sutra sve je to više manje\ngala predstava! Ja mislim da je najbolje da otputujem. Ja sam jedanaest godina odsutan, i\nvidiš, ja se više ne osjećam ovdje, kako da kažem: kod kuće. Der Mensch ist ein Gewohnheitstier!1\nA to ćeš dopustiti i sam: u ovakvoj jednoj intimnoj slavi, u svojoj roditeljskoj kući osjećati se\nstrancem, neke vrsti prolaznikom, to baš nije najprijatniji osjećaj!\nGLEMBAY: To ovisi od toga, kako tko osjeća! Ja mislim, da su ti tvoji osjećaji svakako potpuno\nneosnovani. Sve je to überspannt2.\nLEONE ustane nervozno kao da je uboden. On je nervozno reagirao na tu riječ: U čitavom\ntvom rječniku ti nisi našao druge riječi nego upravo: überspannt? To ste mi govorili od\nmoje pete godine! Uostalom! On se svladao. Trijezno i mirno s nešto maliciozno ironičnim\nprizvukom: Molim te, izvini, ali dopusti mi da te zapitam: kom sretnom slučaju imam da\nzahvalim ovaj tvoj kasni posjet?\nGLEMBAY ustao je pogođen. U njemu kuha. On raste iz depresije u violenciju. Gleda dugo svoga\nsina i klima glavom: Da, upravo tako arogantan bio si spram mene već u svojoj devetoj godini. To je\nta tvoja venecijanska krv! Škripi zubima, puši i prođe sobom gore dolje. Zaustavi se tvrdo i odlučno:\nDakle molim te, da ne gubimo vrijeme! Ja sam bio na terasi, kad si ti razgovarao s doktorom\nSilberbrandtom i ja sam čuo svaku tvoju riječ. Stanka. Otac i sin dugo se gledaju okom u oko. Leone\niza stanke podigne obje ruke u ramenima, a zatim ih bespomoćno spusti. (...)\nGLEMBAY: Tako? A šta bi ti uradio s čovjekom, koji bi pred dva svjedoka izjavio, da tvoja\nvlastita žena spava čitavu noć sa svojim ljubavnikom?\nLEONE: Ne znam!\nGLEMBAY: A tako? Ti ne znaš?\nLEONE: Naravno, da ne znam! Ja prije svega nemam žene, a drugo, ja nemam šezdeset i\ndevet godina! Ja dakle ne znam, što bih ja uradio na tvome mjestu!\nGLEMBAY: Pa dobro, molim te, uzmimo da je tako! Dobro! Ti ne znaš! Dobro! Molim te!\nDobro! Prođe sobom i onda stane. Možeš li ti razgovarati sa mnom samo dvije minute kao\nprijatelj?\nLEONE: Ne! Na jedno pitanje koje je u jednoj nijansi toplo zazvučalo, to je bilo suviše kratko i suviše\noštro. Osjetivši da je ta riječ bila prejaka, nastoji iza neugodne šutnje, da je razvodni komentarom:\nNaime ja, ja naime mislim, ljudi ili su prijatelji ili nisu! A na dvije minute ne može se biti prijateljem.\nI moguće se nas dvojica niti ne poznajemo: u ovih jedanaest godina mi nismo gotovo nijedanput\nrazgovarali, mislim naime od onog jutra, kada su mamu našli mrtvu! I vidiš, ja ne bih htio biti\nneiskren: od mamine smrti ja nisam nijedanput osjetio potrebe da govorim s tobom prijateljski! Da!\nLagao bih, da ti kažem, da mogu s tobom da govorim prijateljski, pa bilo to samo dvije minute! Vidiš:\nja sam zapakovao, ja putujem! Ja smatram, da je moj dolazak u ovaj glembajevski dom bio neke\nvrste posljednja sentimentalna zabluda. Ti si me pozvao pismeno, jubilej, obiteljski obziri i sve ovo\nšto već spada k ovakvoj slavi, ali to sve jače je od mojih nerva! Ja sam, kako ti veliš: überspannt!\nMene smatraju „paranoidom”! Jednom „paranoidu” ne treba ništa uzeti za zlo! Ali molim te da\nDer Mensch ist ein Gewohnheitstier! (njem.) – Čovjek je životinja koja robuje svojim navikama!\nüberspannt (njem.) – prenapeto\nsvakako uvažiš, da sve ono, što sam rekao Silberbrandtu, nije bilo rečeno na tvoju adresu! Na moju\nčasnu riječ, ja nisam imao ni pojma, da ti slušaš na terasi!\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i tako\nnajaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznog teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2023-ljetni-rok-skolski-esej/page-2.png","page":2,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2023-jesenski-rok-sazetak","kind":"sazetak","partLabel":"Sažetak","year":2023,"schoolYear":"2022./2023.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2023/08/HRV23jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2023-jesenski-rok-sazetak/paper.pdf","sourceName":"HRV IK-2 D-S063.pdf","durationMinutes":80,"wordRange":{"min":200,"max":250,"acceptedMin":180,"acceptedMax":275},"maxScore":18,"scoreMultiplier":2,"rubricId":"summary-2023","taskText":"Pročitajte polazni tekst.\nSažetak oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš sažetak bude pravopisno, gramatički i leksički točan.\nU sažetak morate uvrstiti sve smjernice.\nSažetak mora imati 200 – 250 riječi.\nIris Jerončić Tomić i suradnici, Društvene mreže i samopoštovanje\nSamopoštovanje se odnosi na osobnu prosudbu vlastite vrijednosti. Odnosi se na pozitivnu ili\nnegativnu procjenu svojega „ja” i na to koliko pojedinac smatra sebe vrijednim i kompetentnim.\nUglavnom je stabilna osobina koja se razvija tijekom vremena i koja reagira na dnevne događaje\ni kontekste. Upotreba društvenih mreža i razina samopoštovanja dva su međusobno povezana\nkonstrukta. Ono što radimo na internetu, osobito na društvenim mrežama, utječe na naše\nsamopoštovanje jer ljudi žive dio svog života na društvenim mrežama.\nOsoba ima priliku oblikovati sliku o sebi upotrebljavajući društvene mreže poput Facebooka i\nTwittera. Objave odražavaju emocije i način na koji se osobe predstavljaju te mogu poslužiti za\nispitivanje njihove osobnosti i razine samopoštovanja u mrežnim okruženjima. Društvene mreže\nmogu poboljšati samopoštovanje, uključujući percepciju fizičkog izgleda, odnosa s drugima i\nromantičnih veza, pogotovo kad osoba primi pozitivne povratne informacije od svojih vršnjaka i\nprijatelja na društvenim mrežama. Osim toga, profil na društvenoj mreži omogućuje korisnicima\nkontrolu nad onim što objavljuju na mreži i kako se žele predstaviti drugima. Dakle, profil pomaže\nzadovoljiti potrebe pojedinca za očuvanjem vlastite vrijednosti i integriteta, što dovodi do pozitivnih\nosjećaja i više razine samopoštovanja.\nSvaki pojedinac, bez obzira na razinu samopoštovanja, ima potrebu pripadati društvenoj\nskupini, što postiže aktivnošću na društvenim mrežama. Pripadnost grupi potiče razvoj kolektivnog\nsamopoštovanja i pojedincu predstavlja značajnu emocionalnu vrijednost. Komunikacija na\ndruštvenim mrežama može biti korisna za osobe s niskom razinom samopoštovanja jer im pomaže\nda se prilagode novoj sredini i da podignu razinu samopoštovanja. Pojedinci koji upotrebljavaju\ndruštvene mreže mogu doživjeti osjećaj pripadnosti i socijalnu podršku drugih. Osobe s nižom\nrazinom samopoštovanja pokušavaju nadoknaditi nedostatak samopoštovanja povećanjem broja\nonline prijatelja kako bi uspostavili osjećaj pripadnosti i naglasili doživljaj popularnosti. Prihvaćajući\nviše zahtjeva za prijateljstvom, osobe s niskom razinom samopoštovanja nastoje ostvariti socijalnu\ninterakciju. Osobe s nižom razinom samopoštovanja provode više vremena na mreži i imaju više\npromotivnih sadržaja na svojim profilima. Za razliku od njih osobe s višom razinom samopoštovanja\nčešće upotrebljavaju društvene mreže za poboljšanje odnosa s ljudima koje poznaju nego za\nstjecanje novih prijatelja. Korisne su im za održavanje postojećih prijateljstava ili bliskih odnosa.\nPojedinci s višom razinom samopoštovanja preferiraju dijeljenje fotografija, misli i ideja s drugima te\npridaju manje važnosti online interakciji putem društvenih mreža.\nPored pozitivnog učinka na razinu samopoštovanja komunikacija na društvenim mrežama\nmože imati i negativne učinke. Kad se govori o povezanosti upotrebe društvenih mreža i razine\nsamopoštovanja, onda se ispituje njihov utjecaj na poštovanje tijela, osobito među adolescentima.\nSažetak Hrvatski jezik\nDruštvene mreže mogu doprinijeti nezadovoljstvu vlastitim tijelom kod oba spola. Okupiranost\nvlastitim tijelom, pa tako i nezadovoljstvo, razvijaju se relativno rano. To je primijećeno već\nkod djevojčica u dobi od sedam godina. Idealno žensko tijelo prikazano u masovnim medijima\nutjelovljuje ideju mršave žene kao privlačne i poželjne. Nezadovoljstvo vlastitim tijelom i ulaganje u\nizgled važni su čimbenici rizika za probleme mentalnog zdravlja, prije svega poremećaja prehrane\ni depresije, a negativno se odražavaju na dobrobit i samopoštovanje adolescenata. U ovom\nkontekstu viša razina izloženosti masovnim medijima povezana je s višom razinom nezadovoljstva\nvlastitim tijelom i poremećajem prehrane. Stope poremećaja prehrane među ženama, kao što su\nanoreksija, ortoreksija nervosa i bulimija, rastu. Sve više muškaraca zabrinuto je zbog oblika tijela\ni težine jer su svakodnevno izloženi medijskom pritisku. Ulaganje u vanjski izgled pretpostavlja\naktivnosti koje iziskuju mnogo vremena, energije i novca, a također mogu biti štetne za školski i\nakademski uspjeh, međuljudske odnose i tjelesno zdravlje. Isto tako, na društvenim mrežama drugi\nprosuđuju objavljene fotografije i vrednuju ih lajkovima i komentarima što može dovesti do osjećaja\nprihvaćenosti ili odbijenosti.\nDruštvene mreže čest su predmet istraživanja i neslaganja oko uzroka i posljedica njihova\nodnosa prema samopoštovanju i dobrobiti ljudi. Njihova upotreba može imati društvene i psihološki\nnegativne učinke na ljude, ali s druge strane one mogu biti i vrlo korisne u kontekstu društvene\npovezanosti i pripadnosti.\nPrilagođeno prema: https://hrcak.srce.hr/file/354676\nSmjernice za pisanje sažetka\nPročitajte zadani tekst.\nSažmite polazni tekst svojim riječima:\n• tako da navedete opće podatke o polaznome tekstu\n• tako da odredite namjenu i temu teksta\n• tako da navedete osnovne misli teksta i pojedinosti koje ih podupiru\n• tako da odredite autorov stav o temi.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2023-jesenski-rok-sazetak/page-4.png","page":4,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-2023-jesenski-rok-sazetak/page-5.png","page":5,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-2023-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2023,"schoolYear":"2022./2023.","term":"jesenski rok","level":null,"archiveUrl":"./files/ncvvo/wp-content/uploads/2023/08/HRV23jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-2023-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK jesen.pdf","durationMinutes":160,"wordRange":{"min":440,"max":null,"acceptedMin":396,"acceptedMax":null},"maxScore":30,"scoreMultiplier":2,"rubricId":"school-essay-2023","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nVjenceslav Novak, Posljednji Stipančići\nPolazno pitanje\nKako Juraj Stipančić utječe na živote ženskih članova svoje obitelji?\nPrvi polazni tekst\nDragi Muki!\n(...)\nTa moja dobroćudna i neuka mati vjeruje i s nekakvim nadama spaja u sebi uvjerenje da se Fedica\nzaljubio. (...) A znaš li što će biti konac svega: zaludit će sirotu djevojku, pa će se i u njezinoj glavi\npočeti razvijati kojekakve romantične ludorije, dosadit će joj post i krunica, a kuća postati tijesna...\nAli bijesa bi sebi Fedica o tome razbijao glavu!\nA najposlije: zašto joj ne bi Fedica tu radost priuštio? Mi smo veseljaci dobra srca – rekao si ti jedne\nnoći kad smo ono jednog pijanoga starca digli iz snijega i odnijeli u kavanu da na biljaru prespava noć.\nZašto ne bi dakle naš Fedica vršio samaritansku dužnost naprama siroti osamljenoj i boležljivoj djevici?\n– Zašto bih ja dakle otkrio pred majkom ili pred sestrom sa Fedice koprenu u kojoj im se predstavio,\nkako iz majčinih riječi razabiram, u nekakvoj djevičanskoj slici? Uopće, kad o njem slušam govoriti\nsvoju majku, sve mislim u sebi: vidiš ti našega Fedicu kako on umije lijepo glumiti! (...)\nTvoj György\nDrugi polazni tekst\nDragi Muki!\n(...)\nBio sam prisiljen upotrijebiti sredstvo što si ga ti kod svoje stare tetke s uspjehom prakticirao. Uzeo\nsam pištolj: „Ili pet stotina, ili ćete me naći u ovoj sobi prostrijeljene glave.” Neću ti opisivati kakvim\nje očima gledala na pištolj u mojoj ruci; znam da nije bila rumenija nego tvoja tetka kad si se s\nnjome ovako našalio. Sve je htjela nešto govoriti, ali su joj usta bila ukočena... „Žao mi je, rekoh\njoj, ali meni drugo ne preostaje.” „Pa dobit ćeš, dat će ti se”, reče napokon, „kakav si ti to, zaboga!\nDobit ćeš...” A jutros mi je već donijela novce: „Eto ti, prodala sam kuću.” (...)\nTvoj György\nSmjernice\n• U uvodu:\n− ukratko predstavite autora i djelo\n− u jednoj ili više rečenica oblikujte tvrdnju kojom ćete odgovoriti na polazno pitanje i tako\nnajaviti ono o čemu ćete pisati u središnjemu dijelu eseja.\n• U središnjemu dijelu eseja razradite i argumentirajte svoju tvrdnju kojom ste odgovorili na\npolazno pitanje tako da argumentacija:\n− proizlazi iz razumijevanja djela u cjelini\n− proizlazi iz sadržajne i stilske analize polaznog teksta i njegove uloge u djelu u cjelini\n− bude povezana s književnopovijesnim kontekstom u kojemu je djelo nastalo.\nSvoj tekst rasporedite u odlomke koji su jasno, logično i smisleno povezani.\n• U zaključku sažeto istaknite ono najvažnije o čemu ste pisali u središnjemu dijelu eseja.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-2023-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2022-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2022,"schoolYear":"2021./2022.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2022/06/HRVB22ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2022-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-2022","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nAlbert Camus, Stranac\nBio je sam. Izvalio se bio na leđa, podvio ruke pod glavu, čelo mu je bilo u sjeni litice a tijelo\nna suncu. Plavi kombinezon isparavao se od vrućine. Malo sam se iznenadio. Za mene je cijela ta\npripovijest bila svršena i došao sam ovamo ne misleći više na to.\nČim me ugledao, pripodigao se i gurnuo ruku u džep pa sam, naravno, stegnuo Raymondov\nrevolver u džepu sakoa. Zatim se on ponovo izvalio, ali nije vadio ruke iz džepova. Bio sam\nprilično daleko od njega, desetak metara. Na mahove sam nazirao njegov pogled, između napola\nsklopljenih vjeđa. Ali uglavnom je njegov lik titrao u užarenom zraku preda mnom, šumor je valova\nbio još tromiji i spokojniji nego o podne. Isto ono sunce, isto ono svjetlo na istom onom pijesku što\nse protezao i ovdje. Već dva sata dan nije odmicao, već dva sata bio je usidren u oceanu usijana\nmetala. Na obzorju je prošao jedan brodić, nazreo sam krajičkom oka samo crnu mrlju jer sam\nnetremice motrio Arapina.\nPomislih da treba samo da se okrenem pa da se ovo svrši. Ali na leđa mi se bio navalio cijeli\nžal ustreptao od sunca. Učinih nekoliko koraka prema izvoru. Arapin se nije ni pomaknuo. Ipak je\njoš bio prilično daleko. Možda zbog sjene na licu učinilo mi se da se smije. Čekao sam. Obrazi su\nmi gorjeli od sunca i osjećao sam kako mi se kapljice znoja sakupljaju u obrvama. Sunce je peklo\nisto onako kao i onoga dana kad smo pokopali mamu i, isto onako kao i onda, najviše me boljelo\nčelo i sve su mi žile na njemu u isti mah damarale ispod kože. Zbog toga žara koji više nisam\nmogao podnositi, koraknuo sam naprijed. Znao sam da je to glupo, da se neću izbaviti od sunca\nako se pomaknem za jedan korak. Ipak, prešao sam jedan korak, samo jedan korak. A tada, ne\npridižući se, Arapin izvadi nož i pokaza mi ga na suncu. Svjetlo sijevnu na čeliku i kao da me\nduga svjetlucava oštrica pogodi u čelo. U isti mah znoj nakupljen u obrvama poteče mi odjednom\nniz kapke i zastre ih mlakim i gustim velom. Taj zastor od suza i soli zasjeni mi oči. Osjećao sam\nsamo cimbale sunca na čelu i, nekako nejasno, blistavi mač uperen iz noža svejednako u mene.\nTaj užareni mač palio mi je trepavice i kopao bolne oči. Tada sve zaigra preda mnom. Zapuhnu me\ntežak i vreo dah mora. Učini mi se da se nebo širom otvorilo da pusti ognjenu kišu. Napeh se svim\nsvojim bićem i ruka mi se zgrči na revolveru. Otponac popusti, dotaknuh glatki trbuh drška i tada\nsve poče, usred praska koji bijaše u isto vrijeme rezak i zaglušan. Stresoh sa sebe znoj i sunce.\nPojmih da sam poremetio ravnotežu dana, izvanrednu tišinu žala na kojem sam bio sretan. Zatim\nopalih još četiri puta u nepomično tijelo u koje se meci zabijahu a da se ništa nije opažalo. Bijahu\nto kao četiri kratka udarca kojima sam pokucao na vrata nesreće.\nSmjernice\n• Predstavite poetiku djela Stranac.\n• Objasnite na temelju djela u cjelini kako je karakter glavnoga lika doveo do ubojstva o kojemu\nse pripovijeda u polaznome tekstu.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini te protumačite njegovu ulogu u cjelini\ndjela.\n• Usporedite glavni lik djela Stranac s Raskoljnikovim iz romana Zločin i kazna.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2022-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2022-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2022,"schoolYear":"2021./2022.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2022/06/HRVA22ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2022-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-2022","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nJohann Wolfgang Goethe, Patnje mladoga Werthera\n29. srpnja\n(...)\nA smijem li reći, Wilhelme? Zašto ne bih smio? Ona bi sa mnom bila sretnija nego što je s njim!\nOn nije čovjek koji bi znao ispuniti sve želje onakva srca! Njemu nekako nedostaje osjećajnost –\nshvati to kako hoćeš – njegovo srce nije kadro djelovati na drugo srce tajanstvenom osjećajnom\nmoći, nije se kadro svezati s drugim srcem! Kad bismo Lotta i ja zajedno čitali neku knjigu, na\nstanovitu bi se mjestu u toj dragoj knjizi naša srca stopila u jedno. Bilo je stotinu takvih slučajeva:\nnešto treće bi svojim djelovanjem potaknulo naša osjećanja da se zajedno oglase. Dragi\nWilhelme! – On je doduše voli iz sve duše, a što sve takva ljubav ne zaslužuje?!\nNeki neugodni čovjek me je prekinuo u pisanju. Suze su mi se osušile. Rastresen sam.\nZbogom, dragi!\n(...)\n12. rujna\nBila je nekoliko dana na putu, išla je po Alberta. Danas sam joj ušao u sobu, pošla mi je ususret,\npoljubio sam joj ruku sa silnom radošću.\nKanarinac joj je sletio sa zrcala na rame. „To nam je novi prijatelj”, reče i zovne ga na dlan,\n„namijenjen je dječici. Umiljat je. Pogledajte ga! Kad mu dajem kruha, lepeće krilima i pristojno\nkljuca. Gle, zna me i poljubiti!”\nKad je ptičici ponudila svoja usta, ona ljupko pritisne njezine slatke usne kao da je kadra osjetiti\nblaženstvo toga užitka.\n„Neka poljubi i vas”, reče Lotta i okrene pticu prema meni. Mali kljun prevali put od njezinih do\nmojih usta, a kad mi je blago piknuo usne, osjetio sam dašak kao predosjećaj nježnoga užitka.\n„Ptičji poljubac”, rekoh, „nije čist od pohlepe, ptica traži hranu i povlači se nezadovoljno, ako\nosim ljubaznosti nema ničega.”\n„Ja joj dajem jesti iz svojih usta”, reče Lotta i uzme u usta nekoliko mrvica kruha za pticu,\nokrene joj se i pruži joj usne sa smiješkom u kojemu se iskrila bezazlena i samilosna ljubav.\nJa odvratih lice. Ne bi to smjela raditi! Ne bi smjela dražiti moju maštu tim prizorom rajske\nnevinosti i blaženstva, ni buditi moje srce, što ga ravnodušnost životne sudbine ipak ponekad\nuljulja u tup san! – A zašto ne? – Zna da joj neću ništa, jer zna koliko je ljubim.\nSmjernice\n• Predstavite poetiku djela Patnje mladoga Werthera.\n• Usporedite na temelju djela u cjelini Lottin odnos prema Wertheru i prema Albertu.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini.\n• Protumačite na temelju čitateljskoga iskustva kako ljubav motivira postupke književnih likova.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2022-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2022-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2022,"schoolYear":"2021./2022.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2022/08/HRVB22jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2022-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU jesen.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-2022","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nFjodor Mihajlovič Dostojevski, Zločin i kazna\n– Znaš šta, Dunja – poče ozbiljno i suhoparno – molim te, naravno, da mi oprostiš za ono jučer, ali\nsmatram da mi je dužnost da te opet podsjetim da ne odustajem od svog glavnog zahtjeva. Ili ja ili\nLužin. Ja mogu biti i hulja, ali ti ne smiješ. Jedna je hulja dosta. Ako se ipak udaš za Lužina, neću te\nviše smatrati za sestru.\n– Rodja, Rodja! Opet se ponavlja isto ono od jučer – jadovito cikne Puljherija Aleksandrovna. – I\nšto neprestano sam sebe nazivaš huljom, to nikako ne mogu podnijeti. I jučer je bilo isto tako...\n– Brate – odlučno mu i isto onako suhoparno odvrati Dunja – u svemu tome si ti negdje ipak\npogriješio. Noćas sam o tome razmišljala i otkrila pogrešku. Stvar je u tome što ti valjda misliš da\nse ja tobože nekome i za nekoga žrtvujem. A to uopće nije istina. Udajem se jednostavno za svoj\nračun zato što mi je teško samoj; a poslije, naravno, bit će mi drago ako budem mogla i pomoći\nsvojima, ali to nikako nije najvažniji motiv moje odluke...\n„Laže!ˮ pomisli Raskoljnikov grizući nokte od jada. „Oholica! Neće da prizna da želi biti\ndobročiniteljica! O, ti bijedni karakteri! I kad vole, baš kao da mrze... O, kako ih... sve mrzim!ˮ\n– Ukratko, udajem se za Petra Petroviča – nastavi Dunječka – zato što između dva zla biram\nmanje. Namjeravam pošteno učiniti sve što on od mene očekuje, prema tome, ne obmanjujem\nga... Što si se tako osmjehnuo?\nI ona plane, a u očima joj sijevne gnjev.\n– Baš ćeš sve učiniti? – priupita je on smješkajući se jetko.\n– Do određene granice. I način i forma prosidbe Petra Petroviča odmah su mi pokazali što on\ntraži. Dakako da mnogo drži do sebe, možda i previše, ali se nadam da drži i do mene... Što se\nopet smiješ?\n– A što se ti opet crveniš? Lažeš, sestro, svjesno lažeš, iz puke ženske tvrdoglavosti, samo da bude\npo tvome... Ne možeš ti poštovati Lužina jer sam ja njega vidio i razgovarao s njim. Prema tome,\nprodaješ se za pare i, prema tome, u svakom slučaju, postupaš nečasno, i drago mi je što se još\nmožeš bar crvenjeti!\n– Nije istina, ne lažem!... – uzvikne Dunječka, pošto je posve izgubila hladnokrvnost. – Ne bih se\nudala za njega kad ne bih bila uvjerena da me poštuje i da mu je stalo do mene; ne bih se udala za\nnjega kad ne bih bila čvrsto uvjerena da i ja mogu njega poštovati. Na svu sreću, mogu se o tome\npouzdano osvjedočiti, i to još danas. A takav brak nije nečastan, kao što ti tvrdiš! Ali i sve kad bi\nimao pravo, kad bih se zaista odlučila da učinim nešto nečasno, zar nije bezdušno od tebe što tako\ngovoriš sa mnom? Zašto tražiš od mene junaštvo koje možda i tebi nedostaje? To je despotizam, to\nje nasilje! Ako koga upropastim, upropastit ću samo sebe... Nikog još nisam zaklala!... Što me tako\ngledaš? Što si tako problijedio? Rodja, što ti je? Rodja, dragi moj!\nSmjernice\n• Predstavite poetiku djela Zločin i kazna.\n• Protumačite socijalnu i psihološku motivaciju Raskoljnikovljeve odluke da ubije lihvaricu.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini.\n• Povežite problematiku polaznoga teksta s književnim djelima slične problematike.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2022-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2022-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2022,"schoolYear":"2021./2022.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2022/08/HRVA22jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2022-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU jesen.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-2022","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nMiroslav Krleža, Gospoda Glembajevi\nBARUNICA CASTELLI mirno i žalosno: U čitavoj ovoj tamnoj glembajevskoj kući vi ste za mene bili\njedina traka svjetlosti! Ja sam ušla u ovu kuću iz materijalnih razloga: ja to priznajem! Sie müssen\ndas verstehen! Meine Kindheit hab’ ich nicht verbracht wie Sie, auf einem Kirmanperser Tausend\nund eine Nacht spielend!1 S dvanaest godina ja sam ostala na ulici, Leone. Vi ne znate što to\nznači smucati se po parkovima na jesenjoj kiši, gladan i poderan i bez krova! Vi ste počeli živjeti\ns rentom od dvadeset funti mjesečno, a ja s poderanim cipelama i s jednom starom lisicom oko\nvrata! Meine Glembay-Ehe war eine finanzielle Transaktion!2 Ja to priznajem! I vidite: ja sam imala\niza sebe tada već jedan degenerirani brak sa šezdesetogodišnjim barunom Castellijem i mnogo\ntoga, no vjerujte mi, ja govorim pred mrtvim licem ovoga starca: za sve ono što sam ja morala u\novim posteljama i u ovom braku, ja sam bila vrlo slabo plaćena! Und ich weiss es nicht: vielleicht\nexistiert Etwas über uns,3 ali ja sam, tako mi Bog pomogao, tu svoju glembajevsku transakciju\nvrlo skupo platila! Krvavo! Furchtbar blutig!4 Vi znate i sami tko je bio vaš otac! I sve ono što ste vi\nnjemu gore u sobi noćas nabrojili, sve sam to ja gledala iza kulisa punih dvadeset godina. (...) i taj\nčovjek koji je mogao da zgazi nečiju egzistenciju (...), taj čovjek je postao ocem mog djeteta! Oliver\nje čisti, izrezani on! Und alles furchtbar Dunkle in diesem Kind,5 to je moj križ! Dobro: dečki se\ndogovorili i htjeli da orobe nekakvog kasira ciglane! (...) Ali nije najgori kriminal u tome kad ovakav\nšesnaestogodišnji Glembay nabije lovačku pušku da orobi kasira: to je bez sumnje grozno! Das\nSchrecklichste von allem ist aber, dass ich das gewusst habe!6 Zločin je rastao u krvi toga dečka\nneprekidno i ustrajno šesnaest godina, zločin je počeo onoga dana kada je to dječje srce zakucalo\nu mojoj utrobi! (...) A vi, Leone, najbolje znate i sami što znači glembajevska krv! (...)\nLEONE: Sve je to mutno! Mene boli glava i ja počinjem da se gubim u svemu tome. Ja sam\nse vratio ovamo potpuno miran, sve one ljage što sam ih godinama osjećao zbog oskvrnute\nuspomene na moju majku, sasvim su već bile ishlapjele, i ja sam bio potpuno miran! Ali, molim vas,\novo sve oko vas ovdje! Ovaj Oberleutnant, ovaj vaš ispovjednik, pa onda smrt one trudne žene, i\nona stara pod konjima, čitav način kojim se ovdje u kući govorilo o tim stvarima, to morate shvatiti\nda me je nerviralo!\nSie müssen das verstehen! Meine Kindheit hab’ ich nicht verbracht wie Sie, auf einem\nKirmanperser Tausend und eine Nacht spielend! – Vi to morate razumjeti! Ja nisam provela svoje\ndjetinjstvo kao vi igrajući se Tisuću i jedne noći na kirmanskom perzijskom sagu!\nMeine Glembay-Ehe war eine finanzielle Transaktion! – Moj glembajevski brak bio je financijska\ntransakcija!\nUnd ich weiss es nicht: vielleicht existiert Etwas über uns, – I ja ne znam: možda povrh nas postoji Nešto,\nFurchtbar blutig! – Strahovito krvavo!\nUnd alles furchtbar Dunkle in diesem Kind, – I sve ono tako strašno mračno u tom djetetu,\nDas Schrecklichste von allem ist aber, dass ich das gewusst habe! – Ali od svega je najstrašnije\nto, da sam ja to znala!\nSmjernice\n• Predstavite poetiku djela Gospoda Glembajevi.\n• Protumačite odnos barunice Castelli i Leonea Glembaja na temelju djela u cjelini.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini. Objasnite ulogu polaznoga teksta u\ndjelu u cjelini.\n• Protumačite kako glembajevsko nasljeđe utječe na sudbinu Leonea Glembaja.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2022-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2021-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2021,"schoolYear":"2020./2021.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2021/06/HRVB21ljeto2.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2021-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nPolazni tekst\nAnte Kovačić, U registraturi\nBože moj! Kako li je voljko i ugodno u tom niskom krevetu, na tim mekanim perinama, među\ntim nabuhlim jastucima... Podovi se lašte, sagovi, protkani zlatnim i srebrnim žicama, čarobno\nljeskaju... Pa ove slike... Baš ta sučelice krevetu: golo tijelo žene, božanske ljepote!... Odvrni oči,\nIvice Kičmanoviću! Odvrni... A ono ogromno zrcalo: na, sav se vidim u njemu... I tamo se odrazuje\nta gola ljepota... Odvrni oči, Ivice, zrcalo te izdaje... Oh, majko moja, ti priprosta, ti pobožna\nseljakinjo! Stid me je! Stid... Odvrni oči od svega!\nKako sam ja u ovom divnom krevetu? Šta je to bilo?\nIvica Kičmanović prikrije oči i obraze objema rukama. Krepke ruke i jaki laktovi legoše mu na\nširoka mladenačka prsa...\nŠta je to bilo?\nIma mi dvadeset godina! Je li moguće?\nZar tako hitro? Uz toliko muka i tegoba? Pa ta rajska noć... Oh, ja snivam i bolan i čaroban\nsan na tvrdoj seljačkoj klupi... možda u zelenoj travi? Ta ja sam toliko puta divno snivao pod onim\nstarim seljačkim krovom, u onim mojim milim bregovima, kano da me oblaci nose na laganim\nsvojim ramenima... Možda i sada snivam... Nije, nije dvadeset godina...\nŠta je to bilo?...\nGozba! Sjajna gospodarska gozba, pa svečani govori, pa pjevanje... onda mir... žarko pa\nslabo svjetlo, pa onaj stisak ruke... onaj oganj, ona strast... pa tada...? Ah, možda bijaše to samo\nseljačka svadba? Možda je i moj otac dudao u svoj veseli bajs? Možda to tek mene uvedoše u\nbračnu komoricu s ljubom mojom... a muzikaši i svatovi još pjevaju za rastanak onu melankoličnu\npjesmu:\n... Zbogom, zbogom, Jelice,\nDjevičanstva tvojega\nNikad više ne bude!...\nOh, što bijaše...?\nNije to san... nije san... Bože moj!\nSmjernice\n• Predstavite djelo U registraturi u kontekstu književnopovijesnoga razdoblja u kojemu je nastalo.\n• Portretirajte Lauru na temelju djela u cjelini.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini i protumačite njegovu ulogu u cjelini\ndjela.\n• Usporedite Ivicu Kičmanovića sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2021-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2021-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2021,"schoolYear":"2020./2021.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2021/06/HRVA21ljeto2.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2021-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA HRV A.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nMiroslav Krleža, Povratak Filipa Latinovicza\nSve je to bilo grozničavo one noći i suludo, doslovno katastrofalno, a ta se napetost doživljavanja\nviše nije vraćala. Sivjelo je sve polagano i venulo kao list poslije zapare! Ništa nije naslikao Filip od\none poplave zamisli: isprecrtao je nekoliko kartona za nacrt bakroreza, i sve je ostalo nezapočeto\nu mapi na ormaru. I ništa ne radi, ništa ne čita, nego leži i polagano osjeća tihu grižnju u sebi: od\nnepomičnosti, od jalove dosade.\n„Tako će ga sada pozvati na večeru, pak će se gnjaviti sa starim Liepachom, onda će se\nodvući do kavane i ondje čitati novine, čekati Bobu, i sve ne će zapravo imati nikakve prave\nsvrhe! Vući će se prašnom cestom do vinograda, umoran, sa snom na trepavicama, a s teškim i\nbezdanim bdjenjem pred sobom.”\nKod krčmara Šimuneka još su rasvijetljeni prozori. (...) Lepet krilima u kokošinjcu, izdaleka\nglas sove u šumi, vjetar u krošnjama i onda duga, neugodna tišina. Iz Kostanjevca, dolje odmah\npod mlinom, jedan podmukli pucanj, a onda opet sve tiho. Spavaju stari slamnati krovovi, štagljevi\ni patke po kokošinjcima. Vlažan miris kukuruznih hljebova iz toplih krušnica miješa se s vonjem\ngoveda i gnoja, šušti kukuruzovina na vjetru, tu i tamo kapljica teške kiše, dolazi polagano jesen, a\non tu dangubi s nekakvom čudnom gnjilom ženom.\n„Što je večeras bila tako nervozna? Odbila se od njega na hladnoneshvatljiv razmak,\nod prvog dana kako se pojavio ovdje onaj problematični čovjek. Tko je taj Kyriales? Odakle je\ndoputovao? Žvače svoju englesku lulu, sjedi u oblaku slatkog dima i tako čudno gleda kao da\nznade nešto više od običnih smrtnika ljudi. On je stari, dugogodišnji Bobin prijatelj, a gdje se\nupoznala ta bolesna žena s tim Gruzinom? Grk sa Kavkaza, doktor medicine, pustolov, što je taj\nčovjek s dugim, od dima žutim, tankim, hladnim prstima? Zašto je doputovao, što radi tu i kamo\nputuje? Kamo se sve to uopće giba?”\nSmjernice\n• Predstavite poetiku djela Povratak Filipa Latinovicza.\n• Protumačite odnos Filipa Latinovicza i Kyrialesa na temelju djela u cjelini.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini i objasnite njegovu ulogu u cjelini djela.\n• Usporedite Filipa Latinovicza sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2021-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2021-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2021,"schoolYear":"2020./2021.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2021/08/HRVB21jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2021-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU jesen.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nWilliam Shakespeare, Hamlet\nPrvi polazni tekst\nAl otkrivenje takvih vječnih stvari\nDUH: Ja sam duh tvog oca, osuđen\nNe dolikuje ušima od mesa\nObilaziti noću neko vrijeme,\nI krvi. Slušaj me, o, slušaj\nA danju postit, zatvoren u ognju,\nPa ako ikad ljubio si oca –\nDok plamen taj me sveg ne očisti\nOd gadnih grijeha, koje za života\nHAMLET: O, Bože moj!\nPočinih. Da mi nije zabranjeno\nKazivat tajne moga zatvora, DUH: Osveti gadno mu\nIspričati bih štošta mogao, I bezdušno umorstvo!\nOd čega bi i ponajblaža riječ HAMLET: Ha! Umorstvo!\nStrahotom tebi dušu prožela\nDUH: Umorstvo već je samo sobom gadno,\nI mladu tvoju krv zaledila\nAl ovo ti je ponajgadnije\nI oči ti, ko zvijezde iz putanja,\nI najgrđe i najbezdušnije!\nIzbacila iz duplja njihovih,\nA kudrave i guste uvojke HAMLET: O, kazuj mi ga bez odlaganja,\nRazmrsila, te svaka bi se vlas Da uzmognem na brzim krilima,\nZa sebe sama nakostriješila Ko miso ili mašta ljubavna,\nKo bodljike u ljutog dikobraza. Pojurit i na svoju osvetu!\nDrugi polazni tekst\nKRALJ: Je l’ otac bio drag vam, Laerte? Od rođenoga gine obilja.\nIl tek ste kao neka slika bola – Što hoćemo uradit, valjalo bi\nLik bez srca? Uradit smjesta, čim i hoćemo,\nJer naše htijenje mijenja se i slabi\nLAERT: Što pitate me to?\nI odgađa toliko, koliko je\nKRALJ: Ja ne mislim da niste ljubili I prilika i jezika i ruku,\nSvog oca, nego znam da ljubav je I onda riječi „valjalo biˮ jesu\nZa vrijeme vezana, a život mi Ko dubok uzdah, koji blažeć zlijedi1,\nDokazuje da vrijeme gasi žar Al sad u živac čira. Hamlet je\nI vatru njenu. Ima neki gar Na povratku – što mislite uradit,\nIl fitilj u plamenu ljubavi, Valjanim da se sinom pokažete\nŠto hoće da ga oslabi, i ništa Svog oca – više djelom nego riječju?\nNa svijetu nema uvijek istu snagu\nJer kad se snaga odviše razbuja, LAERT: U crkvi ću mu grkljan prerezati!\nzlijedi – ranjava\nSmjernice\n• Predstavite djelo Hamlet u kontekstu književnopovijesnoga razdoblja u kojemu je nastalo.\n• Protumačite odnos Hamleta i Laerta na temelju djela u cjelini.\n• Usporedite polazne tekstove na sadržajnoj i stilskoj razini i objasnite njihovu ulogu u kontekstu\ndjela u cjelini.\n• Povežite tematiku polaznih tekstova s djelima slične tematike.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2021-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2021-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2021,"schoolYear":"2020./2021.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2021/08/HRVA21jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2021-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU jesen.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nAnte Kovačić, U registraturi\nIvica Kičmanović vukao se po nižim službicama od oblasti do oblasti... Samotan, mrk, strog\ni ozbiljan, nije ni s kim općio. Svatko mu bijaše tuđ, kano i on drugima. Nije imao ni prijatelja ni\nneprijatelja, a niti je on kome bio jedno ili drugo. (…)\nUgrabi omašan i otrcan spis o kaznenoj parnici hajdučice Lare, a onda segnu za svojim\nživotopisom u pretinac registratorskoga stola...\n– To je moje... i to će sa mnom! – razgovaraše mrmljajući sâm sa sobom u registraturi...\nIznenada se nečemu domisli, planuše mu obrazi i stade drhtat čitavim tijelom...\n– Tako je! Tako je! Dobro!... Zašto da ovdje ne svršimo među vama, djeco moja, drugovi moji,\nbraćo moja? Ta vi mi bijaste nakon „krvave svadbeˮ jedini na ovome svijetu s kojima se zabavljah,\ndrugovah i vodih srdačne razgovore... među vama vječno šutljivima... da, među vama valja\nsvršiti!... (…)\nI on zakračuna vrata, obazre se još jedared po svim kutovima i na prozore pa uvjerivši se da\nnema nigdje živa stvora izvuče iza spisa nekoliko boca tekućine i mirno stade polijevati spise.\nOnda nakvasi kazneni akt o parnici hajdučice Lare i svoj vjekopis pa napokon sama sebe...\nSada mu se rašire oči, a bjesnoća i ludilo raspiri mu čitavo biće...\n– Što da još krzmam? (…) Ipak je Laura majstorica! Oh! Laura!... Laura!... – I upali luč, baci je\nu tekućinu, i što bi okom trenuo, usplamti sve i probukta strašan oganj te razarajuća vatra zahvati\nsvu registraturu...\nDrugi polazni tekst\nMiroslav Krleža, Povratak Filipa Latinovicza\nAdvokat Vladimir Baločanski, sin bivšeg odjelnog predstojnika Baločanskog, zaljubio se u\ntu ženu dječački naivno i savršeno nevino. Od prvog dana on je njoj bio više dosadan nego\nzanimljiv, no upravo, odbijajući toga slabića često na nevjerojatno okrutnu distancu, ona ga\nje fatalno dotukla; moglo bi se reći doista, kao što se govorilo na ulici vulgarno: uništila. Zbog\nnje je Baločanski pao u teške novčane neprilike, u pronevjerenja većega stila, u krivotvorenja\nmjeničnih potpisa, a kad je dospio u zatvor, a žena mu se (prilično kukavno i namješteno) bacila\nosim toga još i kroz prozor, on je ostao Kseniji Radajevoj kao ostavština jedne drame: ona ga je\njednoga dana naslijedila kao pošiljku iz kaznionice. (…) One tri godine, dok je Baločanski ležao\nu Lepoglavi, proživjela je Ksenija Radajeva furiozno, vjenčavši se civilno s jednim politikantom i\nratnim bogatašem i bacajući novac tog veleindustrijalca kao korijandole1, te se ne bi moglo reći\nnije li već onda, u onom u svakom pogledu nerazumnom i razornom samouništavanju, bilo nečeg\nod samoubojstvene, visokouznemirene, upravo sulude naklonosti spram smrtonosnih užitaka koji\nsu joj konačno jednoga dana tako žalosno zavrnuli vratom.\nkorijandoli – papirnate vrpce\nSmjernice\n• Predstavite poetiku djela U registraturi i poetiku djela Povratak Filipa Latinovicza.\n• Portretirajte Lauru i Kseniju Radajevu (Bobočku) na temelju djela u cjelini.\n• Usporedite polazne tekstove na sadržajnoj i stilskoj razini.\n• Usporedite Lauru i Kseniju Radajevu (Bobočku) s barunicom Castelli iz djela\nGospoda Glembajevi.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2021-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2020-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2020,"schoolYear":"2019./2020.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2020/08/HRVB20jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2020-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRV B ESEJ.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nAnte Kovačić, U registraturi\n– Ja sam Laura G. – odsiječe ona nekako trpko. – A vi? Đak. Dakako, to svjedoči taj kup knjiga.\nVi ste po svoj prilici bliži rođak gospodaru ovoga doma?\n– Ne. Uzelo me od milosti, seljačkoga sina, da me uzgajaju poput takozvanog „siromašnog\nđaka“! – odgovorim.\n– A kako se zove taj siromašni đak?\n– Ivica Kičmanović!\n– Ivica! Ivica! – uskliknu rekao bi ushićenim glasom djevojka. – Sirotan Ivica! Eh, tada smo\nbraća: ja sestra, a ti brat! Oboje sirotani! – I ona me uhvati za ruke i tako me milo gledala, nu ja\ntome pogledu nijesam mogao odoljeti, već ponikoh nikom.\n– Brat i sestra – ponovi ona tiše. – Ne pristaješ li? Ej, pa kako će to lijepo biti! – I ona, ne\nočekujući moga odgovora, živo me cjelune u usta, u čelo, u oči... Nikada me još žena nije\npoljubila, osim moje majke. Polije me rumen do ušiju i ja se hrlo i oprezno ogledah ne bi li se gdje\nu blizini desio milostivi Mecena ili njegov alter ego, kumordinar Žorž... Ali sve bijaše mirno, tek je\nlagahan jutarnji struj ponjihavao granjem i cvijećem.\n– Sestro! – šapnem plaho i uhvatim obje njezine oble ručice... – Sestro! Ja sve to ne\nrazumijem... A što će reći? – zapnem ja, sjetivši se noćašnje moje zgode...\n– Tko? – uleti mi djevojka u riječ. – Tko? Ivice! Tko?\n– Ništa, ništa, gospodično!\n– Reci, Ivice, sve! Ispovjedi, brate! – privine se ona dražesnim stiskom do mene. – Ne zovi me\ngospodičnom. To je tako ružno. Ja ćutim da smo mi bliski kano da se zajedno rodismo i zajedno\nothranismo! Meni se tek čini da se negdje na dugo i dugo rastasmo, a evo danas opet nađosmo\nse zajedno! Ja sam samotna grana na ovome svijetu. Nemam nigdje baš nikoga!... – zaliju se\nnaglo suzama njezine oči... – Pa evo, sada će nam obadvoma biti lijepo i ugodno...\n– Da, nama će biti lijepo i ugodno! – uskliknem ja, i mi se uhvatismo za ruke i dugo se tako\ndržasmo, ne progovorivši ni jedno ni drugo. Ja oćutjeh da postajem neko drugo, novo biće. Duša\nmi se zanijela daleko, daleko preko brda i dolina tamo u naše seljačke bregove i lugove. Ah,\nda nam je tamo biti zauvijek samima... I snatreći tako opet je pogledah. Ona bijaše udubljena u\nmisli, a lišce vidjelo joj se tako nevino, tako svježe i nježno... I u taj tren zavrti mi neki otajni crv\nu srcu i ja se naglo prenem iz svoga slatkoga snatrenja, trgnem rukama i izvinem ih iz njezinih.\nPromrmljam teško, kano da sam zahripio: – Lauro, sestro, jao meni, jednoga samo da nije...\nštićenica i rođakinja toga staroga Mecene!... Rođakinja!?\nOna skoči, problijedi u licu i posivi, a ustašca joj stade stezati neka užasna trzavica...\n– Zbogom! – odsiječe kratko. – Vi ne razumijete mene – vi ne znate ništa, gospodičiću moj!\nZbogom! Učite... učite... – I ona me pusti, leteći tihim i žurnim koracima u Mecenov dom...\nSmjernice\n• Predstavite djelo U registraturi u kontekstu književnopovijesnoga razdoblja u kojemu je nastalo.\n• Protumačite odnos Ivice i Laure na temelju djela u cjelini.\n• Interpretirajte polazni tekst na sadržajnoj i stilskoj razini. Objasnite ulogu polaznoga teksta u\nkontekstu djela u cjelini.\n• Usporedite Lauru sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2020-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2020-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2020,"schoolYear":"2019./2020.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2020/08/HRVA20jesen1.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2020-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRV A ESEJ.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nAnte Kovačić, U registraturi\n– Ima rubeninu, ima! – uzdahne majka. – Pa kako to, škola? Pa zašto nam ga ne pustiše\ngospoda? Što njemu treba škole?\n– Što ćeš? Tako ti je na ovom svijetu. Znaš, nijesam ni ja tamo šutio. Rekoh im svoju baš\nodrješito: Evo, kakve su to nove pravice? Prije bijaše otac gospodar svome djetetu na život i smrt.\nA danas? Tek je počelo raspoznavati roditelje, već čeka učitelj sa šibom da ga predaš u njegove\nruke. (...)\n– Muči ti, Jožina – župnik će na to. – Ti si muzikaš, pa razumiješ više od ostalih. A nije li\nti drago da znaš više od ostalih? Ha? Reci. – E, to je istina! – zavrtim ja glavom i pogrebem se\nsmeteno iza uha. – A čitati i pisati – nastavi župnik – nije li to mnogo više od muzike i bajsa?\nDanas su, dragane moj, teška vremena. (...)\n– Sve su to gospodski računi! – prekine župnika naš susjed, mali „kanonikˮ. – A mi nećemo\nda nam se djeca pogospode: Aj, jok! Čast svoj gospodi! Ali mi im poklanjamo gospodstvo. Djeca\nmi ne budu ni kuhana ni pečena po školama. Kruh ne bude rastao od prolijevanja tinte, već od\ngnoja. Mi ne živimo od šaranja pera po papiru, nego ti valja ljudski huknuti u šake, pak zadrijeti\nplugom i motikom u tvrdu kost zemaljsku.\nDrugi polazni tekst\nMilutin Cihlar Nehajev, Bijeg\nOvdje vidim pravi seljački tip. Ljudi kojima sve naziranje na svijet diktuje zemlja, mati\nhraniteljica. Nije čudo što ovaj čovjek ne trpi škole; on ne vidi nikakva saveza između pisanih slova\ni poljskih poslova. I to, što je nepovjerljiv prema gospodi, nema – čini mi se – razloga u tobožnjem\nnemaru kaputaša1 za nj ili u pašovanju2 raznih bilježnika. Moj Pajo ili Nikola ne razumije zašto\n„gospodinˮ živi; budući da mu nije jasno da se bez zemlje dade živjeti, drži ovakvu uredbu društva,\nkakva jest, nekim nepravednim usudom koji mu nije prijatan. (...)\n– Vi se svi tužite da se naše knjige ne prodaju, da književnik stradava. Ja ti kupujem gotovo\nsvaku našu knjigu; pa znaš što mi se čini da je krivo svemu? Vi ste svi nekakvi užasni slabići; ne\nvjerujete ni u sebe ni u drugoga, opisujete uvijek neke nervozne i izmučene ljude. A pogledaj ti nas\novdje što radimo po strani. Jedva ja razumijem to vaše umjetničko raspoloženje; a kako ćeš da se\nza nj zagrije široka masa puka? (...)\n– Ti si, Toša, previdio da ta velika masa puka nas ne razumije zato što nas ne čita, pače što\nnas ne može čitati. A da ima i manje analfabeta3, jedva da bi tvoj seljak iz Zdenaca imao kakav\ninteres za lijepu knjigu.\nkaputaš – onaj koji nema razumijevanja za probleme sirotinje\npašovanje – provođenje svoje volje\nanalfabet – onaj koji ne zna čitati ni pisati\nSmjernice\n• Predstavite poetiku djela U registraturi i poetiku djela Bijeg.\n• Portretirajte Ivicu Kičmanovića i Đuru Andrijaševića na temelju djela u cjelini.\n• Usporedite polazne tekstove na tematskoj, problemskoj i stilskoj razini.\n• Usporedite polazne tekstove s književnim djelima slične tematike.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2020-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2019-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2019,"schoolYear":"2018./2019.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2019/06/HRVB19ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2019-ljetni-rok-skolski-esej/paper.pdf","sourceName":"Esejski zadatak za B razinu.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nMiroslav Krleža, Gospoda Glembajevi\nLeone je ustao i stoji pred jednom izlizanom staromodnom cehovskom slikom u baroknoj rami.\nLEONE: A što misliš, illustrissime, zašto drži ovaj Glembay vagu u ruci?\nFABRICZY: Pa to je cehovski simbol, vaga. On je vagao i trgovao za čitavog svog života!\nLEONE: Da, on je vagao za čitavog svog života! To je mene još kao dečka uvijek zanimalo, kako\nje to, da je ovaj vagao tako da drži vagu koja je prevagnula! A poslije sam se dosjetio: to je prvi\nGlembay koji je vagao krivo!\n(...)\nFABRICZY: (...) Svi ovi Glembajevi radili su i stjecali u prilikama mnogo težim nego što su\ndanašnje i daleko je, dragi moj amice1, od onog Glembaja s vagom u ruci do tvog gospodina oca,\npravog i tajnog savjetnika, koji, kao što smo jutros čuli na svečanoj sjednici Trgovačke komore,\nzapošljava i hrani više od deset hiljada glava! Carissime2, da, tako je to!\nLEONE: Vama su još uvijek zdravice od banketa u glavi! Idite sutra na svečanu sjednicu\nTrgovačke komore, pak deklamirajte te svoje zdravice tamo! Što to meni pjevate, ja nisam nikakav\njubilarac ni bankir! Ja sam u ovoj kući prolaznik, meni ove slike govore stvari mnogo tamnije od\njedne zdravice! Za vas onaj Glembay drži u ruci crkvu, a za mene krvavi nož! Kako za koga! (...)\nJa sam rekao što sam čuo: da je ovaj Glembay varao na kartama, a onaj da je krivo vagao! Das\nhab’ ich gesagt! Kein Wort mehr!3\nFABRICZY: Jawohl, das ist die Bárbóczy-Legende: die Glembays sind Mörder und Falschspieler,4\ni svi su Glembajevi prokleti! To je bablja pripovijest!\nLEONE: Tako, to sve je die Bárbóczy-Legende? Prekrasno! Uzmi samo od Četrdesetosme\novamo, molim te lijepo! Za ovu Ludvigu sâm si rekao da se utopila, sama iz vlastite inicijative; i\nnjen sin skočio je u vodu iz vlastite inicijative. Das hast du selber gesagt!5 Brat ovog ajznbanera6\n(der die Wiener Hochbauer heiratete), der ist im Irrenhaus gestorben!7 Najstariji njegov sin, taj\nse je ustrijelio. (...) Tu je moja pokojna mama! Dobro! Ona nije Glembajica, ali ona se otrovala u\nkompleksu Glembay! Kannst du das vielleicht leugnen!8 Alice, a Alice, zar se nije utopila? Pokojni\nIvan zar nije pao iz trećega kata?\namice – prijatelju\nCarissime – Najdraži\nDas hab’ ich gesagt! Kein Wort mehr! – To sam rekao! Ni riječi više!\nJawohl, das ist die Bárbóczy-Legende: die Glembays sind Mörder und Falschspieler, – No da, to je ona\nbarbocijevska legenda: Glembajevi su ubojice i varalice,\nDas hast du selber gesagt! – To si rekao ti sam!\najznbaner – željezničar\n(der die Wiener Hochbauer heiratete), der ist im Irrenhaus gestorben! – (koji se oženio Bečankom Ho-\nchbaureovom), taj je umro u ludnici!\nKannst du das vielleicht leugnen! – Možeš li možda to poricati!\nSmjernice\n•• Predstavite djelo Gospoda Glembajevi u kontekstu književnopovijesnoga razdoblja u kojemu je\nnastalo.\n•• Portretirajte Leonea Glembaja na temelju djela u cjelini.\n•• Interpretirajte polazni tekst. Protumačite ulogu upotrebe njemačkoga i latinskoga jezika.\n•• Objasnite ulogu polaznoga teksta u kontekstu djela u cjelini. Protumačite ulogu barbocijevske legende.\n•• Usporedite Leonea Glembaja sa sličnim književnim likovima.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2019-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2019-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2019,"schoolYear":"2018./2019.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2019/06/HRVA19ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2019-ljetni-rok-skolski-esej/paper.pdf","sourceName":"Esejski zadatak za A razinu.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nTin Ujević, Igračka vjetrova\nPati bez suze, živi bez psovke,\ni budi mirno nesretan.\nTašte su suze, a jadikovke\nublažit neće gorki san.\nPodaj se pjanom vjetru života,\npa nek te vije bilo kud;\npusti ko listak neka te mota\nu ludi polet vihor lud.\nLeti ko lišće što vir ga vije,\nza let si, dušo, stvorena;\nza zemlju nije, za pokoj nije\ncvijet što nema korijena.\nDrugi polazni tekst\nTin Ujević, Dva puta jao\nMoj život! Ne govorite mi o njemu kako je jadan, kukavan, neispavan, sav pogažen i pogružen,\ndostojan stida i prezira. Kada bih još uvijek znao grčki – vidite li, i to sam zaboravio! – naveo\nbih za naslovni list tragedije moga života onaj koji počinje: io, io, papapai, dakle: jao, jao, kuku\nmeni. Kako bi samo lijepo bilo slobodno stupati po poljima, trčati, plivati, veseliti se bez zapreke!\nAli od svega toga ništa. Koliko sam puta pomislio o srećnome danu kada mi poderane cipele\nneće ranjavati nogu, kada ću imati na sebi sasvim čisto rublje, kada u džepovima neću morati\nda vucarim sve nekakve otrcane knjižice i masne bilješke. Kako bih se napokon osjetio blaženim\nveslajući po jezercima zaokruženim baršunastim gajevima! Nego život me evo tako spleo, uništio,\nšatro, nije mi dao nikakve slobode ni ljubavi, i sapeo me kao kliještima među dva prokleta kukavna\nepigrama. Koliko sada vidim kako smo lično nemoćni (pred Augijasovim štalama1), mi mali pjesnici\ni sanjari, i kako smo osuđeni da budemo igračkom vjetrova i žrtvom svih moćnih i lukavih. Što ima\nlijepa da se sačuva od moje uspomene? – Samo moje suze i moje molitve, jer su barem one bile\nčiste. Ali je na tijelo i na dušu teško, po onoj riječi, pogledati bez pečali2 i gađenja. Jer sve evo biva\nrana, modrica, čir, stigma, gnoj i brazgotina. Jao, jao, jao.\nAugijasove štale – simbol velike prljavštine i neurednosti\npečal – tuga, nevolja, jad\nSmjernice\n•• Predstavite stvaralaštvo Tina Ujevića u kontekstu vremena u kojemu je stvarao.\n•• Predstavite tematska i stilska obilježja Ujevićeva pjesništva te ih povežite s konkretnim\npjesmama i/ili zbirkama.\n•• Usporedite polazne tekstove na sadržajnoj i stilskoj razini.\n•• Protumačite univerzalnost tematike polaznih tekstova i povežite ih s djelima slične tematike.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2019-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2019-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2019,"schoolYear":"2018./2019.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2019/08/HRVB19jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2019-jesenski-rok-skolski-esej/paper.pdf","sourceName":"Esejski zadatak za B razinu.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nHenrik Ibsen, Nora\nHELMER: (...) Večeras ću se posvetiti samo tebi, ti mala, bespomoćna djevojčice. Ali najprije da\nvidimo što je tamo. (Ide prema vratima predsoblja.)\nNORA: Što tražiš vani?\nHELMER: Da vidim samo je li došlo kakvo pismo.\nNORA: Ne, nemoj, Torvalde.\nHELMER: Zašto ne?\nNORA: Torvalde, molim te. Nema nikakve pošte.\nHELMER: Samo da vidim. (Hoće da ode u predsoblje.) (Nora za glasovirom udara prve taktove\ntarantele.)\nHELMER (stane na vratima): Aha!\nNORA: Ako mi sutra valja plesati, onda moram prije s tobom vježbati.\n(...)\nNORA (uzima tamburin i dug šareni šal iz kutije, brzo se ogrne i skoči naprijed): Sviraj, ja ću\nplesati! (Helmer svira, Nora pleše, Rank stoji pokraj glasovira za Helmerom i promatra.)\nHELMER (svirajući): Lakše, lakše.\nNORA: Ne znam drukčije.\nHELMER: Ne tako divlje, Nora!\nNORA: A baš ovako treba.\nHELMER (prestane): Ne, ne, tako to ne ide.\nNORA (smije se i maše tamburinom): Zar ti nisam rekla?\nRANK: Čekajte, ja ću.\nHELMER (ustane): Hajde samo. Ovako ću je lakše ispravljati. (Rank sjeda za glasovir i svira. Nora\npleše što dalje sve življe. Helmer stoji pokraj peći i stavlja primjedbe. Nora se na njih ne obazire,\nkosa joj pada niz pleća. Ona se na to nimalo ne osvrće, nego nastavlja ples.)\nGĐA LINDE (ulazi, zastane kao prikovana na vratima): Ah!\nNORA (plešući): Ovdje je veselo, Kristina!\nHELMER: Ali, draga Nora, ti plešeš kao da je o glavu!\nNORA: Pa i jest.\nHELMER: Prestani, Rank, to je sasvim ludo. Prestani, kažem ti! (Rank prestaje svirati. Nora\nodjednom zastaje.)\nHELMER (prilazeći joj): Nikad ne bih pomislio: pa ti si sve zaboravila.\nNORA (odbacuje tamburin): Eto, vidiš.\nHELMER: Zbilja treba sve iznova.\nNORA: Vidiš sad i sâm. Moraš sa mnom vježbati do posljednjeg trenutka. Hoćeš li, Torvalde?\nHELMER: Hoću, dakako.\nNORA: Večeras i sutra ne smiješ ni na što misliti nego samo na me. Ne smiješ otvoriti ni jedno\npismo, čak ni naš sandučić.\nSmjernice\n•• Predstavite djelo Nora u kontekstu književnopovijesnoga razdoblja u kojemu je nastalo.\n•• Prikažite temeljne dramske sukobe u djelu Nora.\n•• Interpretirajte polazni tekst i objasnite čime je motivirano Norino ponašanje u polaznome tekstu.\n•• Usporedite Noru sa sličnim književnim likovima.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2019-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2019-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2019,"schoolYear":"2018./2019.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2019/08/HRVA19jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2019-jesenski-rok-skolski-esej/paper.pdf","sourceName":"Esejski zadatak za A razinu.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nFranz Kafka, Preobrazba\nSlušajući te majčine riječi, Gregor spozna kako je nedostatak svakog neposrednog kontakta\ns ljudima, a spojen s jednoličnošću života usred obitelji, morao u toku ova dva mjeseca pomutiti\nnjegov razum, jer drugačije nije mogao sebi objasniti da je ozbiljno mogao željeti da mu isprazne\nsobu. Bi li zaista volio da mu se topla soba, udobno namještena baštinjenim pokućstvom\nprometne u spilju, u kojoj bi, doduše, onda po miloj volji mogao puziti u svim pravcima, ali bi\nistovremeno brzo i potpuno zaboravio svoju ljudsku prošlost? Tȁ već sada nije bio daleko od toga\nzaborava, i samo je živnuo čuvši majčin glas što ga već tako dugo nije slušao. Neka se ništa ne\niznese iz sobe; sve je trebalo ostati; nije mogao da se odrekne korisnog utjecaja namještaja na\nsvoje stanje; a bude li ga namještaj smetao da besmisleno gmiže unaokolo, to onda neće biti\nnikakva šteta, već velika prednost.\nDrugi polazni tekst\nRanko Marinković, Kiklop\nNeman golema, ispunila vidno polje jednoga oka (na drugo je zažmirio).\nAli ne trepće Melkior.\nGigantski kukac – svežder, pantofag (već ga je Edgar Allan Poe opisao) probija se teško kroz\nguštaru. Smetaju mu noge, rogovi, oklop ga poklopio... ali oči radoznalo izbacio naprijed, izvan\nglave – probija se proždrljivo svom cilju – oku Melkiorovu.\nNe trepće Melkior.\n– Čuj me, duše... – prozbori u posljednji čas svoju besjedu (rogovima će mi oko probiti) no\nkukac nezadrživi već mu je prekrio sav vid, ugasio svjetlost, zaklonio svijet...\n– Navalio je kamen – reče Melkior i spusti glavu nemoćno na zemljina njedra: majko moja...\nZačuje tutanj u dubini pod sobom. Ispod njega zadrhtala je zemlja.\nHropće zemlja razrovana, ranjena, već je udaraju njegova kopita.\n– Polifem-kiklop dolazi!\nA kad je očima povratio vid... na horizontu gorjelo je nebo. Praskave zvijezde rigale su vatru sa\nvisine.\nČuo je riku uplašenih zvijeri u daljini.\n– Zoopolis! – reče s nekom nadom i čudan osmijeh ozari mu lice bezumnim sjajem.\n– Utvrđeni grad!\nSmjernice\n•• Predstavite poetiku djela Preobrazba i poetiku djela Kiklop.\n•• Portretirajte Gregora Samsu i Melkiora Tresića.\n•• Usporedite polazne tekstove na sadržajnoj i stilskoj razini.\n•• Protumačite ulogu polaznih tekstova na temelju djela u cjelini.\n•• Usporedite polazne tekstove s književnim djelima slične problematike.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2019-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2018-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2018,"schoolYear":"2017./2018.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2018/06/HRVB18ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2018-ljetni-rok-skolski-esej/paper.pdf","sourceName":"Esejski_zadatak_za_B_razinu.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nPrvi polazni tekst\nAntun Branko Šimić\nOpomena\nČovječe pazi\nda ne ideš malen\nispod zvijezda!\nPusti\nda cijelog tebe prođe\nblaga svjetlost zvijezda!\nDa ni za čim ne žališ\nkad se budeš zadnjim pogledima\nrastajo od zvijezda!\nNa svom koncu\nmjesto u prah\nprijeđi sav u zvijezde!\nDrugi polazni tekst\nJosip Pupačić\n*\n* *\nZvijezda da mi je biti,\ni živjet kao zvijezda\nnegdje visoko, visoko.\nPa da netko za mene\nbrojeći zvijezde kaže:\nOno je moja zvijezda.\nZvijezda da mi je biti.\nSmjernice\n•• Predstavite Antuna Branka Šimića i Josipa Pupačića u kontekstu književnopovijesnih razdoblja\nu kojima su stvarali.\n•• Opišite tematske i stilske značajke Šimićeve i Pupačićeve lirike.\n•• Usporedite polazne tekstove.\n•• Usporedite temu polaznih tekstova s djelima slične tematike.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2018-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2018-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2018,"schoolYear":"2017./2018.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2018/06/HRVA18ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2018-ljetni-rok-skolski-esej/paper.pdf","sourceName":"Esejski_zadatak_za_A_razinu.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nWilliam Shakespeare, Hamlet\n(Ulazi Hamlet sa dva ili tri glumca.)\nHAMLET: Govorite taj govor, molim vas, kako sam ga ja vama izgovorio; okretno, s lakoćom; jer\nako ga afektirano izgovorite, kao što mnogi glumci čine, bilo bi mi draže da gradski telal1 viče moje\nstihove. I nemojte odveć rukom sjeći zrak, ovako (pravi kretnje rukama po zraku); nego budite\nodmjereni u svemu. (...)\nPRVI GLUMAC: Ja vam to obećajem.\nHAMLET: Nemojte biti ni suviše ukočeni; dajte da vas vodi rasuđivanje. Uskladite radnju s\nriječima, a riječi s radnjom; i naročito pazite da ne prekoračite naravnu umjerenost. Jer sve što\nje pretjerano protivi se cilju glume kojoj je svrha i u početku i sada, bila i jest, da drži tako reći\nzrcalo prirodi; da bi pokazala vrlini njezine osobine, preziru njegovu sliku, a samome svijetu i\nsrži vremena njihov otisak i lik. I sada, ako se u tome pretjera, ili ako nešto ostane nedorečeno,\npremda će neuke natjerati u smijeh, ne može da ne rastuži upućene; a dopustit ćete da će sud\njednoga od ovih posljednjih prevagnuti cijelo gledalište prvih.\nDrugi polazni tekst\nJ. D. Salinger, Lovac u žitu\nPredstava nije bila tako loša kao neke koje sam gledao. Bila je, međutim, ipak bliže onim\nblesavim. Sadržaj: pet stotina tisuća godina života nekog starog bračnog para. (...) Alfred Lunt i\nLynn Fontanne igrali su stari par, i bili su vrlo dobri, ali nisu mi se baš svidjeli. Bili su, ipak, nekako\ndrukčiji od ostalih, to da. Nisu se ponašali kao obični ljudi, a nisu se ponašali ni kao glumci. Teško\nje to objasniti. Držali su se nekako više kao da su svjesni da su veličine i sve. Hoću reći, bili su\ndobri, ali bili su nekako previše dobri. Kad bi jedno od njih prestalo govoriti, ono drugo bi reklo\nnešto vrlo brzo, odmah nakon toga. To je trebalo izgledati kao da ljudi zaista pričaju i upadaju\njedno drugom u riječ. Nevolja je bila u tome što je sve to bilo isuviše slično tome kako ljudi\nrazgovaraju i upadaju jedno drugome u riječ. Ponašali su se nekako pomalo slično onome kako\nstari Ernie, dolje u Greenwich Villageu, svira klavir. Ako čovjek nešto čini isuviše dobro, onda,\nnakon izvjesnog vremena, ako ne pazi na to, počinje se time razmetati. A nakon toga nije više tako\ndobar kao što je bio.\nSmjernice\n• Predstavite poetiku djela Hamlet i poetiku djela Lovac u žitu.\n• Objasnite ulogu polaznih tekstova u kontekstu djela Hamlet i Lovac u žitu u cjelini.\n• Usporedite polazne tekstove.\n• Protumačite na temelju čitateljskoga iskustva odnos stvarnoga života i kazališta.\n• Obrazložite svoje tvrdnje.\ntelal – glasnik","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2018-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2018-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2018,"schoolYear":"2017./2018.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2018/08/HRVB18_jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2018-jesenski-rok-skolski-esej/paper.pdf","sourceName":"Esejski_zadatak_za_B_razinu_redovni_ucenici.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nPrvi polazni tekst\nFjodor Mihajlovič Dostojevski, Zločin i kazna\n„Ama, ne čudim se još mami, Bog bio s njom, ona je oduvijek bila takva, ali što je Dunji?\nDunječka draga, pa znam ja vas! Bilo vam je već dvadeset godina kad smo se posljednji put\nvidjeli: tada sam već shvatio kakvi ste. Eto, mama piše da Dunječka ‘može svašta podnijeti’. (…)\nJasno je: radi sebe, radi svog komfora, čak ni da bi se spasila od smrti, ne bi se nikad prodala,\na radi drugog se, eto, prodaje! Prodat će se radi dragog, obožavanog čovjeka! Eto u čemu je\ncijeli vic: prodat će se radi brata, radi majke. Sve će prodati! Eh, tu ćemo, ako treba, prigušiti i\nsvoj moralni osjećaj; slobodu, mir, čak i savjest, sve, sve ćemo iznijeti na pazar1. K vragu i taj\nnaš život! Samo da nam ta naša voljena stvorenja budu sretna! Štoviše, izmislit ćemo i posebnu\nkazuistiku2, naučit ćemo ponešto od jezuita3 pa ćemo možda i sami sebe umiriti na neko vrijeme,\nuvjerit ćemo se da tako treba biti, da zaista treba biti radi plemenita cilja. Takvi smo, eto, mi i sve\nje jasno kao dan. Jasno je da tu nije nitko drugi u pitanju nego Rodion Romanovič Raskoljnikov,\nda je on u prvom planu. Pa nego, molim lijepo, može ga usrećiti, uzdržavati ga na studijama,\nučiniti ga ortakom u kancelariji, osigurati mu budućnost; može se još poslije i obogatiti, steći\nugled i poštovanje, pa na kraju života biti i slavan čovjek. A majka? Pa tu je o njezinom Rodji\nriječ, o njezinom predragom Rodji, njezinom prvijencu! Pa kako ne bi za takva prvijenca žrtvovala\nčak i takvu kćer? O, draga i nepravedna srca! Pa što: ne bismo možda prezali ni od Sonječkine\nsudbine! Sonječka, Sonječka Marmeladova, vječna Sonječka, dok bude svijeta i vijeka! A jeste li vi\nžrtvu, tu žrtvu obje odvagnule? Jeste li? Možete li je podnijeti? Je li vrijedna? Ima li smisla? Znate\nli vi, Dunječka, da Sonječkina sudbina nije nimalo gora od života s gospodinom Lužinom? (…)ˮ\nDrugi polazni tekst\nHenrik Ibsen, Nora\nNORA: Sutra putujem kući – mislim, u naš stari gradić. Ondje ću lakše naći kakvu zaradu.\nHELMER: O ti ludo, neiskusno stvorenje!\nNORA: Moram pokušati steći iskustva, Torvalde.\nHELMER: Da ostaviš svoju kuću, muža, djecu! Pomisli što će reći svijet!\nNORA: To me se nimalo ne tiče. Znam samo da meni tako treba.\nHELMER: Pa to je strahota! Kako se možeš odreći svojih najsvetijih dužnosti?\nNORA: Što misliš, koje su moje najsvetije dužnosti?\nHELMER: Zar ti to uistinu moram reći? Zar to nisu dužnosti prema mužu i djeci?\nNORA: Imam ja i drugih svetih dužnosti.\nHELMER: Nemaš. Koje bi to bile?\nNORA: Dužnosti prema samoj sebi.\nSmjernice\n•• Predstavite poetiku djela Zločin i kazna i poetiku djela Nora.\n•• Objasnite ulogu polaznih tekstova u kontekstu djela Zločin i kazna i djela Nora u cjelini.\n•• Usporedite polazne tekstove.\n•• Protumačite na temelju čitateljskoga iskustva univerzalnost tematike polaznih tekstova.\n•• Obrazložite svoje tvrdnje.\npazar – tržnica\nkazuistika – dokazivanje lažnih teza\njezuiti – crkveni red","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2018-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2018-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2018,"schoolYear":"2017./2018.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2018/08/HRVA18_jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2018-jesenski-rok-skolski-esej/paper.pdf","sourceName":"Esejski_zadatak_za_A_razinu_redovni_ucenici.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nFjodor Mihajlovič Dostojevski, Zločin i kazna\nOsuda je bila ipak blaža, nego što se moglo očekivati, kad se uzme u obzir izvršen zločin,\na možda je bila blaža baš zato jer zločinac ne samo da nije nastojao opravdati sebe, nego je\nnekako i sam iskazivao želju da sam sebe okrivi još više. Sve neobične i osobite okolnosti u toj\nstvari bijahu uzete u obzir. O bolesnom i bijednom stanju zločinca, prije nego što je izvršio zločin,\nnije bilo ni najmanje sumnje. Što se nije okoristio grabežom, pripisalo se donekle probuđenom\nkajanju, donekle pak nepotpunom zdravlju umnih sposobnosti za vrijeme izvršivanja zločina.\nNenadano ubojstvo Lizavete poslužilo je dapače primjerom koji potvrđuje taj sud: čovjek izvršuje\ndva ubojstva, a onamo zaboravlja da su otvorena vrata! Naposljetku prijava njegova, da je on\nkrivac, u onaj čas, kad se stvar neobično zamrsila time što je fanatik Nikolaj klonuo duhom i lažno\nobijedio sebe, a pravi zločinac ne samo da se nije mogao jasno obličiti, nego se na njega nije\nskoro ni sumnjalo. (Porfirij je Petrovič potpuno održao riječ) – sve je to konačno pripomoglo da je\nokrivljeniku ublažena sudbina.\n(...)\nUkratko, završilo se tim da je zločinac osuđen na robiju drugog reda, svega na osam godina,\nuzevši u obzir da se prijavio sam, i neke druge olakotne okolnosti.\nDrugi polazni tekst\nAlbert Camus, Stranac\nSuci se vratiše. Nabrzinu pročitaše porotnicima niz pitanja. Začuh: „kriv za umorstvoˮ... „s\npredumišljajem”... „olakotne okolnosti”. Porotnici iziđoše, a mene odvedoše u onu prostorijicu gdje\nsam već jednom čekao.\n(...)\nČekali smo vrlo dugo, mislim gotovo tri četvrti sata. Napokon zazvoni zvonce. Odlazeći,\nbranitelj mi reče: – Predsjednik porote pročitat će najprije odgovore. Vas će uvesti tek kad se\nbude izricala osuda. – Lupali su vratima. Ljudi su trčkarali po hodnicima o kojima nisam znao jesu\nli blizu ili daleko. Zatim začuh kako netko prigušenim glasom čita nešto u sudnici. Kad zvonce\nponovo zazvoni i kad se vrata pregrade otvoriše, dočeka me tišina u sudnici, tišina i onaj čudni\nosjećaj koji me obuze kad primijetih da je mladi novinar odvratio pogled od mene. Nisam pogledao\nna onu stranu gdje je bila Marie. Nisam imao kad jer mi predsjednik sudskog vijeća nekako čudno\nsaopći da će mi glava biti odrubljena na javnom mjestu u ime francuskoga naroda. Učini mi se da\nprepoznajem osjećaj što bijaše ispisan na svim licima. Vjerujem da je to bila obzirnost. Žandari su\nbili vrlo blagi prema meni. Branitelj mi stavi ruku na zapešće. Nisam više ni na što mislio. Međutim,\npredsjednik me upita nemam li što dodati. Porazmislih i rekoh: – Nemam. – Zatim me odvedoše.\nSmjernice\n•• Predstavite poetiku djela Zločin i kazna i poetiku djela Stranac.\n•• Portretirajte Raskoljnikova i Mersaulta na temelju djela u cjelini.\n•• Usporedite polazne tekstove.\n•• Na temelju čitateljskoga iskustva objasnite odnos osobne i društvene odgovornosti i povežite\nga s polaznim tekstovima.\n•• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2018-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2017-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2017,"schoolYear":"2016./2017.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2017/06/HRVB.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2017-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI_ZADATAK_ZA_B_RAZINU.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nPrvi polazni tekst\nVjenceslav Novak, Posljednji Stipančići\nU takvoj neprekidnoj tišini gojila se uz Valpurgu Lucija, dočim je sin Juraj pripao skroz ocu od\nonoga dana kad je počeo da uči čitati. Lucija je bila vrlo živahna djevojčica, te je Valpurga poradi\ntoga pretrpjela mnogo prigovora od Stipančića koji je uopće za Luciju malo mario i samo jedno\nu pogledu njezinoga odgoja odrješito zahtijevao: da ne smije na ulicu gdje bi došla u dodir s\ngradskom dječurlijom... Mala bi se s velikom radošću, kad bi samo mogla, ukrala na presvođeni\nhodnik i gledala kao u čudu onaj slobodni plavi prostor nad crvenkastim krovovima susjednih kuća\ni pitajućim očima ispitivala kao zagonetku tijesnu uličicu kojom bi prošao sad koji odrasli čovjek a\nsad proletjelo koje dijete. A tek kad bi se zaletjela na trg djeca – njezina bi se duša od sreće smijala\nnjihovoj igri i svojim malim ručicama uhvatila bi se zida i plesala i vriskala od radosti jednako kako\nsu slobodni njezini vršnjaci i vršnjakinje izvodili svoje živahne kretove u svakojakim igrama... Djece\nbi onda nestalo, a ona bi gledala zamišljenim očima pravcem kud bi ih nestalo: Što je tamo? A kad\nbi njezino blijedo lice dobilo živahniji izraz probuđene želje da se zaleti za svojim vršnjacima, eto\nglasa stare Veronike: – Isuse i Marijo! Da te vidi milostivi gospodin!... Ti bi i na stube i možda – Bog\nbudi s nama – na ulicu! – U glavi stare Veronike odrazilo se na svoj način Stipančićevo uvjerenje da\nće rođeno gospodstvo djece stradati ako zađu na ulicu među običnu gradsku djecu.\nDrugi polazni tekst\nDinko Šimunović, Duga\nPa koliko je bila vitka, tako je hitro i skakala, da bi svak, čim je vidi, pomislio na srnu makar i ne\nznajući kako je zovu. Žarke joj oči tako su se sjale te bi mislio da su za sve prije nego za san. A\nbilo je samo deset godina toj Srni. (...)\nSerdar i Serdarovica mislili su da se ne pristoji njihovoj kćeri kad mu drago pjevati i koju god\npjesmu, zato što je bila žensko i zato što još nijesu kupili glasovira. A radi toga što je bila žensko,\nkratili su joj mnoštvo stvari, pa i stoga što su bili bogatiji od drugih.\nMajka i u polusnu opazi na prozoru djevojčicu.\n– Brunhilda!\n– Brunhilda! – ponovi za njom kao jeka otac.\n– Past ćeš sa prozora, Brunhilda!\n– Pa još si goloruka! Je li te ko vidio, Brunhilda? Kakva si to ti djevojčica!\n– A je li na tebi sunce? Bože sveti, brzo unutra, Brunhilda.\nI tako je Srna slušala svaki dan bezbrojne opomene za svoju lakoumnost, osobito kad bi htjela\nda učini nešto što se dopušta samo dječacima. (...)\nAli i jesti nijesu joj nikada do sita davali: „Dječaci mogu žderati koliko hoće. Oni treba da budu\nveliki i jaki, a ti moraš biti tanka i vitka.” – „I ne smiješ trčati jer se to djevojčici ne pristoji.” – „A\nmogla bi pasti i nagrditi lice”, govorili su naizmjence Serdar i Serdarovica.\nSmjernice\n• Predstavite roman Posljednji Stipančići u kontekstu književnopovijesnoga razdoblja u kojemu je\nnastao.\n• Portretirajte Luciju Stipančić na temelju djela u cjelini.\n• Usporedite polazne tekstove.\n• Protumačite na temelju čitateljskoga iskustva kako odgoj i društvena sredina određuju živote\nžena.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2017-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2017-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2017,"schoolYear":"2016./2017.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2017/06/HRVA.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2017-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI_ZADATAK_ZA_A_RAZINU.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nMilutin Cihlar Nehajev, Bijeg\n‒ Dakle, čujte me. Ja sam bio kod vas na predavanju i moram pohvaliti vaš interes za predmet.\nVidi se mar i ozbiljnost; dakako, da li će napredak biti prema vašem trudu, o tom se još ne da\nništa reći. Obučavanje je teška stvar i ište mnogo iskustva. Ja sam na primjer i sam opazio da\nste mjestimice odviše duboko i potanko zašli u predmet. Vi hoćete da dokažete da je psihologija\nuopće malo teška disciplina za gimnaziju? Jest, no zato se upravo valja držati knjiga i propisa\nvisoke vlade da ne izgubimo s vida temeljnu namjeru i svrhu obuke.\n(...)\nNajbolje je dakle držati se strogo knjige pa zahtijevati makar i nešto više učenja napamet...\n‒ Ali psihologiju...\n(...)\nAndrijašević osjeti na sebi ravnateljev uprti pogled i to mu bude neugodno.\n‒ Da, kazali su mi a i sam sam vidio – vi često puta zađete u druge discipline, date se odviše lako\nzavesti pitanjima koja đaci stavljaju profesoru – i koja pitanja imaju samo tu svrhu da se potroši dio\nškolskoga vremena. Govorili ste jednom – ako sam dobro informiran – o problemu materije, i čini\nse da ste zašli predaleko.\nDrugi polazni tekst\nMichel de Montaigne (1533. – 1592.), Eseji\nNeprestano nam se pune uši kao da se lijevkom toči u bačvu, a nama je samo ponavljati\nono što je rečeno. Htio bih da taj novi odgojitelj to ispravi i da na samom početku, već prema\nmogućnostima duha koji je dobio u ruke, počne stavljati ga pred izbor, dajući mu da sve iskuša,\nizabere i sâm odluči, ponekad mu probijajući put, a ponekad puštajući da ga sam prokrči. Ne\ntražim da on smišlja i sâm govori, nego hoću da svog učenika sluša kako on govori.\n(...)\nNeka od djeteta ne traži samo riječi iz zadaće, nego neka traži njihov smisao i bit; neka o uspjehu\nšto ga je postiglo ne sudi po njegovu pamćenju nego po njegovu životu. A ono što je naučilo neka\nmu predoči na stotine načina i neka sve to prilagodi najrazličitijim stvarima, kako bi mogao vidjeti\nje li sve dobro naučeno i usvojeno, (...).\nNeka mu sve prosije kroz gusto sito i neka mu ništa ne usadi u glavu samo na vjeru i zbog\nautoriteta; nek mu načela Aristotelova ne budu svete istine, a isto tako ni načela stoika i\nepikurovaca.1 Mora mu otvoriti mogućnost višestrukog suda: ako može, izabrat će, a ako ne može,\nostat će u dvojbi. Samo su ludi ljudi uvijek sigurni i odlučni.\nstoici i epikurejci – sljedbenici filozofskih škola u antici\nSmjernice za pisanje\n• Predstavite roman Bijeg u kontekstu književnopovijesnoga razdoblja u kojemu je nastao.\n• \u0007Smjestite prvi polazni tekst u sadržajni kontekst romana Bijeg. Portretirajte Đuru Andrijaševića.\n• Usporedite polazne tekstove.\n• Objasnite koji bi obrazovni model trebao biti temelj suvremenoga školstva.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2017-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2017-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2017,"schoolYear":"2016./2017.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2017/08/HRVB17jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2017-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nSofoklo, Antigona\nPrvi tekst\nDrugi tekst\nIzmena\nKreont\nJao meni! Promisli, o sestro, kako nam\nPreminu otac omražen i preziran! A ipak se usudi kršit naredbu?\nSam sebe krivcem zločina je otkrio\nI zato si je oba oka izbio. Antigona\nPa mati mu i žena – ista osoba –\nPletènom omčom skonča život Pa nije mi to valjda Zeus proglasio\nsramotno. Nit’ Pravda, vjerna druga donjih bogova,\nI treće, brata dva u jedan sebe dan Za ljude te je zakone postavila,\nPogubiše, smrt svojom rukom jadnici Nit’ tvoj je, mislila sam, proglas tako jak\nIstovremeno jedan drugom zadaše. Da ti ko smrtnik dići bi se mogao\nSad same nas dvije ostasmo i najgora Nad božje, nepisane, vječne zakone.\nJoš smrt nas čeka ako protiv zakona Od danas nisu ni od jučer, oduvijek\nMi pogazimo volju il’ vlast kraljevsku. Zauvijek žive, nitko ne zna kada se\nNa umu treba imati da žene smo: Pojaviše. A zbog njih nisam željela\nS muškarcima se ne možemo boriti; Od bogova bit kažnjena jer čovjeka\nPa onda jači nama zapovijedaju Pobojah se. Da umrijet ću, to znala sam –\nTe slušat nam je to i òd tog mučnije. Ta kako ne? – i da tvog nema proglasa.\nJa, dakle, molim one što pod zemljom su Umrem li prije reda, meni korist je.\nNek’ oproste jer evo sila priječi me; Tko živi kao ja u bijedi velikoj,\nA poglavare slušat ću. Jer raditi Smrt kako ne bi bila njemu korisna?\nŠto snage prelazi baš nije pametno. Pa zato ni ja žalit neću, snađe l’ me\nKob takva. Al’ da sina moje majke leš\nNepokopan ostavim, nju bi boljelo;\nA zbog te svoje sudbe ne žalostim se.\nSmjernice\n• Predstavite Sofokla u kontekstu književnopovijesnoga razdoblja u kojemu je stvarao.\n• Na temelju Sofoklova djela Antigona predstavite obilježja književne vrste kojoj pripada.\n• Usporedite polazne tekstove.\n• Usporedite Antigonu sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2017-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2017-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2017,"schoolYear":"2016./2017.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2017/08/HRVA.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2017-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU jesenski rok.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi tekst Drugi tekst\nAntun Gustav Matoš Dobriša Cesarić\nDjevojčici mjesto igračke Molitva\nLjerko, srce moje, ti si lutka mala, Što htjedoh reći, davno sve sam\nPa ne slutiš smisla žalosnih soneta, U djetinjstvu još reko bogu,\nKesteni pred kućom duhu tvom su meta, Ali da nisam kakav jesam\nJoš je deset karnevala do tvog bala. I da vjerovat još mogu,\nZa ovo dijete, koje volim,\nTi se čudiš, dušo. Smijat si se stala Ovako boga bih da molim:\nOvoj ludoj priči. Tvoja duša sveta\nJoš ne sniva, kako zbore zrela ljeta. Svojim si zvijezdama napiso\nGledaš me ko grle. Misliš – to je šala. U prazno nebo sve sudbìne,\nI mi smo samo tvoja mîsō,\nAl će doći veče, kad ćeš, ko Elvira, Što sija zvjezdama iz tmine.\ndon Huánâ sita i lažnih kavalira, Svejedno da li ćemo stići\nSjetiti se sjetno nježne ove strofe. Na vrhove il past u bezdan,\nMi moramo tek ići, ići\nSvud kuda put nas vodi zvjezdan!\nMoje će ti ime šapnut moja muza,\nA u modrom oku jecati će suza\nO dobri Bože, ako one\nKo za mrtvim clownom iza katastrofe.\nZvijezde što sjaju njoj sudbìnu\nU nevolju i jad je gone,\nU očajanje i crninu,\nMilostiv pogled na nju svrni,\nGle, ima oči kao lane,\nOd budućih joj dana crnih\nUčini, Bože, svijetle dane!\nSve zvijezde što joj život mrače,\nO dobri Bože, ti ugasi –\nSve one zvijezde koje znače\nBesanih noći sijede vlasi,\nI one koje bolest nose\nSmjernice U svojemu sjaju blijedom,\nI one koje prijete bijedom.\n• Predstavite Antuna Gustava Matoša i Dobrišu I one koje prijete bijedom.\nCesarića u kontekstu književnopovijesnih\nrazdoblja u kojima su stvarali. Al ako nećeš da ih zgasiš\n• Predstavite tematske i stilske značajke Matoševe I ako iskušenja treba,\ni Cesarićeve lirike. Ti moraš, Bože, da je spasiš\n• Usporedite polazne tekstove. Pred ponorima mostom neba.\n• Protumačite univerzalnost teme polaznih I nemoj da joj život zgadiš,\ntekstova i usporedite ih s književnim djelima Odrediv puno bola za nju,\nslične tematike. A kada spustiš ruku na nju,\n• Obrazložite svoje tvrdnje. Spusti je samo da je gladiš!","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2017-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2016-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2016,"schoolYear":"2015./2016.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2016/06/HRVB.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2016-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nWilliam Shakespeare, Hamlet\nHAMLET:\n(…)\nKako sve prilike svjedoče protiv mene;\nNa osvetu me potiču! Ta što je čovjek\nKad mu je glavni cilj i svrha u životu\nDa jede i da spava? Zvijer, i ništa više.\nZacijelo Onaj što nas s takvim umom stvori,\nDa naprijed gledamo i natrag, nije nam\nDao sposobnost i taj Bogu sličan razum\nDa neiskorišteni pljesnive u nama.\nJe l’ to živinska zaboravljivost il strah,\nTe odveć podrobno na ishod mislimo –\nTa misao, raščètvorena, ima jedan\nDijel samo mudrosti, tri kukavičluka –\nAl ne znam zašto ponavljam: »To treba činit«,\nKad imam povod, volju, moć i sredstva da to\nI učinim. Svi prosti primjeri me uče:\nEto, ta vojska tako golema i skupa,\nTankoćutan i nježan koju vodi knez\nKojega duh, slavohlepljem božanskim nadut,\nNevidljivome ishodu se drsko ruga,\nIzlažuć ono što je nestalno i ljudsko\nSvemu što smrt, sudbina i pogibelj smiju –\nZa ljusku jajinju. Uistinu bit velik\nNije bez velika se razloga pokrenut,\nNo velik povod nać za svađu i u slamki\nKada je čast na kocki. Kako ja tad stojim\nKojem je smaknut otac, majka okaljana?\nDok mi to krv uzbuđuje i mozak, puštam\nDa sve spava. (…)\nSmjernice\n• Predstavite djelo Hamlet u kontekstu književnopovijesnoga razdoblja u kojemu je nastalo.\n• Portretirajte lik kraljevića Hamleta.\n• Interpretirajte polazni tekst.\n• Objasnite svevremenost djela Hamlet.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2016-ljetni-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2016-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2016,"schoolYear":"2015./2016.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2016/06/HRVA.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2016-ljetni-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nMiroslav Krleža, Povratak Filipa Latinovicza\nLeži pod njegovim nogama ogroman čađavi velegrad u oblaku čađe i dima, u polusutonu\nfebruarskom, i to je ta toliko razvikana Evropa, ta zlatna blagoslovljena zemlja, s modrim toplim\njužnim zatonima gdje cvatu naranče, i s tim sjevernim strašnim čađavim tvrđavama gdje boluju\ndjeca od angine, a po mokrim ulicama se vuku škrofulozne1 djevojke. “Kako su žalosne sadrene\nHygieje po prašnjavim ljekarničkim izlozima! Kao lim dječjih igračaka, tako su tanke i prozirne i\nbesmislene sve ograde ljudskih shema, kojima se ljudi ograđuju od životne istine i od istinite\nživotne stvarnosti. To su zapravo sve pločice dječjih igračaka, religija, božićnih bedastoća, idila\nkoje uznose kult čiste laži, a iza svega proviruje roba: kupujte margarin, čokoladu, naranče,\nvaniliju, sukno, gumije! Ljudi su izmislili tapete, sagove, parkete, cijevi s ugrijanom vodom,\nstaklena vrata, zlatne ribice, kaktuse i čitave izloge knjiga po svojim stanovima, koje nitko ne čita.\nLjudi su nagomilali pod svojim krovovima kitajsku majoliku2, akvarele, damastne stolnjake, svilene\nčarape, krzna i dragulje. Ljudi lakiraju svoje nokte kao perverzni istočnjaci, kupaju se u mramornim\nkupaonicama, voze se u ugrijanim kočijama, piju gorke želučane likere, ali pojma zapravo nemaju\nšto je to životna stvarnost i kako bi trebalo živjeti?”\nSve češće i sve intenzivnije javljala se u posljednje vrijeme u Filipu misao, kako bi bilo da se\notkine od sve te čađe i od tog smrada i da otputuje kući u Panoniju, gdje nije bio već davno. Da\nproživi dolje kod majke na kostanjevečkom vinogradu jednu jesen, bogatu, mirnu, vinorodnu!\n“Mračna tintasta jugovina, blijeda mjesečina, mlačna noć s dalekim titranjem luči u dolini. Crne\nkrošnje hrastova na raskršćima, uznemirene zvjezdane niti iza maglenih mrlja, a gdjegdje u\ndalekim vinogradima po koji osamljeni pucanj, što se onda dugo razlijeva jarugama i poljima i\nnestaje u jarku kod mlina kao daleka grmljavina. Tišina u polju. Gdjegdje se čuje po koji list\nkukuruza kako se maknuo, kao da je prošla žena sa štirkanom podsuknjom preko staze i šušnula\npreko brvna. Teku vode kaljave, blatne, panonske i klokoću pod mostovima, a raspeto tijelo visi\npod topolom nijemo, plehnato, pod drvenim krovićem sa papirnatim cvijećem pod staklom u\nškrinjici, kao u staklenom lijesu: tu je čitavo poslijepodne plakao jedan slijepac s harmonikom,\na sada je tiho i nema nikoga. Spava Panonija i nema čađe, ni jurnjave, ni živaca. Ondje su noći\ntihe kao ugasla lula: bez svjetala, bez dima, bez čađe.\nškrofulozan – otečenih vratnih limfnih žlijezda\nkitajska majolika – kineska keramika\nSmjernice\n• Predstavite poetiku romana Povratak Filipa Latinovicza.\n• Portretirajte lik Filipa Latinovicza na temelju djela u cjelini.\n• Interpretirajte polazni tekst.\n• Povežite lik Filipa Latinovicza sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.\nESEJSKI ZADATAK ZA A RAZINU.indd 1 14.6.2016. 5:06:55","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2016-ljetni-rok-skolski-esej/page-1.png","page":1,"width":1063,"height":1474,"crop":{"x":0,"y":0,"width":1063,"height":1474}}]},{"id":"hrvatski-b-2016-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2016,"schoolYear":"2015./2016.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2016/08/HRVB_jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2016-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA B RAZINU jesenski rok.pdf","durationMinutes":160,"wordRange":{"min":350,"max":null,"acceptedMin":315,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nB\nPrvi tekst Drugi tekst\nAntun Gustav Matoš, Utjeha kose Stanko Vraz, Otkud modre oči?\nGledo sam te sinoć. U snu. Tužnu. Mrtvu.\nU dvorani kobnoj, u idili cvijeća, Mlađe b`jaše srce mi i glava,\nNa visokom odru, u agoniji svijeća, Ljubih djevu: kan1 u kćeri juga\nGotov da ti predam život kao žrtvu. Crne oči, crna kosa duga…\n(Nje raskršen kip2 već krije trava).\nNisam plako. Nisam. Zapanjen sam stao\nU dvorani kobnoj, punoj smrti krasne, Tvoje su oči modre, kosa plava,\nSumnjajući da su tamne oči jasne Kanda rajskim anđelom si drúga3,\nOdakle mi nekad bolji život sjao. Al obraza4 tvog je svaka pruga5,\nKanda duša davno ih poznava.\nSve baš, sve je mrtvo: oči, dah i ruke,\nSve što očajanjem htjedoh da oživim Da! ja slutim, te već od vjekova\nU slijepoj stravi i u strasti muke, Duše su nam sestre si i braća:\nŠto smrt razbi, bog stvori iznova.\nU dvorani kobnoj, mislima u sivim.\nSamo kosa tvoja još je bila živa Ko čist anđeo s rajske mi se uze\nPa mi reče: Miruj! U smrti se sniva. Sad Nje duša u Tvom kipu vraća,\nDa ju ljubim opeta bez suze.\nkan – kao\nkip – tijelo\ndrúga – prijateljica\nobraz – lice\npruga – crta\nSmjernice\n• Predstavite Antuna Gustava Matoša i njegovo stvaralaštvo.\n• Opišite tematske i stilske značajke Matoševe lirike.\n• Usporedite polazne tekstove.\n• \u0007Protumačite univerzalnost teme polaznih tekstova i povežite ih s književnim djelima slične\ntematike.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2016-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2016-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2016,"schoolYear":"2015./2016.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2016/08/HRVA_jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2016-jesenski-rok-skolski-esej/paper.pdf","sourceName":"ESEJSKI ZADATAK ZA A RAZINU jesenski rok.pdf","durationMinutes":160,"wordRange":{"min":400,"max":null,"acceptedMin":360,"acceptedMax":null},"maxScore":80,"scoreMultiplier":2,"rubricId":"school-essay-legacy","taskText":"ZADATAK ZA PISANJE ŠKOLSKOGA ESEJA\nA\nPrvi polazni tekst\nVjenceslav Novak, Posljednji Stipančići\nČinilo se da je otac radio pravo što je sudio u pogledu Jurjevoga talenta. U petoj godini znao je Juraj\nčitati i pisati, u šestoj godini razumio se već u čitanje geografske karte, znao naizust sve evropske\ndržave sa glavnim im gradovima i brojem stanovnika, znao imena gorâ, rijekâ i tako dalje. U osmoj go-\ndini podučavao ga je uz oca u školskim predmetima pater Bonaventura, silno jak čovjek okrugle glave,\nzaburmućenog nosa, crvenog lica, debelog vrata i velikog trbuha. Matematika je Jurju osobito išla u\nglavu, a učio je lako i jezike. U desetoj godini govorio je pored materinskoga jezika njemački i talijanski\ni prevađao iz latinskoga. Na očev imendan i iza svakoga ispita držao bi otac gozbu. To je bio jedini dan\nkad bi otvorio svoja vrata ljudima koji nijesu bili članovi njegove obitelji. (...) Najsvečaniji čas kod stola\nbila bi Jurjeva zahvalnica ocu i učiteljima što bi on u tri jezika govorio: njemački, talijanski pa latinski.\nDrugi polazni tekst\nMilutin Cihlar Nehajev, Bijeg\nSa pet godina Đuro je već razumio i znao više nego »đaci« koji su svršavali pučku školu. Sve je gledalo\nu njem neko gotovo čudovište, osobito otkad su u gimnaziji profesori potvrdili da takva talenta nije bilo\nza njihova vremena u školi. Još jače se raširi to uvjerenje kad su u omladinskim listovima počeli izlaziti\nneki Đurini književni pokušaji; sa sedamnaest godina vrijedio je već i u očima sudrugova i kod profesora\nkao sigurna buduća veličina.\nViše od svih bila je o tom uvjerena njegova mati. (...) Koliko je mogla, podupirala je sama sina,\nkupovala mu knjige, dala ga izučiti glasovir; a pomagao joj je i stric Toma koji je bio bez obitelji, pa je\nĐuku zavolio kao svoje dijete. Njemu za volju zvali su ga i Đurom, što nije obično ime u Primorju (...). U\nobitelji bilo je već kao stalno da će od tjelesno inače dosta slaboga dječaka postati slavan muž; a to je\npotvrdila i teta Klara koja je – sjećajući se da se je sa majčine strane sva obitelj sastojala od duševno\nsilno razvitih ljudi što su ipak više ili manje pustolovno završili život – važno kazala: Od ovoga dječaka\nbit će ili nešto ili ništa.\nSmjernice\n• Predstavite romane Posljednji Stipančići i Bijeg u kontekstu razdoblja u kojima su nastali.\n• Usporedite Jurja Stipančića i Đuru Andrijaševića na temelju djela u cjelini.\n• Usporedite polazne tekstove.\n• \u0007Protumačite na temelju čitateljskoga iskustva kako odgoj i društvena sredina određuju živote\nknjiževnih likova.\n• Obrazložite svoje tvrdnje.","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2016-jesenski-rok-skolski-esej/page-1.png","page":1,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2015-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2015,"schoolYear":"2014./2015.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2014/03/HRV_B15ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2015-ljetni-rok-skolski-esej/paper.pdf","sourceName":"HRV B IK-2 D-S029.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte sljedeći tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nMističan sonet\nO ponoći, kad crne ruže snijevahu\nUz hihot zvijezda u šedrvána1 pjeni,\nU gradu, kad me svi ismijevahu,\nO zlatnoj sjeni snatrih, o dragoj ženi.\nO kako čudno njene oči sijevahu\nKroz tajnu noći u slatkoj uspomeni!\nA dušom mojom, njenom harfom, pjevahu,\nJa ne znam kakvi zvuci, psalam meni.\nI zemlju, oblak, nebo i planete\nKo dragu gledah. Nađoh je ko Boga\nU suzi materije sakritoga,\nKroz zagonetku moje čežnje svete.\nLjepota, ljubav, sreća, sni i zánosi\nSu Bog, mistérij što u ženi zànosī.\nAntun Gustav Matoš\nšedrvan – vodoskok ili česma\nHRV B IK-2 D-S029\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite Antuna Gustava Matoša i njegovo stvaralaštvo.\n• Opišite tematske i stilske značajke Matoševe lirike.\n• Protumačite motive i stilske figure kojima se ostvaruju tema i ugođaj pjesme. Odredite ritam i\noblik pjesme.\n• Objasnite poantu pjesme Mističan sonet.\n• Obrazložite svoje tvrdnje.\nHRV B IK-2 D-S029","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2015-ljetni-rok-skolski-esej/page-4.png","page":4,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2015-ljetni-rok-skolski-esej/page-5.png","page":5,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-a-2015-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2015,"schoolYear":"2014./2015.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2014/03/HRV_A15ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2015-ljetni-rok-skolski-esej/paper.pdf","sourceName":"HRV A IK-2 D-S030.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte sljedeće tekstove nakon kojih slijede upute i smjernice za pisanje\nškolskoga eseja.\nPrvi tekst\nJohann Wolfgang Goethe, Patnje mladog Werthera\n16. srpnja\nNe znam kako mi je kad sam s njom. To je kao da mi se duša izokreće u živce. – Ima jedna melodija\nkoju svira na klaviru poput anđela, jednostavno, a produhovljeno. To joj je najdraža pjesma, a i mene\nliječi od svih patnji, dvojbi i ludorija, čim Lotta udari prvu notu. (…)\n18. srpnja\nWilhelme, kako bi naše srce izdržalo svijet bez ljubavi? To bi bilo kao čarobna svjetiljka bez svjetla.\nČim uneseš u nju malu luč, pojave ti se na bijelome zidu slike u svim bojama. Pa kada drugoga i ne\nbi bilo, osim tih prolaznih utvara, ipak je to sreća. Stojimo pred svojim zidom kao bezazlena djeca\ni zanosimo se tim čudesnim učincima. (…) „Vidjet ću je!“ kličem odmah ujutro čim se razbudim i\nradosno promatram divno sunce. „Vidjet ću je!“ I toga dana nemam više nijedne želje. Sve se gubi\nu čekanju večeri, kada ću je vidjeti.\nDrugi tekst\nAlbert Camus, Stranac\nUvečer je Marie došla po mene i upitala me bih li je htio uzeti za ženu. Rekoh joj da mi je svejedno,\nali da se možemo vjenčati ako baš želi. Htjela je znati volim li je. Odgovorih joj isto onako kako\nsam joj već jednom odgovorio, da to ništa ne znači, ali da je sigurno ne volim. – A zašto bi me onda\nuzeo za ženu? – pripita me. Objasnih joj da to uopće nije važno, i da se možemo uzeti ako baš želi.\nUostalom, to je ona tražila, a ja sam se zadovoljio da kažem da hoću. Tada napomenu da je brak\nozbiljna stvar. Odgovorih joj: − Nije. – Ona načas ušutje promatrajući me nijemo. Zatim opet\nprogovori. Htjela je samo znati bih li prihvatio tu ponudu i od neke druge žene s kojom bih bio\njednako vezan. Rekoh: − Naravno.\nHRV A IK-2 D-S030\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite djela Patnje mladog Werthera i Stranac u kontekstu književnopovijesnih razdoblja u\nkojima su nastala.\n• Portretirajte i usporedite Werthera i Mersaulta na temelju djela u cjelini.\n• Usporedite likove u polaznim tekstovima.\n• Povežite Wertherov i Mersaultov lik sa sličnim književnim likovima.\n• Obrazložite svoje tvrdnje.\nHRV A IK-2 D-S030","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2015-ljetni-rok-skolski-esej/page-4.png","page":4,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2015-ljetni-rok-skolski-esej/page-5.png","page":5,"width":993,"height":1404,"crop":{"x":0,"y":0,"width":993,"height":1404}}]},{"id":"hrvatski-b-2015-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2015,"schoolYear":"2014./2015.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2014/03/HRVB15jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2015-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRV B IK-2 D-S028.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte sljedeće tekstove nakon kojih slijede upute i smjernice za pisanje\nškolskoga eseja.\nPrvi tekst\nGiovanni Boccaccio, Dekameron\nVelim dakle da su godine od plodonosnoga Utjelovljenja Sina Božjega brojem do tisuću tristo\nčetrdeset i osme bile stigle, kad je dični grad Firencu, najljepši od svih italskih gradova, pohodila\nsmrtonosna kuga koja se, ili zbog djelovanja nebeskih tijela ili zato što je zbog naših zlih djela\npravedan gnjev Božji posla na smrtnike da ih popravi, pošto nekoliko godina prije poče u istočnim\nkrajevima i liši ih bezbrojne množine života, prelazeći iz mjesta u mjesto bez prestanka prema\nZapadu nevoljno širila.\nI nije protiv nje pomogao ni ljudski razbor, ni naredbe po kojima su grad od mnoge nečistoće\nslužbenici za to određeni čistili i u nj zabranjivali ući svakomu bolesniku, ni mnogi dani savjeti o\nčuvanju zdravlja; ni k tome ponizna zaklinjanja što ih, ne jednom nego mnogo puta, i u naloženim\nprocesijama i na druge načine vjernici Bogu zavapiše; te nekako u rano proljeće rečene godine\nona užasno započe, i na neobičan način, svoje bolne posljedice pokazivati. I nije to činila kao na\nIstoku gdje je, komu god je tekla krv na nos to bio očit znak neumitne smrti, nego su se u njezinu\npočetku javljale, jednako u muških i u ženskih, ili na preponama ili pod pazusima neke otekline, od\nkojih su jedne narastale kao obična jabuka, druge kao jaje, i neke više a neke manje, a puk ih je\nzvao micinama. I s ta dva spomenuta dijela tijela za kratko vrijeme počinjala se rečena smrtonosna\nmicina širiti i rasti bez iznimke po svim njegovim dijelovima; i poslije toga su se znaci rečene bolesti\npočinjali mijenjati tako da su se mnogima ruke i bedra, i svi drugi dijelovi tijela osipali crnim ili modrim\npjegama, u jednih krupnim i rijetkim, u drugih sitnim i gustim.\nDrugi tekst\nEmmanuel Carrère, Neki drugi životi\nNajedanput je primijetio i da su se vrane razbježale, da se više ne čuje pjev ptica. Tada je stigao\nval. Trenutak prije more je bilo nepomično, trenutak poslije sručavalo se na njega poput velikog\nnebodera. U djeliću sekunde pomislio je kako će umrijeti i kako neće biti vremena za patnju. Val ga\nje poklopio, odnio i zakotrljao u svojoj utrobi, taj mu se trenutak pretvorio u cijelu vječnost, ali onda je\nna leđima provirio iz vode. Proklizao je poput surfera iznad kuća, drveća, ceste. Zatim val krene na\ndrugu stranu, povlačeći ga prema pučini. Vidio je kako smjera prema urušenim zidovima o koje će\nse razbiti pa se refleksno uhvati za jednu palmu koju ispusti, zatim za drugu, koju bi isto tako ispustio\nda ga nešto tvrdo, neki komad ograde, nije prikovao za deblo. Oko njega silovitom brzinom hujalo je\npokućstvo, životinje, ljudi, grede, betonski blokovi. On zažmiri, pripremivši se da će ga smrskati neki\ntakav golemi otpad, i žmirio je tako sve dok se stravična tutnjava morske struje nije smirila i dok ne\nzaču nešto drugo, urlike ozlijeđenih muškaraca i žena, i dok nije shvatio da to nije bio kraj svijeta,\nda je živ i da prava mora tek počinje. Otvorio je oči, skliznuo na deblo do površine vode koja je bila\nposve crna, mutna.\nHRV B IK-2 D-S028\nHRV B IK-2 D-S028.indd 4 23.7.2015. 11:46:19\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite značenje Giovannija Boccaccia u razvoju književnosti na prijelazu iz srednjega vijeka\nu renesansu.\n• Smjestite prvi polazni tekst u kontekst književnoga djela i objasnite njegovu ulogu u djelu u cjelini.\nObjasnite što se dogodilo u polaznim tekstovima.\n• Usporedite prvi i drugi polazni tekst s obzirom na temu, temeljne probleme, ugođaj i\npripovjedačke postupke.\n• Objasnite kako se u djelu Dekameron prevladavaju životne teškoće.\n• Obrazložite svoje tvrdnje.\nHRV B IK-2 D-S028\nHRV B IK-2 D-S028.indd 5 23.7.2015. 11:46:19","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2015-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1063,"height":1474,"crop":{"x":0,"y":0,"width":1063,"height":1474}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2015-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1063,"height":1474,"crop":{"x":0,"y":0,"width":1063,"height":1474}}]},{"id":"hrvatski-a-2015-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2015,"schoolYear":"2014./2015.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2014/03/HRVA15jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2015-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRV A IK-2 D-S031.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte sljedeći tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nJerome David Salinger, Lovac u žitu\nNew York je jeziv kad se u njemu, u kasno doba noći, netko glasno smije na ulici. Čuje\nse na milje daleko. To uvijek djeluje na čovjeka tako da se osjeti strahovito potišten i\nosamljen. Osjetio sam neizdrživu želju da odem kući i malo naklapam sa starom Phoebe.\nPoslije izvjesnog vremena vožnje šofer i ja konačno smo se upustili u nešto kao razgovor.\nPrezime mu je bilo Horwitz. Bio je mnogo bolji čovjek od onog šofera s kojim sam se vozio\nranije iste večeri. Bilo kako bilo, palo mi je na pamet da bi možda on mogao znati nešto o\nonim patkama.\n- Hej, Horwitz – rekao sam – jeste li ikad prošli pored one lagune u Centralnom parku?\nDolje u južnom dijelu?\n- Pored čega?\n- Lagune. Onog kao malog jezera, tamo. Tamo gdje su one patke. Sigurno znate.\n- Aha. Pa šta je s tim?\n- E pa, znate one patke koje plivaju naokolo po njemu? Tamo u proljeće i uvijek? Znate li\nmožda, kojom srećom, kamo odlaze zimi?\n- Tko kamo odlazi?\n- Patke. Znate li, slučajno? Hoću da kažem, da li netko dolazi s kamionom ili tako nečim i\nodnosi ih, ili one odlete onako same od sebe? Odsele se na jug ili tako nešto?\nHRV A IK-2 D-S031\nHRV A IK-2 D-S031.indd 4 23.7.2015. 11:43:40\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Smjestite roman Lovac u žitu u književnopovijesni kontekst i objasnite pojam\nproza u trapericama.\n• Smjestite polazni tekst u sadržajni kontekst djela. Portretirajte Holdena na temelju djela u cjelini.\n• Prokomentirajte Holdenova razmišljanja i raspoloženje na temelju polaznoga teksta.\n• Protumačite pitanja o patkama i povežite ih s naslovom djela.\n• Obrazložite svoje tvrdnje.\nHRV A IK-2 D-S031\nHRV A IK-2 D-S031.indd 5 23.7.2015. 11:43:40","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2015-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1063,"height":1474,"crop":{"x":0,"y":0,"width":1063,"height":1474}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2015-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1063,"height":1474,"crop":{"x":0,"y":0,"width":1063,"height":1474}}]},{"id":"hrvatski-b-2014-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2014,"schoolYear":"2013./2014.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2013/03/HRVB14ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2014-ljetni-rok-skolski-esej/paper.pdf","sourceName":"HRVB Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedeni tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nHenrik Ibsen, Nora\nHELMER: Rado bih za tebe radio i dan i noć, Nora – radi tebe trpio bih svaku bijedu\ni nevolju. Ali nitko za voljenoga ne žrtvuje – svoju čast.\nNORA: To su učinili milijuni žena.\nHELMER: Ah, misliš i govoriš kao nerazumno dijete!\nNORA: Možda. A ti ne misliš i ne govoriš kao čovjek za koga bih se mogla vezati. Kad je\nprošao taj tvoj strah – ne zbog onoga što je prijetilo meni, nego zbog onoga čemu\nbi ti bio izvrgnut – kad je, dakle, prošao taj tvoj strah i kad se više nisi imao čega\nbojati, za tebe je bilo: nikom ništa! Kao da se ništa nije dogodilo. Opet sam, kao i\nprije bila tvoja ševa, tvoja lutka koju ćeš dvostruko pažljivo nositi na rukama, kad\nsam već tako krhka i lomna. (Ustaje.) Torvalde, u tom trenutku puklo mi je pred\nočima da sam čitavih osam godina ovdje živjela s jednim stranim čovjekom i da\nsam s njime rodila troje djece…Ta mi je misao nepodnošljiva! Sama bih sebe\nrastrgla.\nHELMER (teška srca): Vidim, vidim. Otvorio se ponor među nama… Ali, Nora, zar ga\nne bismo mogli premostiti?\nNORA: Kakva sam sada, nisam žena za te.\nHELMER: Imam snage da postanem drukčiji.\nNORA: Možda, kad ti se lutka oduzme.\nHELMER: Da se odvojim od tebe, da se rastanem s tobom – ne, Nora, ja to ne mogu pojmiti.\nNORA (ide u sobu lijevo): Utoliko je potrebnije da bude odmah. (Vraća se odjevena za put,\nu ruci joj mala torba koju stavlja na stolicu pokraj stola.)\nHELMER: Nora, Nora, ne sada! Čekaj do jutra!\nNORA (uzima zimski kaput): Ne mogu noćiti u kući strana čovjeka.\nHELMER: Ne bismo li mogli ostati ovdje kao brat i sestra?\nNORA (stavlja šešir na glavu): Znaš i sam da ne bi dugo trajalo. (Ogrće se šalom.) Zbogom\nTorvalde. Neću da se opraštam s djecom. Znam, uostalom, da su sada u boljim\nrukama nego što su moje. Kakva sam sada, ne mogu im biti ništa.\nHRV B IK-2 D-S022\n\u0018\nHRV B IK-2 D-S022.indd 4 29.1.2014 11:18:39\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite dramu Nora u kontekstu književnopovijesnoga razdoblja u kojemu je\nnastala. Odredite vrstu drame.\n• Smjestite polazni tekst u kontekst drame Nora. Objasnite na temelju polaznoga teksta uzrok,\ntijek i razrješenje temeljnoga dramskog sukoba. Objasnite kako je u drami Nora prikazan\nvanjski, a kako unutarnji sukob likova.\n• Prikažite odnos između glavnih likova u polaznome tekstu i objasnite kakvu preobrazbu\nproživljavaju likovi. Objasnite čega se Helmer najviše boji.\nProtumačite zašto se Nora ne želi oprostiti s djecom.\nProtumačite zašto Nora ne vjeruje Helmeru i ne pristaje na njegove uvjete.\n• Objasnite u čemu se Norina reakcija razlikuje od očekivanoga ponašanja žene u obitelji.\nIznesite svoje gledište o obiteljskim odnosima, dužnostima i pravu na slobodu pojedinca\nunutar obitelji.\n• Potkrijepite svoje tvrdnje citatima i/ili parafrazama iz polaznoga teksta te primjerima\niz djela u cjelini.\nHRV B IK-2 D-S022\n\u0018\nHRV B IK-2 D-S022.indd 5 29.1.2014 11:18:40","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2014-ljetni-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2014-ljetni-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-a-2014-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2014,"schoolYear":"2013./2014.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2013/03/HRVA14ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2014-ljetni-rok-skolski-esej/paper.pdf","sourceName":"HRVA Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedene tekstove nakon kojih slijede upute i smjernice za pisanje\nškolskoga eseja.\nPrvi tekst\nAntun Šoljan, Kratki izlet\nBilo je to negdje prvih godina poslije rata, kada se svima nama činilo da svijet počinje iz\npočetka, iz iskonske magme. Hrabro smo, sa svima drugima, pokušali vjerovati da se\nsve može iznova otkriti, osvijetliti novim smislom, i da se tu, na ovom komadiću tla, može\nodigrati potpuno nova drama. Činilo se da je sama zemlja razotkrila pred nama bijela brda\nsvoga tijela i dopustila nam da po njima bauljamo i vršljamo poput neznatnih ali plodonosnih\nkukaca. Činilo se da ima toliko nevinog tla na koje prije nas nije stupila ljudska noga. Činilo\nse da smo upravo mi pozvani da nakon razaranja nastavimo život, preuzmemo nasljeđe,\nokrunimo vjekove uspješnom sintezom, da ih dovršimo. Jedan od nas je, sjećam se, i\nrekao da to „netko crpe našu patnju da dovrši svijet”. Imali smo dojam da se napokon nešto\ndogađa.\nRatno pitanje „gdje smo?” i poratno „kamo ćemo?” izgubila su svoju oštrinu (sve smo više\nbili razni, na raznim mjestima, sve više kretali u raznim pravcima), u to vrijeme počeli smo\nse pitati opet jednom „odakle smo došli?”, a teza „treba se vratiti komadić puta da bismo se\nmogli zaletjeti dalje” postajala je parolom dana. Nećemo valjda počinjati uvijek od nulte točke,\nuvijek sve otpočetka, kao da nije bilo ničeg prije nas?\nHRV A IK-2 D-S022\n\u0018\nHRV A IK-2 D-S022.indd 4 27.1.2014 11:14:47\nDrugi tekst\nAntun Šoljan, Kratki izlet\nGdje sam? pitao sam se nijemo, stojeći u tom skamenjenom ničem, osjećajući da sam\nzauvijek izgubljen i da mi je od sviju nada, od svega znanja, od cijelog bića ostalo samo\npitanje: Gdje sam? Što je sa mnom? Što je sa svijetom?\n(...)\nMožda nikada i nije bilo drugog svijeta, rekao sam samome sebi, kao da se opravdavam.\nMožda sam u ovoj pustoši od početka, možda smo svi u njoj od početka, samo mi nije bilo\ndano da je vidim tako jasno kao sada. Možda se nikad nisam ni maknuo odavde. Možda\nnisam krenuo ni na kakav izlet. Možda je ovo zapravo blagovijest, spas. Možda je ovo ona\nkonačna sloboda kojoj su preci toliko težili, i ja sam na cilju.\nHRV A IK-2 D-S022\n\u0018\nHRV A IK-2 D-S022.indd 5 27.1.2014 11:14:47\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Smjestite autora i roman Kratki izlet u društveni i povijesni kontekst.\n• Predstavite polazne tekstove s obzirom na sadržaj i kompoziciju romana Kratki izlet.\n• Objasnite pripovjedačev doživljaj poslijeratnoga vremena.\nProtumačite značenje misli treba se vratiti komadić puta da bismo se mogli zaletjeti dalje.\nObjasnite simboliku riječi pustoš u kojoj se pripovjedač našao. Odredite ulogu retoričkih\npitanja i ponavljanja u polaznim tekstovima.\n• Usporedite „psihologiju klape” u romanu Kratki izlet i spoznaju da pripovjedač na kraju ostaje\nsam. Objasnite pitanje slobode u polaznim tekstovima i u romanu Kratki izlet.\n• Potkrijepite svoje tvrdnje citatima i/ili parafrazama iz polaznoga teksta te primjerima\niz djela u cjelini.\nHRV A IK-2 D-S022\n\u0018\nHRV A IK-2 D-S022.indd 6 27.1.2014 11:14:47","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2014-ljetni-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2014-ljetni-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2014-ljetni-rok-skolski-esej/page-6.png","page":6,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-b-2014-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2014,"schoolYear":"2013./2014.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2013/09/HRVB14jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2014-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRVB Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedeni tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nSofoklo, Antigona\nKreont:\nU srcu, sinko, tako treba suditi:\nSve volji svoga oca podređivati.\n(…)\nStog nikad, sinko, nemoj svoje pameti\nZa ljubav žene gubiti, već dobro znaj\nDa grozan to je zagrljaj kad supruga\nU kući bude žena zla. Ta može li\nBit gore rane no što loš je prijatelj?\nKo neprijatelja odbaci curu tu:\nU Hadu nek’ se udaje za nekoga!\nTa ja zatèkoh je gdje očevidno mi\nOd svega grada samo ona prkosi;\nA lašcem gradu neću se pokazati,\nVeć smaknut ću je. Stog nek’ Zeusa, roda svog\nČuvara, zove! Ako budem neposluh\nDopuštao u rodu, izvan roda će\nPorasti jače.\n(...)\nStog uvijek treba čvrst poredak braniti,\nA nipošto podleći ženi; ako već\nTo moramo, muškarac nek’ nas protjera\nNo da se kaže: slabiji od žena smo.\nZbor:\nDa, čini nam se, ne vara li starost nas,\nDa mudro zboriš to o čemu govoriš.\nHRV B IK-2 D-S019\n\u0018\nHRV B IK-2 D-S019.indd 4 27.1.2014 11:19:40\nHemon:\nMoj oče, bozi daju pamet ljudima\nOd svih dobara kao dobro najveće.\nA da ti sada ispravno ne govoriš,\nTo reći nit’ bih mogao nit’ umio.\nAl’ štošta mudro zna i drugom sinuti.\nOd tebe vidim bolje sve što kaže tko\nIl’ radi ili opet zna prekoriti.\nTvog oka pučanin se plaši: neće on\nIzreći što ti uhu ne bi godilo.\nA ja iz prikrajka to mogu slušati,\nTu djevu kako žali grad, što najgorom\nSad smrću gine sve zbog čina predivnog,\nA od svih žena najmanje zavređuje:\n(…)\nPa nije l’ za tô zlatnu čast zavrijedila?\nBaš takav tajni potiho se širi glas.\nA zà me, oče, nema blaga većega\nNa svijetu nego što je tvoja dobrobit.\nOd dobra glasa oca sretna ima li\nZa djecu veće sreće il’ od dječjega\nza oca? Stog ne pòmišljaj da pravo je\nTek to što kažeš ti, a drugo nikada.\nTko zà se misli da je mudar jedini\nA takav jezik ili um u drugoga\nDa nema, kad se otkrije, pokazat će\nPrazninu pustu. Al’ ni mudru nije baš\nSramota učiti i skroman ostati:\n(…)\nBaš tako tko na lađi konop jedreni\nPritegnuv čvrsto, nimalo ne popusti,\nTaj izvrnute dalje plovi palube.\nStog ù srcu popusti, preinači to!\nHRV B IK-2 D-S019\n\u0018\nHRV B IK-2 D-S019.indd 5 27.1.2014 11:19:40\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Smjestite djelo Antigona u književno razdoblje u kojemu je nastalo i odredite kojemu\nknjiževnomu rodu i vrsti pripada.\n• Opišite situaciju u kojoj su se našli Kreont i Hemon.\nObjasnite što Hemon naziva zlatnom čašću koju je zavrijedila njegova zaručnica.\n• Odredite razloge sukoba Kreonta i Hemona. Usporedite njihov dijalog s obzirom na obiteljske\nodnose i odnose prema narodu. Objasnite smisao Hemonove usporedbe na kraju polaznoga\nteksta.\n• Objasnite kako se u djelu Antigona razrješava sukob morala i zakona.\nIznesite svoje mišljenje o odnosu morala i zakona na temelju djela Antigona.\n• Potkrijepite svoje tvrdnje citatima i/ili parafrazama iz polaznoga teksta te primjerima\niz djela u cjelini.\nHRV B IK-2 D-S019\n\u0018\nHRV B IK-2 D-S019.indd 6 27.1.2014 11:19:40","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2014-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2014-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2014-jesenski-rok-skolski-esej/page-6.png","page":6,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-a-2014-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2014,"schoolYear":"2013./2014.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2013/09/HRVA14jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2014-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRVA Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedeni tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nMarin Držić, Dundo Maroje\nPOMET: (…) Ma se je trijeba s bremenom akomodavat\u0004; trijeba je bit vjertuozu\u0004 tko hoće\nrenjat\u0004 na svijetu. Kralj je čovjek od ljudi, kad se umije vladat. Nije ga imat dinâr, er vidim\nmnoge s dinarmi potištene; nije ga bit doktur, er vidim mnoge te brigate\u0004 fantastike\u0004; nije ga\nbit junak s mačem u ruci, er su ti većekrat ali ubijeni ali ih su pune tamnice; nije ga bit poeta\nni komedije umjet činit, er tizijem svak ore i na svaki ga pijer\u0004 hoće operat\u0004, kao bastaha\u0004,\na umjesto zahvaljenja da mu reku: „Ne valja ništa, iždeni\u0004!”, i da mu neprijatelji ostanu; nije\nga bit mužik, er tizijeh druzi čine pjet kad veću volju plakat imaju.\nTrijeba je bit pacijent10 i ugodit zlu bremenu, da se pak dobro brijeme uživa. Svakijem\nkami!11 Maro mi prijeti, a ja mu se s baretom12 u ruci klanjam; Tudešak me, moj idol, dviže\ns trpeze, s delicija! Srcem mučno idem – čijerom volentijero13. I tko k meni dođe: „Pomete,\nopravi mi”, – opravljam; „Pođ’ za mene”, – idem; konselj14 mi pita, – umijem mu ga dat; psuje\nme, – podnosim; ruga se mnom, – za dobro uzimljem. Ovaki ljudi renjaju. A merita15 moj\nprofumani16 trbuh da mu vjerno služim. Sve sam ove galantarije za njega naučio, er me nigda\nne izdava na dobru obroku; vazda je bio pripravljen, dispos17 ponijet.\n\u0004\ns bremenom se akomodavat – prilagoditi se vremenu\n\u0004\nvjertuoz – obdaren vrlinom, sposoban razumno i odlučno djelovati radi postizanja cilja\nsvladavanjem fortune, čovjek nazbilj\n\u0004\nrenjati – vladati\n\u0004\nbrigata – družina\n\u0004\nfantastik – čudan, nastran, neobičan\n\u0004\npijer – gozba, svadba\n\u0004\noperati – upotrijebiti\n\u0004\nbastah – nosač\n\u0004\niždeniti – silom odagnati, otjerati\npacijent – strpljiv\nSvakijem kami! – sa svakim se snaći\nbareta – kapa\nčijerom volentijero – licem dobrohotnim, radosnim\nkonselj – savjet\nmeritati – zaslužiti\nprofuman – namirisan\ndispos – spreman\nHRV A IK-2 D-S019\n\u0018\nHRV A IK-2 D-S019.indd 4 11.6.2014 14:49:25\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Smjestite dramu Dundo Maroje u kontekst hrvatske književnosti.\n• Predstavite temu, nositelje dramskih sukoba, mjesto i vrijeme radnje u drami Dundo Maroje.\nObjasnite ulogu Prologa Dugoga Nosa.\n• Odredite temu Pometova monologa. Objasnite tko je, prema Pometovu mišljenju, kralj od ljudi.\nPrikažite lik Pometa Trpeze, njegovu životnu filozofiju i njegov odnos prema drugim likovima.\n• Objasnite koje se Pometove osobine i danas smatraju poželjnima za društveni uspjeh.\nObrazložite tko bi, prema Vašemu mišljenju, mogao biti kralj od ljudi.\n• Potkrijepite svoje tvrdnje citatima i/ili parafrazama iz polaznoga teksta te primjerima\niz djela u cjelini.\nHRV A IK-2 D-S019\n\u0018\nHRV A IK-2 D-S019.indd 5 11.6.2014 14:49:25","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2014-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2014-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-b-2013-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2013,"schoolYear":"2012./2013.","term":"ljetni rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2012/03/HRVB13ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2013-ljetni-rok-skolski-esej/paper.pdf","sourceName":"02 HRVB Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedeni tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nMiroslav Krleža, Gospoda Glembajevi\nANGELIKA uzela je jednu stolicu i sjela vis-a-vis1 njega uzevši mu jednu ruku u svoje: Sve\nće biti dobro, Leone!\nLEONE: Ništa ne će biti dobro! Ti znaš, Beatrice: onog čovjeka tamo ja sam dotukao! Ja\nsam htio da oborim jednog tvrdog, ogromnog Glembaja, a ono ondje bio je jedan desperater\npred stečajem! Strašilo bijedno za ptice! Ja sam se tukao s jednom fikcijom! Stanka. Leone,\ndišući kratko i uzrujano, suhim ustima kao u ognjici, brzo i nervozno, ali ne glasno:\nSve je to kriminalno! Glembajevski kriminalno! Ja sam još učio nepravilne grčke glagole\nkad sam prvi put doživio kriminal! Bila se digla vjetrina i čupala stabla s korijenom, a mi dečki\nna botaničkom izletu, s bilinskom kantom i leptirskim mrežama, sklonismo se u jednu krčmu\nu šumi kraj kamenoloma. I tamo u tmini, u smrdljivoj krčmi, kod petrolejke, tamo su nekakvi\ncrni i rutavi ugljenari govorili kako nekome treba pustiti krv! „Ubiti ga treba”, tako je rekao\njedan. Ja sam kao u bunilu, nošen groznim strahom, potrčao u tminu, u noć, i u onoj vjetrini,\nu prolomu oblaka, po grmljavini, ja sam od straha vikao i trčao bez glave! Tamo sam prvi put\nstvarno doživio da se ljudi ubijaju! Onda sam se kretao svijetom s leptirskom mrežom u ruci\ni sa šafranovom lukovicom! A danas sam star i glup, danas sam bolestan, i još uvijek živim\nu krvavoj krčmi! O kad bih mogao da pobjegnem iz svega toga! Zvona u gradu. Ptica. Dan\nraste. Iz toga se ne može. Imala je stara Barboczyjeva pravo: Glembajevi su ubojice! Onaj\nvaraždinski Glembay koji drži remetinačku crkvu u ruci, on je u viničkoj šumi ubio i orobio\njednog kranjskog zlatara koji je vozio u Varaždin crkvenu zlatninu! To sam čuo od jednog\nglembajevskog kočijaša koji je služio još kod pokojnog Ferdinanda!\nANGELIKA: To je fama i legenda! To nema nikakve podloge!\nLEONE: O, Gospode Bože moj, zašto svi vi mislite uvijek na nekakvim podlogama?\nNikada ništa nema podloge! Ja sam to čuo od jednog kočijaša i to je za mene kroz čitavo\nmoje djetinjstvo bila najstvarnija stvarnost od svega, u čitavoj ovoj kući! (...)\n_____________________\nvis-a-vis – nasuprot, sučelice\nHRV B IK-2 D-S016\n\u0018\nHRV B IK-2 D-S016.indd 4 21.3.2013 14:20:53\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite Krležino dramsko stvaralaštvo na temelju trilogije Gospoda Glembajevi.\n• Smjestite polazni tekst u kontekst drame. Predstavite lik Leonea u obitelji Glembay i prikažite\ntemeljne dramske sukobe.\n• Rekonstruirajte na temelju dijaloga u polaznome tekstu događaje koji su obilježili Leoneovo\ndjetinjstvo i odrastanje. Prikažite čime je Leone zaokupljen i zaprepašten u polaznome tekstu i\nprotumačite rečenicu … i još uvijek živim u krvavoj krčmi!. Odredite ulogu Leoneova\npripovijedanja o događaju iz djetinjstva. Objasnite ulogu legende stare Barboczyjeve u\nkontekstu drame. Povežite glembajevsko podrijetlo i razvoj Leoneova lika.\n• Usporedite Krležine likove Filipa Latinovicza i Leonea Glembaja na temelju motiva povratka i\nunutarnjih nemira. Iznesite svoje mišljenje o tome može li se čovjek boriti protiv obiteljskoga\nnasljeđa.\nHRV B IK-2 D-S016\n\u0018\nHRV B IK-2 D-S016.indd 5 21.3.2013 14:20:53","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2013-ljetni-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2013-ljetni-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-a-2013-ljetni-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2013,"schoolYear":"2012./2013.","term":"ljetni rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2012/03/HRVA13ljeto.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2013-ljetni-rok-skolski-esej/paper.pdf","sourceName":"02 HRVA Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedene tekstove nakon kojih slijede upute i smjernice za pisanje\nškolskoga eseja.\nPrvi tekst\nMiroslav Krleža, Povratak Filipa Latinovicza\nSlušajući tu jednoličnu i praznu životnu shemu svoga kočijaša, Filip je osjećao spram\nJože Podravca neku neizrecivo indiferentnu daljinu. „Dvije stotine milijuna ovakvih iz drva\nizrezanih kočijaša živi ovdje po ovim livadama od Tihog oceana do ovih panonskih močvara:\nlica jednaka, ruke jednake, sudbine jednake.”\n(...)\n„Joža Podravec ima zingericu i šlingeraje, a on Filip, rješava stvari na simboličan način:\nigrajući se obojadisanim plohama kao formulama, rješavajući zapravo probleme jedne\napstraktne, potpuno imaginarne aritmetike. Jako je daleko između njega i ovog panonskog\nkočijaša: zapravo neshvatljivo daleko! Daleko je između njega i onog kasnosecesionističkog\nspomenika na kaptolskoj promenadi. I to su dva svijeta. A ona žuta graničarska, erarska,\nbarokna crkva ondje na livadi, i ona je svijet za sebe. Stoji tu kao neka vrsta utvrde u ovom\nblatu i govori već nekoliko stotina godina ovim Panoncima neke svoje osnovne programe i\nrezolucije, a bez ikakvog naročitog rezultata; način mišljenja ovih kočijaša nije se ni u čemu\nizmijenio sigurno već dvije hiljade godina. Taj čovjek pokraj njega na boku bliže je panonskoj\nprapojavi nego Matisseu! To je marvogojac doslovno, i kako je daleko od tih njegovih žuljavih\ndlanova do Filipova osjećaja tkanine ili svile među prstima! Sjede tu tako dva čovjeka na\nboku, ovakav nastrani neurastenik, slikarski sektaš, relativist, fauvist, kolorist, i govore istim\njezikom, a to su zapravo dva jezika i dva kontinenta!\nHRV A IK-2 D-S014\n\u0018\nHRV A IK-2 D-S014.indd 4 7.2.2013 11:29:14\nDrugi tekst\nMilutin Cihlar Nehajev, Bijeg\nGovorili smo o selu. Ja još nikad dosada nisam vidio pravoga sela ni pravoga seljaka,\nonoga što pozna samo svoju zemlju. Naš Primorac, ako i obrađuje vinograd, nije seljak\n(a nije valjda nikad ni bio); njegovo se zvanje mijenja prema potrebi: u mladosti je mornar,\nkasnije nadničari sa svojom lađicom ili radi oko vinograda. Uvijek je spreman da dohvati\nnešto bolje.\n(...)\nToša naveo razgovor na literaturu – i odmah došli mi u debatu.\n– Vi se svi tužite da se naše knjige ne prodaju, da književnik stradava. Ja ti kupujem\ngotovo svaku našu knjigu; pa znaš što mi se čini da je krivo svemu? Vi ste svi nekakvi užasni\nslabići; ne vjerujete ni u sebe ni u drugoga, opisujete uvijek neke nervozne i izmučene\nljude. A pogledaj ti nas ovdje što radimo po strani. Jedva ja razumijem to vaše umjetničko\nraspoloženje; a kako ćeš da se za nj zagrije široka masa puka? (Toša se sav zažari u\nraspravi i to mu izvrsno pristaje; njegova Anka gledala je u nj kao u svoj idol.)\n– Ti si, Toša, previdio da ta velika masa puka nas ne razumije zato što nas ne čita, pače\nšto nas ne može čitati. A da ima i manje analfabeta, jedva da bi tvoj seljak iz Zdenca imao\nkakav interes za lijepu knjigu.\nHRV A IK-2 D-S014\n\u0018\nHRV A IK-2 D-S014.indd 5 7.2.2013 11:29:14\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite poetike romana Bijeg i Povratak Filipa Latinovicza.\n• Smjestite polazne tekstove u kontekst romana. Portretirajte likove Filipa Latinovicza i Đure\nAndrijaševića na temelju polaznih tekstova te romana u cjelini.\n• Usporedite polazne tekstove i objasnite povezanost tema i problema. Prikažite čime su\nzaokupljeni Filip Latinovicz i Đuro Andrijašević u polaznim tekstovima. Protumačite Filipovu\nzabrinutost i Đurina zapažanja. Predstavite Filipove i Đurine sugovornike i njihove stavove na\ntemelju polaznih tekstova i romana u cjelini. Potkrijepite primjerima iz romana.\n• Protumačite u kakvu su odnosu umjetničko stvaralaštvo i društvena sredina te u kojoj se mjeri\nprožimaju umjetnička djela i oni kojima su namijenjena. Svoje tumačenje potkrijepite\nčitateljskim iskustvom i/ili primjerima iz romana.\nHRV A IK-2 D-S014\n\u0018\nHRV A IK-2 D-S014.indd 6 7.2.2013 11:29:14","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2013-ljetni-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2013-ljetni-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2013-ljetni-rok-skolski-esej/page-6.png","page":6,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-b-2013-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2013,"schoolYear":"2012./2013.","term":"jesenski rok","level":"B","archiveUrl":"./files/ncvvo/wp-content/uploads/2012/03/HRVB13jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-b-2013-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRVB Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":350,"max":500,"acceptedMin":315,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedene tekstove nakon kojih slijede upute i smjernice za pisanje školskoga\neseja.\nPrvi tekst\nVjenceslav Novak, Posljednji Stipančići\nZa Valpurgu nije bilo čovjeka koji bi mogao biti umniji, iskusniji i bolji od njezinoga muža.\nDobroćudna od prirode, a odgojena u roditeljskoj kući odgojem koji je gušio u ženskoj djeci\nsvaku samostalnost, podvrgla se vrlo lako njegovoj volji i bila u sebi uvjerena da ne može\npripadati nego samo njemu, da je svijet svake žene optočen ovako samo mužem koji ju je\nusrećio otevši je djevojaštvu. Ona se povrh toga divila njegovim gospodskim navikama što\nih je donio iz daleka svijeta (amo je spadalo npr. i to da je svaki dan mijenjao čisto rublje), i\nnjegovom kratkomu odrješitomu sudu o svim javnim ljudima, prilikama i poslovima; priviknula\nse da samo na izjavu njegove volje čeka i ona kao što i ostala služinčad u kući i da se svaka\nnjegova zapovijed vrši sa strahom i žurbom; napokon njegovo svakidanje čitanje i pisanje\nkojom bi prigodom domaće služavke morale čak i brbljave žene i živahnu djecu iz susjednih\nulica rastjerati – sve to ulijevaše joj osobito počitanje naprama njezinom zakonitomu drugu,\ndočim je njezina sloboda ugasnula malo-pomalo posve, i ona bila u njegovoj kući – slobodna\nropkinja.\nHRV B IK-2 D-S013\n\u0018\nHRV B IK-2 D-S013.indd 4 8.7.2013 15:01:21\nDrugi tekst\nHenrik Ibsen, Nora (Lutkina kuća)\nNORA: Moguće. Ali ti niti govoriš niti misliš kao muž kakvog bih si željela. Čim si prestao\npaničariti – ne zbog mene, nego zbog onog što si mislio da se tebi može dogoditi – kad je\nsve prošlo, ponašao si se kao da se ništa nije ni dogodilo. Što se tebe tiče, mogao si me\nvratiti na moje staro mjesto. Opet sam bila tvoja draga ptičica, tvoja lutka koju odsad moraš\njoš više maziti i paziti jer je tako krhka i lomljiva. (Ustajući.) U tom su mi se trenutku otvorile\noči. Osam sam godina živjela sa strancem, rodila s njim troje djece. Ne mogu to podnijeti!\nNajradije bih samu sebe rastrgla u sto komada!\nHelmer (tužno): Vidim, vidim. Između nas se otvorio ponor. Ali, Nora, mi ga možemo\npremostiti, zatrpati.\nNora: Ova žena kakva sam sad, ne može biti tvoja supruga.\nHelmer: Ja ću se promijeniti.\nNora: Možda – kad ti oduzmu lutku.\nHRV B IK-2 D-S013\n\u0018\nHRV B IK-2 D-S013.indd 5 8.7.2013 15:01:21\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Predstavite djela Posljednji Stipančići i Nora (Lutkina kuća) u kontekstu razdoblja u kojemu su\nnastala.\n• Smjestite polazne tekstove u sadržajni kontekst djela u cjelini. Prikažite strukturu djela u cjelini\ni uočite sličnosti i razlike.\n• Usporedite smisao sintagme slobodna ropkinja i rečenice Možda – kad ti oduzmu lutku u\nkarakterizaciji Valpurge i Nore. Objasnite ulogu oksimorona u prikazu Valpurge i ulogu\nmetafore u prikazu Nore.\n• Predstavite likove Ante Stipančića i Helmera i njihovu ulogu u obitelji. Argumentirajte svoje\nstavove i potkrijepite ih primjerima iz polaznih tekstova i djela u cjelini.\n• Usporedite suvremeni položaj žene u društvu s položajem žene u Ibsenovo i Novakovo\nvrijeme. Izrecite svoje mišljenje o tome jesu li Nora i Valpurga trebale i(li) mogle promijeniti svoj\npoložaj. Argumentirajte svoje stavove i potkrijepite ih primjerima.\nHRV B IK-2 D-S013\n\u0018\nHRV B IK-2 D-S013.indd 6 8.7.2013 15:01:21","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-b-2013-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2013-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-b-2013-jesenski-rok-skolski-esej/page-6.png","page":6,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]},{"id":"hrvatski-a-2013-jesenski-rok-skolski-esej","kind":"skolski-esej","partLabel":"Školski esej","year":2013,"schoolYear":"2012./2013.","term":"jesenski rok","level":"A","archiveUrl":"./files/ncvvo/wp-content/uploads/2012/03/HRVA13jesen.zip","paperUrl":"./files/interactive/croatian-writing/hrvatski-a-2013-jesenski-rok-skolski-esej/paper.pdf","sourceName":"HRVA Ispitna knjizica 2.pdf","durationMinutes":160,"wordRange":{"min":400,"max":600,"acceptedMin":360,"acceptedMax":null},"maxScore":40,"scoreMultiplier":1,"rubricId":"school-essay-legacy","taskText":"Pozorno pročitajte navedeni tekst nakon kojega slijede upute i smjernice za pisanje\nškolskoga eseja.\nSofoklo, Antigona\nTiresija\nPa znat ćeš kad umijeća moga čuješ znak.\nKad nà mjesto se staro, ptičje motrilo,\nGdje svaka dolijeće mi ptica, spustim ja,\nGlas ptičji nepoznat mi čujem, ljutome\nU bijesu, divljoj graji one kreštahu.\nRazabrah, jedna drugu čupa pandžama\nI kolje; lepet krila jasno čuo se.\nI odmah prepadoh se, kušah žrtvovat\nNa žrtveniku plamnom, ali ìz žrtve\nNe suknu plamen, nego se po pepelu\nMast ìz bedara cijedi, topi; puši se\nI prska a žuč uvis šiknu te se sva\nTu rasprsne; iz pretiline ovite,\nŠto rastopi se, kliznu kosti bedrene.\nTo od dječaka ovoga sve doznah ja\nZa gatanje da nema znaka òd žrtve:\nJer meni on je vodič a ja drugima.\nA to zbog tvoje volje boluje nam grad.\nTa svi su žrtvenici i sva ognjišta\nSad ptičje a i pseće hrane, paloga\nJadníka, sina Edipova, prepuni.\nPa onda bozi ùz žrtvu već molitve\nNe primaju nit plamena sa bedara.\nNit krešti ptica dobrokobno okusiv\nTe masne krvi poginula čovjeka.\nTo, dakle, sinko, uzmi sebi na pamet!\nTa griješiti je prirođeno ljudima;\nAl’ sagriješi li tko, on više čovjek lud\nNit nesretan bit neće ako, u zlo on\nZagreznuv, liječi se i nije uporan.\nSamovolja je grijeh zbog nerazbora.\nAl’ pusti mrtvog, poginula nè muči!\nJunaštvo li je ubit mrtva drugi put?\nDobro ti misleć, zborim; zbori l’ dobro tko,\nTog savjet slušat najveća je slast.\nHRV A IK-2 D-S015\n\u0018\nHRV A IK-2 D-S015.indd 4 8.7.2013 15:07:21\nUpute\nSvoj školski esej oblikujte kao zaokruženu cjelinu s uvodom, razradom i zaključkom.\nPazite da Vaš školski esej bude pravopisno i gramatički točan.\nSve smjernice morate uvrstiti u svoj školski esej.\nRedoslijed ponuđenih smjernica ne obvezuje Vas u oblikovanju školskoga eseja.\nSmjernice za pisanje školskoga eseja\n• Smjestite autora u književno razdoblje u kojemu je stvarao. Opišite značajke književne vrste\nkojoj pripada polazni tekst.\n• Smjestite polazni tekst u sadržajni kontekst djela. Predstavite temeljni zaplet djela i opišite\nkarakterne osobine glavnih likova. Potkrijepite primjerima iz djela.\n• Analizirajte odnos ljudskih i božanskih zakona na temelju Tiresijina monologa i objasnite na\nčemu su zasnovane Tiresijina mudrost i domišljatost. Prikažite Tiresijin odnos prema Kreontu i\npovežite ga s Tiresijinim etičkim načelima.\nPotkrijepite primjerima iz djela.\n• Protumačite ulogu retoričkoga pitanja Junaštvo li je ubit mrtva drugi put?. Obrazložite svoj stav\nprema Tiresijinim riječima iz polaznoga teksta.\nHRV A IK-2 D-S015\n\u0018\nHRV A IK-2 D-S015.indd 5 8.7.2013 15:07:21","sourceImages":[{"url":"./files/interactive/croatian-writing/hrvatski-a-2013-jesenski-rok-skolski-esej/page-4.png","page":4,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}},{"url":"./files/interactive/croatian-writing/hrvatski-a-2013-jesenski-rok-skolski-esej/page-5.png","page":5,"width":1091,"height":1502,"crop":{"x":0,"y":0,"width":1091,"height":1502}}]}]};
